LOCK TABLES `exam_questions` WRITE;
/*!40000 ALTER TABLE `exam_questions` DISABLE KEYS */;
INSERT INTO `exam_questions` VALUES
(1,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','vocabulary','B2',NULL,'The new vaccine proved highly ---- in clinical trials, reducing infection rates by nearly 90 percent.','[\"ambiguous\",\"obsolete\",\"redundant\",\"reluctant\",\"efficacious\"]',4,'Efficacious = etkili. Enfeksiyonu %90 azaltan bir aşı için olumlu ve etki bildiren tek sıfat bu. Ambiguous (belirsiz), redundant (gereksiz), obsolete (modası geçmiş) anlamı bozar.',0,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(2,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','vocabulary','B2',NULL,'Despite years of research, scientists have not yet been able to ---- the exact cause of the disease.','[\"postpone\",\"undermine\",\"pinpoint\",\"exaggerate\",\"abandon\"]',2,'Pinpoint = tam olarak tespit etmek. \'Kesin nedeni\' ifadesiyle birlikte kullanılır. Undermine (zayıflatmak) ve postpone (ertelemek) bağlama uymaz.',1,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(3,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','vocabulary','B2',NULL,'The committee decided to ---- the meeting until all members could attend.','[\"look into\",\"give in\",\"make up\",\"turn down\",\"put off\"]',4,'Put off = ertelemek. \'Herkes katılana kadar\' ifadesi zamanı ileri atmayı gösterir. Turn down reddetmek, look into incelemek demektir.',2,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(4,'[\"yds\",\"yokdil\",\"ielts\",\"toefl\",\"proficiency\"]','vocabulary','C1',NULL,'The economist argued that the government\'s policies would only ---- the gap between the rich and the poor.','[\"alleviate\",\"commemorate\",\"accommodate\",\"exacerbate\",\"illuminate\"]',3,'Exacerbate = kötüleştirmek, derinleştirmek. \'Only\' vurgusu eleştirel bir ton verir; alleviate (hafifletmek) tam tersi anlamdadır ve tuzak şıktır.',3,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(5,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','vocabulary','B2',NULL,'Many species are now ---- to extinction because their natural habitats are disappearing.','[\"accustomed\",\"indifferent\",\"vulnerable\",\"immune\",\"superior\"]',2,'Vulnerable to = -e karşı savunmasız. Immune to (bağışık) zıt anlamlı tuzaktır; accustomed to (alışkın) bağlama uymaz.',4,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(6,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','vocabulary','B1',NULL,'Our flight was delayed, so we had to ---- a hotel near the airport for the night.','[\"set off\",\"run out of\",\"bring up\",\"check into\",\"get over\"]',3,'Check into a hotel = otele giriş yapmak. Run out of (tükenmek), get over (atlatmak), set off (yola çıkmak) cümleye uymaz.',5,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(7,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','grammar','B2',NULL,'By the time the rescue team arrived, the fire ---- most of the building.','[\"destroys\",\"was destroying\",\"would destroy\",\"has destroyed\",\"had destroyed\"]',4,'\'By the time + geçmiş zaman\' yapısında daha önce tamamlanmış eylem past perfect (had + V3) ile anlatılır.',6,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(8,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','grammar','B2',NULL,'---- the heavy rain, the match went ahead as planned.','[\"Because of\",\"Unless\",\"Although\",\"Despite\",\"Whereas\"]',3,'Boşluktan sonra isim (the heavy rain) geliyor; zıtlık bildiren edat \'despite\' gerekir. \'Although\' cümle ister, \'because of\' zıtlık değil neden bildirir.',7,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(9,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','grammar','B2',NULL,'If the researchers ---- more funding, they could have completed the project on time.','[\"have received\",\"would receive\",\"receive\",\"received\",\"had received\"]',4,'Ana cümlede \'could have completed\' var: geçmişe dönük gerçek dışı koşul (Type 3). Yan cümlede past perfect kullanılır.',8,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(10,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','grammar','B2',NULL,'The report, ---- was published last week, has caused a lot of controversy.','[\"which\",\"whose\",\"where\",\"what\",\"that\"]',0,'Virgülle ayrılmış (non-defining) sıfat cümlesinde \'that\' kullanılamaz; nesneyi niteleyen \'which\' doğrudur.',9,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(11,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','grammar','C1',NULL,'Not only ---- the deadline, but he also forgot to inform his manager.','[\"he did miss\",\"missed he\",\"did he miss\",\"he missed\",\"has he missing\"]',2,'\'Not only\' cümle başında olduğunda devrik yapı gelir: yardımcı fiil + özne + fiil (did he miss).',10,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(12,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','grammar','B2',NULL,'The more you practise speaking, ---- you will become.','[\"more confident\",\"the confident\",\"the more confident\",\"the most confident\",\"most confident\"]',2,'\'The more ..., the more ...\' kalıbı: bir şey arttıkça diğeri de artar. İkinci yarı da \'the + comparative\' ile kurulur.',11,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(13,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','cloze','C1','Urban gardens are becoming increasingly popular in large cities. (1) ---- providing fresh produce, they also help reduce air pollution and create green spaces where neighbours can meet. However, their success largely depends (2) ---- the support of local authorities.','(1) numaralı boşluğa hangisi gelir?','[\"In spite of\",\"On behalf of\",\"In addition to\",\"Instead of\",\"Regardless of\"]',2,'Cümle ek fayda sayıyor (also help...). \'In addition to + V-ing\' = -e ek olarak. Instead of (yerine) ve in spite of (rağmen) anlamı bozar.',14,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(14,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','cloze','C1','Urban gardens are becoming increasingly popular in large cities. (1) ---- providing fresh produce, they also help reduce air pollution and create green spaces where neighbours can meet. However, their success largely depends (2) ---- the support of local authorities.','(2) numaralı boşluğa hangisi gelir?','[\"with\",\"at\",\"for\",\"on\",\"in\"]',3,'\'Depend on\' sabit bir fiil-edat kalıbıdır: -e bağlı olmak.',15,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(15,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','sentence_completion','B2',NULL,'Although electric cars are becoming cheaper, ----.','[\"their batteries have improved considerably in recent years\",\"governments are offering tax reductions to buyers\",\"many people are still worried about the limited number of charging stations\",\"they produce no exhaust emissions at all\",\"more models are available than ever before\"]',2,'\'Although\' zıtlık ister: arabalar ucuzluyor AMA insanlar hâlâ endişeli. Diğer şıklar elektrikli araçların lehine olup zıtlık kurmaz.',16,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(16,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','sentence_completion','B2',NULL,'Unless the city invests in public transport, ----.','[\"the new metro line was opened last year\",\"traffic congestion will continue to get worse\",\"buses were cheaper in the past\",\"more people have started cycling to work\",\"residents voted for a new mayor\"]',1,'\'Unless\' (-mezse) koşul bildirir; ana cümle gelecek zamanlı bir sonuç ister: \'will continue\'. Diğer şıklar zaman ve anlamca uymaz.',17,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(17,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','sentence_completion','C1',NULL,'So complex was the problem that ----.','[\"the engineers found it quite simple\",\"it was solved in a few minutes by a student\",\"even the most experienced engineers needed weeks to solve it\",\"nobody had ever heard of it before\",\"the company decided to hire more staff last year\"]',2,'\'So ... that\' sonuç bildirir: sorun o kadar karmaşıktı ki en deneyimli mühendisler bile haftalarca uğraştı. Diğer şıklar karmaşıklığın doğal sonucu değildir.',18,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(18,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','sentence_completion','B2',NULL,'----, the museum attracts thousands of visitors every summer.','[\"Although it is difficult to reach\",\"Unless it is renovated\",\"Since it was closed for repairs\",\"Even though tickets are free\",\"Located in the heart of the old town\"]',4,'Kısaltılmış sıfat cümlesi (Located in...) müzeyi niteleyip ziyaretçi çekmesinin nedenini verir. \'Although/even though\' zıtlık kurar ama cümlede zıtlık yok.',19,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(19,'[\"yds\",\"yokdil\",\"ydt\"]','translation','B2',NULL,'Scientists believe that regular exercise can significantly reduce the risk of heart disease.','[\"Bilim insanlar\\u0131 kalp hastal\\u0131\\u011f\\u0131n\\u0131n d\\u00fczenli egzersizle tamamen \\u00f6nlenebildi\\u011fini kan\\u0131tlad\\u0131.\",\"D\\u00fczenli egzersiz yapan bilim insanlar\\u0131n\\u0131n kalp hastal\\u0131\\u011f\\u0131 riski olduk\\u00e7a d\\u00fc\\u015f\\u00fckt\\u00fcr.\",\"Bilim insanlar\\u0131na g\\u00f6re kalp hastalar\\u0131 d\\u00fczenli olarak egzersiz yapmal\\u0131d\\u0131r.\",\"Bilim insanlar\\u0131 d\\u00fczenli egzersizin kalp hastal\\u0131\\u011f\\u0131 riskini \\u00f6nemli \\u00f6l\\u00e7\\u00fcde azaltabilece\\u011fine inan\\u0131yor.\",\"Kalp hastal\\u0131\\u011f\\u0131 riskini azaltmak i\\u00e7in bilim insanlar\\u0131 d\\u00fczenli egzersiz \\u00f6neriyor.\"]',3,'\'Believe that\' = inanıyor, \'can significantly reduce\' = önemli ölçüde azaltabilir. B şıkkı \'kanıtladı\' ve \'tamamen\' diyerek anlamı abartıyor; E şıkkı \'öneriyor\' diyerek fiili değiştiriyor.',20,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(20,'[\"yds\",\"yokdil\",\"ydt\"]','translation','B2',NULL,'Türkiye\'nin en kalabalık şehri olan İstanbul, iki kıta üzerinde kurulmuştur.','[\"Turkey\'s biggest city Istanbul was once built on two different continents.\",\"Istanbul, which is the most populous city in Turkey, is built on two continents.\",\"Being built on two continents, Istanbul became Turkey\'s largest city.\",\"Istanbul is one of the most crowded cities built between two continents.\",\"The population of Istanbul, a city on two continents, is the highest in the world.\"]',1,'Ara söz \'Türkiye\'nin en kalabalık şehri olan\' bir sıfat cümlesiyle (which is the most populous city in Turkey) çevrilir. D şıkkı neden sonuç ilişkisi ekliyor, E şıkkı \'dünyada\' diyerek anlamı değiştiriyor.',21,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(21,'[\"yds\",\"yokdil\"]','translation','C1',NULL,'Had the data been analysed more carefully, the researchers would have noticed the error much earlier.','[\"Veriler daha dikkatli analiz edilseydi, ara\\u015ft\\u0131rmac\\u0131lar hatay\\u0131 \\u00e7ok daha \\u00f6nce fark ederdi.\",\"Ara\\u015ft\\u0131rmac\\u0131lar\\u0131n hatay\\u0131 fark etmesi i\\u00e7in verilerin dikkatle analiz edilmesi gerekiyor.\",\"Veriler analiz edildi\\u011finde ara\\u015ft\\u0131rmac\\u0131lar hatan\\u0131n \\u00e7ok eski oldu\\u011funu fark etti.\",\"Veriler daha dikkatli analiz edilirse, ara\\u015ft\\u0131rmac\\u0131lar hatay\\u0131 daha \\u00f6nce fark edecek.\",\"Ara\\u015ft\\u0131rmac\\u0131lar verileri dikkatlice analiz ettikleri i\\u00e7in hatay\\u0131 erkenden fark etti.\"]',0,'\'Had the data been analysed\' devrik Type 3 koşuldur: geçmişte gerçekleşmemiş durum (edilseydi ... ederdi). B şıkkı olmuş bir olayı anlatıyor, E şıkkı gelecek zaman kullanıyor.',22,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(22,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','reading','B2','Bees play a vital role in agriculture. Around one third of the food we eat depends on pollination, and bees are responsible for most of it. In recent decades, however, bee populations have declined sharply in many parts of the world. Scientists point to several causes, including pesticide use, habitat loss and climate change. Some farmers have responded by planting wildflowers along the edges of their fields, which provide food and shelter for bees throughout the year.','According to the passage, why do some farmers plant wildflowers?','[\"To support bee populations by giving them food and shelter\",\"To replace crops that depend on pollination\",\"To increase the price of their crops\",\"To attract tourists to their farms\",\"To reduce their use of pesticides\"]',0,'Son cümle cevabı açıkça veriyor: kır çiçekleri arılara yıl boyunca \'food and shelter\' sağlar. Pestisit metinde neden olarak geçiyor, çözüm olarak değil.',23,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(23,'[\"yds\",\"yokdil\",\"ydt\",\"ielts\",\"toefl\",\"proficiency\"]','reading','B2','Bees play a vital role in agriculture. Around one third of the food we eat depends on pollination, and bees are responsible for most of it. In recent decades, however, bee populations have declined sharply in many parts of the world. Scientists point to several causes, including pesticide use, habitat loss and climate change. Some farmers have responded by planting wildflowers along the edges of their fields, which provide food and shelter for bees throughout the year.','The word \'declined\' in the passage is closest in meaning to ----.','[\"multiplied\",\"stabilised\",\"recovered\",\"decreased\",\"migrated\"]',3,'Decline = azalmak (decrease). \'Sharply\' ile birlikte keskin bir düşüşü anlatır. Recovered ve multiplied zıt anlamlı tuzaklardır.',24,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(24,'[\"yds\",\"yokdil\",\"ielts\",\"toefl\",\"proficiency\"]','reading','C1','The concept of a four-day working week has gained traction in several countries. Proponents argue that shorter weeks lead to higher productivity, better mental health and lower carbon emissions from commuting. A large trial in the United Kingdom found that most participating companies maintained their output while employees reported less stress. Critics, however, caution that the model may not suit every sector; hospitals and schools, for instance, cannot simply close for an extra day.','What is the main purpose of the passage?','[\"To prove that every company should adopt a four-day week\",\"To argue that productivity always falls when hours are reduced\",\"To explain why hospitals are closed on Fridays\",\"To describe the history of working hours in the UK\",\"To present the benefits of a four-day week alongside its limitations\"]',4,'Metin önce savunucuların görüşlerini ve deney sonucunu, ardından eleştirileri veriyor: dengeli bir sunum. \'Prove\' ve \'always\' gibi kesin ifadeler metinde desteklenmiyor.',25,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(25,'[\"yds\",\"yokdil\",\"ielts\",\"toefl\",\"proficiency\"]','reading','C1','The concept of a four-day working week has gained traction in several countries. Proponents argue that shorter weeks lead to higher productivity, better mental health and lower carbon emissions from commuting. A large trial in the United Kingdom found that most participating companies maintained their output while employees reported less stress. Critics, however, caution that the model may not suit every sector; hospitals and schools, for instance, cannot simply close for an extra day.','It can be inferred from the passage that the UK trial ----.','[\"only included hospitals and schools\",\"did not lead to a significant loss of output for most companies\",\"showed that critics were completely right\",\"increased carbon emissions from commuting\",\"was cancelled because employees felt stressed\"]',1,'\'Most participating companies maintained their output\' = çoğu şirket üretimini korudu, yani önemli bir kayıp yaşanmadı. Diğer şıklar metinle çelişiyor.',26,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(26,'[\"yds\",\"ydt\"]','dialogue','B1',NULL,'Emma: I\'ve been offered a job in Berlin, but I don\'t speak any German.\nLeo: ----\nEmma: That\'s true. Most of my colleagues would speak English anyway.','[\"Berlin is the capital of Germany, isn\'t it?\",\"I have never been to Berlin myself.\",\"German is a very difficult language to learn.\",\"You should never accept a job abroad.\",\"Well, a lot of international companies there work in English.\"]',4,'Emma\'nın cevabı (\'That\'s true... English anyway\') Leo\'nun İngilizcenin iş dili olduğunu söylediğini gösterir. E şıkkı endişeyi artırır ve \'That\'s true\' ile desteklenemez.',27,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(27,'[\"yds\",\"ydt\"]','dialogue','B2',NULL,'Doctor: Your test results look fine, but you seem quite tired.\nPatient: ----\nDoctor: Then try to switch off your phone an hour before bed.','[\"I\'ve been having trouble sleeping; I usually check messages until midnight.\",\"Can I get a copy of my test results?\",\"I feel great, I sleep nine hours every night.\",\"I don\'t like taking medicine.\",\"My sister is also a doctor.\"]',0,'Doktorun tavsiyesi (telefonu yatmadan önce kapat) hastanın uyku ve telefon kullanımıyla ilgili bir sorun anlattığını gösterir.',28,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(28,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','paragraph','B2',NULL,'Plastic waste is one of the most serious environmental problems of our time. Every year, millions of tonnes of plastic end up in the oceans, harming marine life. ----. As a result, several countries have banned single-use plastic bags and straws.','[\"Oceans cover more than seventy percent of the Earth\'s surface\",\"Some people prefer paper bags because they look nicer\",\"Plastic was invented at the beginning of the twentieth century\",\"Many sea animals mistake small plastic pieces for food and die\",\"Recycling centres are usually closed at weekends\"]',3,'Boşluk, deniz canlılarına verilen zararı açıklamalı ve \'As a result... banned\' sonucuna zemin hazırlamalı. Diğer şıklar konu dışı bilgiler veriyor.',29,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(29,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','paragraph','C1',NULL,'Learning a second language changes the brain in measurable ways. ----. For example, bilingual people often perform better on tasks that require switching attention between different activities. Some studies even suggest that speaking two languages may delay the onset of dementia.','[\"Research shows that it strengthens areas linked to attention and memory\",\"Some languages have more than twenty vowel sounds\",\"It is easier to learn a language as a child than as an adult\",\"Many schools in Europe teach English from primary level\",\"Translators usually work with at least three languages\"]',0,'Boşluktan sonra gelen \'For example\' dikkat değiştirme becerisinden bahsediyor; boşluk bu örneği kapsayan genel bir iddia olmalı: dikkat ve hafıza bölgelerinin güçlenmesi.',30,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(30,'[\"yds\",\"yokdil\",\"ydt\"]','irrelevant','B2',NULL,'(I) Coffee is one of the most traded commodities in the world. (II) It is grown in more than seventy countries, mainly in tropical regions. (III) Brazil alone produces about a third of the global supply. (IV) Tea, on the other hand, originated in China thousands of years ago. (V) Changes in weather in coffee-growing areas can therefore affect prices worldwide.','[\"I\",\"II\",\"III\",\"IV\",\"V\"]',3,'Paragraf kahve üretimi ve ticaretini anlatıyor. IV. cümle çayın kökenine geçerek akışı bozuyor; V. cümle \'therefore\' ile III\'e bağlanıyor.',31,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(31,'[\"yds\",\"yokdil\",\"ydt\"]','irrelevant','C1',NULL,'(I) Remote work has transformed the daily lives of millions of employees. (II) Without long commutes, many workers report having more time for family and exercise. (III) The first computer mouse was made of wood. (IV) At the same time, some people feel isolated and miss informal chats with colleagues. (V) Companies are therefore experimenting with hybrid models that combine home and office work.','[\"I\",\"II\",\"III\",\"IV\",\"V\"]',2,'Paragraf uzaktan çalışmanın etkilerini tartışıyor. III. cümle bilgisayar faresinin tarihine dair ilgisiz bir bilgi.',32,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(32,'[\"ielts\",\"toefl\",\"proficiency\"]','vocabulary','C1',NULL,'The lecturer gave a ---- overview of the topic, covering its history, current debates and future directions in just twenty minutes.','[\"superficial\",\"tedious\",\"fragile\",\"reluctant\",\"comprehensive\"]',4,'Tarihi, güncel tartışmaları ve geleceği kapsayan bir özet \'comprehensive\' (kapsamlı) olur. Superficial (yüzeysel) \'covering its history, current debates...\' ile çelişir.',33,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(33,'[\"ielts\",\"toefl\",\"proficiency\"]','grammar','B2',NULL,'Hardly ---- the lecture started when the fire alarm went off.','[\"have\",\"was\",\"had\",\"has\",\"did\"]',2,'\'Hardly ... when\' kalıbı devrik past perfect ile kurulur: Hardly had the lecture started when... (ders yeni başlamıştı ki...).',34,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(34,'[\"ielts\",\"toefl\",\"yds\",\"proficiency\"]','reading','B2','Coral reefs cover less than one percent of the ocean floor, yet they support about a quarter of all marine species. Rising sea temperatures cause corals to expel the tiny algae living inside them, a process known as bleaching. Bleached corals are not dead, but they are under severe stress and may die if temperatures stay high for too long.','According to the passage, bleached corals ----.','[\"are always dead\",\"can still survive if conditions improve in time\",\"cover a quarter of the ocean floor\",\"produce more algae than healthy corals\",\"are found only in cold water\"]',1,'\'Bleached corals are not dead... may die if temperatures stay high for too long\': sıcaklık zamanında düşerse hayatta kalabilirler. \'Always dead\' metinle çelişiyor.',35,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(35,'[\"yds\",\"yokdil\",\"proficiency\"]','vocabulary','C1',NULL,'The findings of the study are ---- with earlier research, which also linked poor sleep to weaker memory.','[\"incompatible\",\"exhausted\",\"reluctant\",\"consistent\",\"indifferent\"]',3,'\'Which also linked\' (o da ilişkilendirmişti) önceki araştırmalarla uyumu gösterir: consistent with = ile tutarlı. Incompatible tam tersidir.',36,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(36,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','grammar','B2',NULL,'The students were asked ---- their mobile phones during the exam.','[\"not using\",\"don\'t use\",\"not use\",\"not to use\",\"to not using\"]',3,'\'Ask someone (not) to do something\' kalıbı: olumsuz emir \'not to + V1\' ile verilir. Edilgen yapıda da aynı kalır: were asked not to use.',37,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(37,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','sentence_completion','C1',NULL,'The medicine was withdrawn from the market ----.','[\"so that more patients could buy it\",\"as soon as it became the best-selling drug\",\"after it was found to cause serious side effects in some patients\",\"because it had been extremely effective\",\"even though doctors had never prescribed it\"]',2,'Bir ilacın piyasadan çekilmesinin mantıklı nedeni ciddi yan etkilerdir. B ve C şıkları neden sonuç ilişkisini tersine çeviriyor.',38,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(38,'[\"ydt\"]','dialogue','B1',NULL,'Can: Are you coming to the concert on Saturday?\nMert: ----\nCan: Oh, that\'s a pity. Maybe next time then.','[\"Of course, I\'ve already bought my ticket!\",\"What time does it start?\",\"I\'d love to, but I have to study for my exam.\",\"Who is playing?\",\"Saturday is my favourite day.\"]',2,'Can\'ın \'That\'s a pity. Maybe next time\' demesi Mert\'in gelemeyeceğini gösterir. B şıkkı olumlu bir cevap olduğu için \'pity\' ile uyuşmaz.',39,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(39,'[\"yds\",\"yokdil\"]','translation','C1',NULL,'Bu çalışmanın amacı, sosyal medya kullanımının gençlerin uyku düzeni üzerindeki etkisini incelemektir.','[\"The aim of this study is to examine the effect of social media use on young people\'s sleep patterns.\",\"This study aims to reduce young people\'s use of social media before sleeping.\",\"This study shows that young people who use social media sleep less.\",\"The aim of social media is to change the sleep patterns of young people.\",\"Young people\'s sleep patterns were examined by social media users in this study.\"]',0,'\'Amacı ... incelemektir\' = The aim ... is to examine. B şıkkı bir sonuç iddia ediyor, E şıkkı amacı \'azaltmak\' olarak değiştiriyor.',40,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(40,'[\"lgs\"]','dialogue','A2',NULL,'Ayşe: Would you like to come to my birthday party on Saturday?\nCan: ----. I have to visit my grandparents.','[\"I\'d love to, but I can\'t\",\"I\'m going to bring a cake\",\"That sounds great, see you there\",\"Yes, of course I will\"]',0,'Can davete gelemeyeceğini söylüyor ve sebep veriyor. Kibarca reddetmenin kalıbı: \"I\'d love to, but I can\'t\". Diğer seçenekler kabul ediyor.',41,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(41,'[\"lgs\"]','dialogue','A2',NULL,'Mert: How often do you surf the Net?\nEce: ----','[\"Because it is fun\",\"For two hours\",\"Twice a day, usually after school\",\"On my computer\"]',2,'\"How often\" sıklık sorar. Cevap sıklık bildirmeli: twice a day. \"For two hours\" süre, \"because\" sebep bildirir.',42,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(42,'[\"lgs\"]','vocabulary','A2',NULL,'My brother always helps my mother in the kitchen. He ---- the table before dinner every evening.','[\"takes\",\"does\",\"makes\",\"sets\"]',3,'\"Set the table\" sofrayı kurmak demek. Ev işleri ünitesinin kalıp ifadesi.',43,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(43,'[\"lgs\"]','grammar','A2',NULL,'If it rains tomorrow, we ---- the picnic.','[\"cancel\",\"will cancel\",\"cancelled\",\"are cancelling\"]',1,'Gelecekle ilgili koşul: If + şimdiki zaman, will + fiil.',44,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(44,'[\"lgs\"]','reading','A2','Hi Ali,\nOur science project about volcanoes is due next week, and we haven\'t finished it yet. Let\'s meet at the library on Saturday at 2 pm. Can you bring the poster paper?\nZeynep','Which of the following is TRUE according to the message?','[\"They will meet on Sunday morning.\",\"Zeynep has finished the project.\",\"Zeynep wants to meet at the library.\",\"The project is about animals.\"]',2,'Mesajda \"Let\'s meet at the library on Saturday at 2 pm\" yazıyor. Proje volkanlarla ilgili, bitmemiş, gün Cumartesi.',45,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(45,'[\"lgs\"]','reading','A2','DURING AN EARTHQUAKE\nDROP to the ground.\nCOVER your head under a strong table.\nHOLD ON until the shaking stops.\nStay away from windows!','What is the poster about?','[\"A safety rule for earthquakes\",\"A school trip to a museum\",\"A new library opening\",\"A cooking competition\"]',0,'\"Drop, cover and hold on\" depremde yapılacakları anlatır; afiş bir güvenlik kuralıdır.',46,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(46,'[\"lgs\"]','vocabulary','A2',NULL,'Teenagers usually like ---- time with their friends at weekends.','[\"to spend money\",\"spend on\",\"spent\",\"spending\"]',3,'\"Like\" fiilinden sonra -ing kullanılır: like spending time.',47,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(47,'[\"lgs\"]','dialogue','A2',NULL,'Waiter: Are you ready to order?\nCustomer: ----','[\"I\'m fine, thanks.\",\"It costs ten liras.\",\"No, the restaurant is closed.\",\"Yes, I\'ll have the vegetable soup, please.\"]',3,'Sipariş sorusuna verilecek doğal cevap sipariş vermektir.',48,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(48,'[\"lgs\"]','grammar','A2',NULL,'Kerem is ---- student in our class. He always gets full marks.','[\"the most hardworking\",\"more hardworking\",\"hardworking than\",\"as hardworking\"]',0,'Bir grubun içinde en: the most + sıfat (üstünlük derecesi).',49,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(49,'[\"lgs\"]','reading','A2','FREE-TIME ACTIVITIES OF 8th GRADERS\nPlaying video games: 40%\nDoing sports: 25%\nWatching TV: 20%\nReading books: 15%','According to the chart, which activity do most students prefer?','[\"Playing video games\",\"Doing sports\",\"Reading books\",\"Watching TV\"]',0,'Tabloda en yüksek yüzde (%40) video oyunlarına ait.',50,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(50,'[\"lgs\"]','dialogue','A2',NULL,'Selin: Hello, can I speak to Mr. Aydın, please?\nSecretary: ----','[\"He is fifty years old.\",\"Yes, I\'m speaking English.\",\"Just a moment, I\'ll put you through.\",\"Goodbye, have a nice day.\"]',2,'Telefonda birini istemek. Uygun cevap \"Hold on / I\'ll put you through\".',51,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(51,'[\"lgs\"]','vocabulary','A2',NULL,'Strong winds and heavy rain hit the city last night. It was a terrible ----.','[\"storm\",\"sunrise\",\"drought\",\"heatwave\"]',0,'Kuvvetli rüzgar ve yağmur bir fırtınayı (storm) anlatır. Doğal afetler ünitesi.',52,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(52,'[\"lgs\"]','dialogue','A2',NULL,'Emre: How about going to the cinema this evening?\nMert: ----. I have a science project to finish.','[\"Sure, let\'s meet at seven\",\"I\'ve already seen it twice\",\"What a great idea\",\"Sorry, I can\'t make it\"]',3,'Mert\'in bir projesi var, yani daveti reddediyor. Kibar ret kalıbı: Sorry, I can\'t make it.',53,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(53,'[\"lgs\"]','dialogue','A2',NULL,'Zeynep: Could you help me with my English homework?\nAli: ----. Let\'s start with the first question.','[\"Of course, I\'d be happy to\",\"It was very difficult\",\"No, I don\'t like English\",\"I\'m sorry, I\'m not free\"]',0,'Ali ardından \'Let\'s start\' diyor; demek ki kabul ediyor. Kabul kalıbı: Of course, I\'d be happy to.',54,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(54,'[\"lgs\"]','dialogue','A2',NULL,'Selin: I\'m sorry, but I broke your pencil.\nDeniz: ----. I have another one.','[\"Never mind\",\"Congratulations\",\"Good luck\",\"Help yourself\"]',0,'Özrü kabul edip önemsizleştirmek için \'Never mind\' (önemli değil) denir.',55,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(55,'[\"lgs\"]','vocabulary','A2',NULL,'My best friend is very ----. She always tells the truth and never breaks her promises.','[\"lazy\",\"reliable\",\"rude\",\"selfish\"]',1,'Hep doğruyu söyleyen ve sözünü tutan biri güvenilirdir: reliable.',56,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(56,'[\"lgs\"]','vocabulary','A2',NULL,'Before you ---- the vegetables, wash them carefully under cold water.','[\"borrow\",\"download\",\"chop\",\"invite\"]',2,'Sebzelerle yapılan mutfak eylemi \'chop\' (doğramak).',57,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(57,'[\"lgs\"]','vocabulary','A2',NULL,'Don\'t share your password with anyone. It is important for online ----.','[\"tourism\",\"safety\",\"furniture\",\"weather\"]',1,'Şifre paylaşmamak internet güvenliğiyle ilgili: online safety.',58,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(58,'[\"lgs\"]','vocabulary','A2',NULL,'Bungee jumping is too ---- for me. I prefer safe activities like hiking.','[\"boring\",\"cheap\",\"dangerous\",\"peaceful\"]',2,'Güvenli aktiviteleri tercih ettiğini söylüyor; bungee jumping onun için tehlikeli: dangerous.',59,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(59,'[\"lgs\"]','grammar','A2',NULL,'I ---- my room every Saturday, and my brother does the dishes.','[\"tidied\",\"tidy\",\"am tidy\",\"tidies\"]',1,'Her cumartesi yapılan rutin, özne \'I\': geniş zaman, yalın fiil: tidy.',60,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(60,'[\"lgs\"]','grammar','A2',NULL,'Earthquakes are ---- than storms because we can\'t predict them.','[\"the most dangerous\",\"most dangerous\",\"more dangerous\",\"dangerouser\"]',2,'İki şey karşılaştırılıyor ve \'than\' var. Uzun sıfat: more dangerous.',61,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(61,'[\"lgs\"]','grammar','A2',NULL,'Last summer we ---- to Cappadocia and took a hot air balloon ride.','[\"go\",\"have go\",\"going\",\"went\"]',3,'\'Last summer\' geçmiş zaman ister: go → went.',62,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(62,'[\"lgs\"]','reading','A2','Hi, I\'m Kerem. I\'m a big fan of science. Every Wednesday after school, I go to the science club. We do experiments and learn about natural forces like earthquakes and floods. Last week we built a small model of a safe house. Next month, our club is going to visit the planetarium in Ankara.','Which of the following is TRUE according to the text?','[\"Kerem goes to the science club every day\",\"They built a real house last week\",\"Kerem doesn\'t like science\",\"Kerem\'s club is going to visit a planetarium\"]',3,'Metnin sonunda \'Next month, our club is going to visit the planetarium\' deniyor.',63,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(63,'[\"lgs\"]','reading','A2','Hi, I\'m Kerem. I\'m a big fan of science. Every Wednesday after school, I go to the science club. We do experiments and learn about natural forces like earthquakes and floods. Last week we built a small model of a safe house. Next month, our club is going to visit the planetarium in Ankara.','When does Kerem go to the science club?','[\"Every morning\",\"On Wednesdays after school\",\"At the weekend\",\"Only in summer\"]',1,'\'Every Wednesday after school\' ifadesi cevabı veriyor.',64,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(64,'[\"lgs\"]','reading','A2','Online Safety Rules\n1. Never share your home address.\n2. Use strong passwords with numbers and symbols.\n3. Don\'t accept friend requests from strangers.\n4. Tell an adult if something online makes you uncomfortable.','Which rule is NOT mentioned in the poster?','[\"Turn off your computer at night\",\"Tell an adult about problems\",\"Don\'t accept requests from strangers\",\"Use strong passwords\"]',0,'Afişte bilgisayarı kapatmakla ilgili bir kural yok; diğer üçü listede var.',65,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(65,'[\"lgs\"]','reading','A2','Tourism in Turkey\nMany tourists visit Turkey every year. Antalya is famous for its beaches, Cappadocia for its fairy chimneys and Istanbul for its history. Most visitors come in summer, but winter is the best time for Erzurum because of skiing.','Why do people visit Erzurum in winter?','[\"To swim in the sea\",\"To see fairy chimneys\",\"To visit old palaces\",\"To go skiing\"]',3,'Metne göre Erzurum kış için en iyisi \'because of skiing\'.',66,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(66,'[\"lgs\"]','dialogue','A2',NULL,'Mom: Can you set the table, please?\nAyşe: ----. Where are the forks?','[\"Sure, no problem\",\"I\'ve already eaten\",\"It\'s not my turn\",\"I\'m doing my homework\"]',0,'Ayşe çatalları soruyor; yani masayı kurmayı kabul ediyor: Sure, no problem.',67,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(67,'[\"ielts\",\"toefl\"]','vocabulary','B2',NULL,'Urban planners argue that green spaces can significantly ---- the stress levels of city residents.','[\"aggravate\",\"allocate\",\"alleviate\",\"accumulate\"]',2,'Yeşil alanlar stresi azaltır: alleviate (hafifletmek). Aggravate kötüleştirir, diğerleri anlamsız.',68,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(68,'[\"ielts\",\"toefl\"]','vocabulary','B2',NULL,'The lecturer gave a ---- overview of the topic before discussing the details.','[\"verbose\",\"concise\",\"fragile\",\"reluctant\"]',1,'Detaylardan önce verilen kısa özet: concise (öz).',69,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(69,'[\"ielts\",\"toefl\"]','vocabulary','B2',NULL,'Remote work has become increasingly ---- since the pandemic, with many companies adopting hybrid models.','[\"obsolete\",\"scarce\",\"trivial\",\"prevalent\"]',3,'Uzaktan çalışma yaygınlaştı: prevalent (yaygın).',70,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(70,'[\"ielts\",\"toefl\"]','grammar','B2',NULL,'Had the researchers collected more data, their conclusions ---- more reliable.','[\"had been\",\"would be being\",\"will be\",\"would have been\"]',3,'Devrik third conditional (Had + V3) → sonuç kısmı \'would have been\'.',71,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(71,'[\"ielts\",\"toefl\"]','grammar','B2',NULL,'Not only ---- the price of housing, but it has also affected public transport.','[\"has tourism increased\",\"tourism has increased\",\"tourism increased\",\"did tourism increasing\"]',0,'\'Not only\' cümle başındaysa devrik yapı gelir: has tourism increased.',72,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(72,'[\"ielts\",\"toefl\"]','grammar','B1',NULL,'The number of students studying abroad ---- steadily over the last decade.','[\"has risen\",\"have risen\",\"is rising since\",\"rose up\"]',0,'\'The number of\' tekil özne; \'over the last decade\' present perfect: has risen.',73,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(73,'[\"ielts\",\"toefl\"]','sentence_completion','B2',NULL,'Although the city invested heavily in cycle lanes, ----.','[\"it was a successful project\",\"the cycle lanes were very popular\",\"many residents still prefer to drive to work\",\"more people started cycling to work\"]',2,'\'Although\' zıtlık kurar: yatırıma rağmen insanlar hâlâ araba kullanıyor.',74,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(74,'[\"ielts\",\"toefl\"]','sentence_completion','B2',NULL,'Unless governments take immediate action, ----.','[\"the summit had been successful\",\"renewable energy was very cheap\",\"we reduced emissions last year\",\"global temperatures will continue to rise\"]',3,'\'Unless\' + present → sonuç gelecekte (will). Anlamca da uygun olan bu.',75,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(75,'[\"ielts\",\"toefl\"]','reading','B2','Sleep researchers have found that teenagers\' internal clocks shift later during adolescence, making it biologically difficult for them to fall asleep before 11 pm. Schools that delayed their start times by just one hour reported improved attendance, fewer car accidents among teenage drivers and better grades in morning classes.','What is the main idea of the passage?','[\"Teenagers are lazier than adults\",\"Later school start times can benefit teenagers\",\"Morning classes should be cancelled\",\"Car accidents are caused by schools\"]',1,'Paragraf, gençlerin biyolojik saatinin geç kaydığını ve okulu geç başlatmanın faydalarını anlatıyor.',76,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(76,'[\"ielts\",\"toefl\"]','reading','B2','Sleep researchers have found that teenagers\' internal clocks shift later during adolescence, making it biologically difficult for them to fall asleep before 11 pm. Schools that delayed their start times by just one hour reported improved attendance, fewer car accidents among teenage drivers and better grades in morning classes.','According to the passage, which was NOT reported by schools that started later?','[\"Higher fees for parents\",\"Fewer car accidents\",\"Better morning grades\",\"Better attendance\"]',0,'Ücretlerden hiç söz edilmiyor; diğer üçü metinde sayılıyor.',77,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(77,'[\"ielts\",\"toefl\"]','reading','B1','The town library has introduced a \'Library of Things\'. Instead of books, members can borrow tools, sewing machines, camping equipment and even musical instruments for up to two weeks. The aim is to reduce waste and help people save money on items they rarely use.','Why did the library start the \'Library of Things\'?','[\"To reduce waste and save people money\",\"To replace all its books\",\"To sell old equipment\",\"To teach people music\"]',0,'Son cümle amacı açıkça veriyor: reduce waste and help people save money.',78,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(78,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','vocabulary','B2',NULL,'The government has decided to ---- the new regulations until the economic situation becomes more stable.','[\"undermine\",\"dominate\",\"illuminate\",\"accelerate\",\"postpone\"]',4,'Ekonomi düzelene kadar düzenlemeleri ertelemek: postpone.',79,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(79,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','vocabulary','C1',NULL,'Despite the ---- evidence presented in court, the jury was not convinced of the defendant\'s guilt.','[\"conclusive\",\"spontaneous\",\"unanimous\",\"circumstantial\",\"redundant\"]',3,'\'Despite\' zıtlık kurar; jüri ikna olmadıysa delil dolaylıydı: circumstantial. Conclusive (kesin) zıtlığı bozar.',80,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(80,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','grammar','B2',NULL,'By the time the rescue team arrived, the fire ---- most of the forest.','[\"was destroying\",\"had destroyed\",\"has destroyed\",\"would destroy\",\"destroys\"]',1,'\'By the time\' + past simple → daha önce tamamlanan eylem past perfect: had destroyed.',81,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(81,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','grammar','B2',NULL,'---- the new drug proved effective in early trials, scientists remain cautious about its long-term effects.','[\"So that\",\"Even though\",\"As long as\",\"Unless\",\"Because\"]',1,'Etkili olmasına rağmen temkinliler: zıtlık bağlacı \'Even though\'.',82,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(82,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','sentence_completion','B2',NULL,'If more funding had been allocated to early-warning systems, ----.','[\"people evacuate their homes quickly\",\"the systems are working well now\",\"the government had built new dams\",\"the damage caused by the flood could have been reduced\",\"the flood will cause less damage\"]',3,'Third conditional (had been allocated) → could have been reduced.',83,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(83,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','translation','B2',NULL,'Araştırmacılar, düzenli egzersizin yaşlı yetişkinlerde hafıza kaybını önemli ölçüde yavaşlatabileceğini öne sürüyor.','[\"Researchers have proved that older adults never lose memory if they exercise.\",\"Researchers suggest that regular exercise can significantly slow memory loss in older adults.\",\"Older adults who suggest exercise to researchers slow their memory loss.\",\"Memory loss in older adults is caused by a lack of regular exercise, say researchers.\",\"Regular exercise is suggested by older adults to researchers for memory.\"]',1,'Özne (araştırmacılar), fiil (öne sürüyor = suggest), modal (-ebileceğini = can) ve \'önemli ölçüde\' (significantly) birebir karşılanan seçenek A.',84,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(84,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','dialogue','B1',NULL,'Mert: I\'ve been offered a job in Berlin, but I\'m not sure whether to accept it.\nAylin: ----\nMert: The salary is great, but I\'d have to leave my family behind.','[\"What\'s making you hesitate?\",\"Is the job in Istanbul?\",\"Why did you reject the offer?\",\"I\'ve never been to Berlin.\",\"Congratulations, when do you start?\"]',0,'Mert\'in cevabı tereddüdünün sebeplerini açıklıyor; soru da \'Seni tereddüde düşüren ne?\' olmalı.',85,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(85,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','cloze','B2','Coffee was first discovered in Ethiopia, (1) ---- legend says a goat herder noticed his animals becoming energetic after eating certain berries. (2) ---- the fifteenth century, it was being grown in Yemen.','(1) boşluğu için en uygun seçenek hangisidir?','[\"when\",\"which\",\"whose\",\"where\",\"what\"]',3,'Bir yer (Ethiopia) tanımlanıyor: where.',86,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(86,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','paragraph','B2',NULL,'Bees play a crucial role in agriculture. ---- In fact, about one third of the food we eat depends on pollination. Without bees, the prices of fruit and vegetables would rise dramatically.','[\"Beekeeping is a popular hobby in Turkey.\",\"Some people are afraid of being stung.\",\"Honey has been used as medicine for centuries.\",\"Many crops rely on them for pollination.\",\"Wasps are often confused with bees.\"]',3,'Boşluktan sonra \'In fact … depends on pollination\' geliyor; boşluk tozlaşma fikrini girmeli.',87,1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(87,'[\"yds\",\"yokdil\",\"ydt\",\"proficiency\"]','irrelevant','B2',NULL,'(I) Social media allows people to stay connected across long distances. (II) However, excessive use has been linked to anxiety among teenagers. (III) The first smartphone was released in 1994. (IV) Some experts therefore recommend limiting screen time. (V) Schools are also starting to teach digital wellbeing.','[\"I\",\"II\",\"III\",\"IV\",\"V\"]',2,'Paragraf sosyal medyanın etkileri ve önlemler hakkında; ilk akıllı telefonun tarihi (III) akışı bozuyor.',88,1,'2026-10-03 04:21:53','2026-10-03 04:21:53');
/*!40000 ALTER TABLE `exam_questions` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `lessons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `lessons` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `unit_id` bigint(20) unsigned NOT NULL,
  `title` varchar(255) NOT NULL,
  `skill` varchar(20) NOT NULL DEFAULT 'mixed',
  `kind` varchar(20) NOT NULL DEFAULT 'lesson',
  `position` int(10) unsigned NOT NULL DEFAULT 0,
  `xp_reward` smallint(5) unsigned NOT NULL DEFAULT 15,
  `is_premium` tinyint(1) NOT NULL DEFAULT 0,
  `story_id` bigint(20) unsigned DEFAULT NULL,
  `scenario_key` varchar(255) DEFAULT NULL,
  `exercises` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`exercises`)),
  `meta` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`meta`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `lessons_unit_id_foreign` (`unit_id`),
  CONSTRAINT `lessons_unit_id_foreign` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `lessons` WRITE;
/*!40000 ALTER TABLE `lessons` DISABLE KEYS */;
INSERT INTO `lessons` VALUES
(1,1,'Kelimeler','vocabulary','lesson',0,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"hello\",\"merhaba\"],[\"goodbye\",\"ho\\u015f\\u00e7a kal\"],[\"name\",\"isim\"],[\"friend\",\"arkada\\u015f\"],[\"student\",\"\\u00f6\\u011frenci\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"teacher\\\" ne demek?\",\"options\":[\"yorgun\",\"\\u015fehir\",\"\\u00f6\\u011fretmen\",\"isim\"],\"answer\":2,\"audio\":\"teacher\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Nice to meet you\",\"options\":[\"Nice to meet you\",\"Nice to see you\",\"Night to meet you\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Benim ad\\u0131m Deniz ve ben bir \\u00f6\\u011frenciyim.\",\"answer\":\"My name is Deniz and I am a student\",\"alternatives\":[],\"tiles\":[\"I\",\"is\",\"Deniz\",\"My\",\"friend\",\"am\",\"name\",\"student\",\"a\",\"and\",\"country\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"teacher\",\"\\u00f6\\u011fretmen\"],[\"country\",\"\\u00fclke\"],[\"city\",\"\\u015fehir\"],[\"happy\",\"mutlu\"],[\"tired\",\"yorgun\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"mutlu\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"happy\",\"friend\",\"goodbye\",\"city\"],\"answer\":0},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Nice to meet you, Mr Brown.\",\"translation\":\"Tan\\u0131\\u015ft\\u0131\\u011f\\u0131m\\u0131za memnun oldum, Bay Brown.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"She is my best friend\",\"answer\":\"She is my best friend\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(2,1,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I ___ from Antalya.\",\"options\":[\"am\",\"is\",\"are\"],\"answer\":0,\"hint\":\"I \\u2192 am\"},{\"type\":\"fill\",\"prompt\":\"My teacher ___ very kind.\",\"options\":[\"am\",\"is\",\"are\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"We ___ in the same class.\",\"options\":[\"am\",\"is\",\"are\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"___ you a student?\",\"options\":[\"Am\",\"Is\",\"Are\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"O benim arkada\\u015f\\u0131m.\",\"answer\":\"She is my friend\",\"alternatives\":[\"She\'s my friend\",\"He is my friend\",\"He\'s my friend\"],\"tiles\":[\"She\",\"is\",\"am\",\"friend\",\"are\",\"my\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"My\",\"sister\",\"are\",\"a\",\"doctor\"],\"error_index\":2,\"options\":[\"is\",\"am\",\"be\"],\"answer\":0,\"explanation_tr\":\"\\\"My sister\\\" tekil (o) oldu\\u011fu i\\u00e7in \\\"is\\\" kullan\\u0131l\\u0131r. \\\"Are\\\" you, we, they i\\u00e7indir. Do\\u011frusu: My sister is a doctor.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'m happy to meet you.\",\"translation\":\"Seninle tan\\u0131\\u015ft\\u0131\\u011f\\u0131ma mutluyum.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(3,1,'Kelime oyunu','vocabulary','words',2,15,0,NULL,NULL,'[]','{\"game\":\"match\",\"words\":[{\"word\":\"hello\",\"translation\":\"merhaba\"},{\"word\":\"goodbye\",\"translation\":\"ho\\u015f\\u00e7a kal\"},{\"word\":\"name\",\"translation\":\"isim\",\"example\":\"My name is Deniz and I am a student.\"},{\"word\":\"friend\",\"translation\":\"arkada\\u015f\",\"example\":\"She is my best friend\"},{\"word\":\"student\",\"translation\":\"\\u00f6\\u011frenci\",\"example\":\"My name is Deniz and I am a student.\"},{\"word\":\"teacher\",\"translation\":\"\\u00f6\\u011fretmen\",\"example\":\"My teacher is very kind.\"},{\"word\":\"country\",\"translation\":\"\\u00fclke\"},{\"word\":\"city\",\"translation\":\"\\u015fehir\"},{\"word\":\"happy\",\"translation\":\"mutlu\",\"example\":\"I\'m happy to meet you.\"},{\"word\":\"tired\",\"translation\":\"yorgun\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(4,1,'Dinle ve konuş','listening','lesson',3,15,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Okulun ilk g\\u00fcn\\u00fc. Yeni bir s\\u0131n\\u0131f arkada\\u015f\\u0131 yan\\u0131na geliyor.\",\"lines\":[{\"who\":\"Emma\",\"text\":\"Hi! I\'m Emma. What\'s your name?\"}],\"options\":[\"My name is Ali. Nice to meet you!\",\"I am name Ali.\",\"Name me Ali.\"],\"answer\":0,\"note_tr\":\"\\u0130smini s\\u00f6ylerken \\\"My name is \\u2026\\\" ya da k\\u0131saca \\\"I\'m \\u2026\\\" dersin. \\\"Nice to meet you\\\" ile bitirmek \\u00e7ok do\\u011fal durur.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"We\'re friends\",\"options\":[\"We\'re friends\",\"Where friends\",\"Were friends\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"How are you\",\"answer\":\"How are you\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Hi, I\'m Can. I\'m from Bursa.\",\"translation\":\"Merhaba, ben Can. Bursal\\u0131y\\u0131m.\"},{\"type\":\"translate\",\"prompt\":\"Biz \\u0130zmirliyiz.\",\"answer\":\"We are from Izmir\",\"alternatives\":[\"We\'re from Izmir\"],\"tiles\":[\"from\",\"We\",\"are\",\"is\",\"Izmir\",\"in\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I am from Turkey\",\"answer\":\"I am from Turkey\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Where are you from?\",\"translation\":\"Nerelisin?\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
