(7,2,'Kelimeler','vocabulary','lesson',0,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"mother\",\"anne\"],[\"father\",\"baba\"],[\"brother\",\"erkek karde\\u015f\"],[\"sister\",\"k\\u0131z karde\\u015f\"],[\"grandmother\",\"b\\u00fcy\\u00fckanne\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"grandfather\\\" ne demek?\",\"options\":[\"ebeveynler\",\"b\\u00fcy\\u00fckbaba\",\"erkek karde\\u015f\",\"teyze \\/ hala\"],\"answer\":1,\"audio\":\"grandfather\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"She\'s got a brother\",\"options\":[\"She\'s got a brother\",\"She\'s got a mother\",\"She got a brother\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"B\\u00fcy\\u00fckannem Trabzon\'da ya\\u015f\\u0131yor.\",\"answer\":\"My grandmother lives in Trabzon\",\"alternatives\":[],\"tiles\":[\"Trabzon\",\"grandmother\",\"grandmother\",\"in\",\"lives\",\"aunt\",\"My\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"grandfather\",\"b\\u00fcy\\u00fckbaba\"],[\"uncle\",\"amca \\/ day\\u0131\"],[\"aunt\",\"teyze \\/ hala\"],[\"cousin\",\"kuzen\"],[\"parents\",\"ebeveynler\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"kuzen\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"father\",\"aunt\",\"sister\",\"cousin\"],\"answer\":3},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I have got two cousins in Ankara.\",\"translation\":\"Ankara\'da iki kuzenim var.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"His sister is a doctor\",\"answer\":\"His sister is a doctor\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(8,2,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I ___ got a little brother.\",\"options\":[\"have\",\"has\",\"am\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"My father ___ got a blue car.\",\"options\":[\"have\",\"has\",\"is\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"This is Ece. ___ brother is ten.\",\"options\":[\"His\",\"Her\",\"Their\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"My parents love ___ garden.\",\"options\":[\"his\",\"its\",\"their\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"K\\u0131z karde\\u015fimin bir kedisi var.\",\"answer\":\"My sister has got a cat\",\"alternatives\":[\"My sister has a cat\",\"My sister\'s got a cat\"],\"tiles\":[\"a\",\"My\",\"have\",\"her\",\"cat\",\"sister\",\"has\",\"got\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"She\",\"have\",\"got\",\"two\",\"sisters\"],\"error_index\":1,\"options\":[\"has\",\"is\",\"having\"],\"answer\":0,\"explanation_tr\":\"He \\/ she \\/ it ile \\\"has got\\\" kullan\\u0131l\\u0131r. \\\"Have\\\" I, you, we, they i\\u00e7indir. Do\\u011frusu: She has got two sisters.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"This is my family.\",\"translation\":\"Bu benim ailem.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(9,2,'Kelime oyunu','vocabulary','words',2,15,0,NULL,NULL,'[]','{\"game\":\"memory\",\"words\":[{\"word\":\"mother\",\"translation\":\"anne\",\"example\":\"My mother is a teacher.\"},{\"word\":\"father\",\"translation\":\"baba\",\"example\":\"My father has got a blue car.\"},{\"word\":\"brother\",\"translation\":\"erkek karde\\u015f\",\"example\":\"I\'ve got one brother and one sister.\"},{\"word\":\"sister\",\"translation\":\"k\\u0131z karde\\u015f\",\"example\":\"His sister is a doctor\"},{\"word\":\"grandmother\",\"translation\":\"b\\u00fcy\\u00fckanne\",\"example\":\"My grandmother lives in Trabzon.\"},{\"word\":\"grandfather\",\"translation\":\"b\\u00fcy\\u00fckbaba\"},{\"word\":\"uncle\",\"translation\":\"amca \\/ day\\u0131\"},{\"word\":\"aunt\",\"translation\":\"teyze \\/ hala\"},{\"word\":\"cousin\",\"translation\":\"kuzen\"},{\"word\":\"parents\",\"translation\":\"ebeveynler\",\"example\":\"My parents love their garden.\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(10,2,'Dinle ve konuş','listening','lesson',3,15,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Arkada\\u015f\\u0131n telefonundaki aile foto\\u011fraf\\u0131n\\u0131 soruyor.\",\"lines\":[{\"who\":\"Lily\",\"text\":\"Who is the man in this photo?\"}],\"options\":[\"He\'s my uncle. He lives in Germany.\",\"He my uncle is.\",\"His is uncle.\"],\"answer\":0,\"note_tr\":\"Bir ki\\u015fiyi tan\\u0131t\\u0131rken \\\"He\'s my \\u2026\\\" ya da \\\"This is my \\u2026\\\" kal\\u0131b\\u0131 en do\\u011fal\\u0131d\\u0131r.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Their house is big\",\"options\":[\"Their house is big\",\"They\'re house is big\",\"There house is big\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I have got two cousins\",\"answer\":\"I have got two cousins\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'ve got one brother and one sister.\",\"translation\":\"Bir erkek, bir k\\u0131z karde\\u015fim var.\"},{\"type\":\"translate\",\"prompt\":\"Onlar\\u0131n ad\\u0131 ne?\",\"answer\":\"What are their names\",\"alternatives\":[\"What\'s their name\",\"What is their name\"],\"tiles\":[\"What\",\"is\",\"their\",\"they\",\"names\",\"are\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"His name is Murat\",\"answer\":\"His name is Murat\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"My mother is a teacher.\",\"translation\":\"Annem \\u00f6\\u011fretmen.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
