(13,3,'Kelimeler','vocabulary','lesson',0,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"book\",\"kitap\"],[\"pen\",\"t\\u00fckenmez kalem\"],[\"pencil\",\"kur\\u015fun kalem\"],[\"notebook\",\"defter\"],[\"desk\",\"s\\u0131ra\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"board\\\" ne demek?\",\"options\":[\"\\u00f6dev\",\"tahta\",\"silgi\",\"kur\\u015fun kalem\"],\"answer\":1,\"audio\":\"board\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Open your books\",\"options\":[\"Open your books\",\"Open your box\",\"Opens your books\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bu kitaplar s\\u0131ram\\u0131n \\u00fcst\\u00fcnde.\",\"answer\":\"These books are on my desk\",\"alternatives\":[],\"tiles\":[\"desk\",\"classroom\",\"books\",\"my\",\"on\",\"are\",\"These\",\"board\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"board\",\"tahta\"],[\"bag\",\"\\u00e7anta\"],[\"eraser\",\"silgi\"],[\"classroom\",\"s\\u0131n\\u0131f\"],[\"homework\",\"\\u00f6dev\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"s\\u0131n\\u0131f\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"pen\",\"classroom\",\"eraser\",\"notebook\"],\"answer\":1},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Open your notebook, please.\",\"translation\":\"Defterini a\\u00e7 l\\u00fctfen.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"That is my bag\",\"answer\":\"That is my bag\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(14,3,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"___ pen is mine. (elimde)\",\"options\":[\"This\",\"These\",\"Those\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Look at ___ birds in the sky!\",\"options\":[\"this\",\"that\",\"those\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"I need ___ eraser.\",\"options\":[\"a\",\"an\",\"the\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"___ talk in the library!\",\"options\":[\"No\",\"Don\'t\",\"Not\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Kitaplar\\u0131n\\u0131z\\u0131 a\\u00e7\\u0131n.\",\"answer\":\"Open your books\",\"alternatives\":[\"Open your books please\"],\"tiles\":[\"books\",\"Open\",\"your\",\"the\",\"open\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"These\",\"books\",\"is\",\"very\",\"interesting\"],\"error_index\":2,\"options\":[\"are\",\"am\",\"be\"],\"answer\":0,\"explanation_tr\":\"\\\"These books\\\" \\u00e7o\\u011ful oldu\\u011fu i\\u00e7in fiil de \\u00e7o\\u011ful olmal\\u0131: These books are very interesting.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Can I borrow your pencil?\",\"translation\":\"Kur\\u015fun kalemini \\u00f6d\\u00fcn\\u00e7 alabilir miyim?\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(15,3,'Kelime oyunu','vocabulary','words',2,15,0,NULL,NULL,'[]','{\"game\":\"choice\",\"words\":[{\"word\":\"book\",\"translation\":\"kitap\"},{\"word\":\"pen\",\"translation\":\"t\\u00fckenmez kalem\",\"example\":\"This pen is mine. (elimde)\"},{\"word\":\"pencil\",\"translation\":\"kur\\u015fun kalem\",\"example\":\"Can I borrow your pencil?\"},{\"word\":\"notebook\",\"translation\":\"defter\",\"example\":\"Open your notebook, please.\"},{\"word\":\"desk\",\"translation\":\"s\\u0131ra\",\"example\":\"These books are on my desk.\"},{\"word\":\"board\",\"translation\":\"tahta\"},{\"word\":\"bag\",\"translation\":\"\\u00e7anta\",\"example\":\"That is my bag\"},{\"word\":\"eraser\",\"translation\":\"silgi\",\"example\":\"I need an eraser.\"},{\"word\":\"classroom\",\"translation\":\"s\\u0131n\\u0131f\"},{\"word\":\"homework\",\"translation\":\"\\u00f6dev\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(16,3,'Dinle ve konuş','listening','lesson',3,15,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Derste \\u00f6\\u011fretmen bir soru sordu ama anlamad\\u0131n.\",\"lines\":[{\"who\":\"Mr Green\",\"text\":\"What is the answer to number five?\"}],\"options\":[\"Sorry, can you repeat the question, please?\",\"What? Again!\",\"I not understand.\"],\"answer\":0,\"note_tr\":\"Anlamad\\u0131\\u011f\\u0131nda kibarca tekrar istemek: \\\"Can you repeat that, please?\\\" ya da \\\"Sorry, I don\'t understand.\\\"\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Those are my pencils\",\"options\":[\"Those are my pencils\",\"These are my pencils\",\"Those are my pencil\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Close the door please\",\"answer\":\"Close the door please\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Sorry, I don\'t understand.\",\"translation\":\"\\u00d6z\\u00fcr dilerim, anlam\\u0131yorum.\"},{\"type\":\"translate\",\"prompt\":\"\\u015eu \\u00e7anta senin mi?\",\"answer\":\"Is that your bag\",\"alternatives\":[\"Is that bag yours\"],\"tiles\":[\"Is\",\"this\",\"that\",\"bag\",\"are\",\"your\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Where is my notebook\",\"answer\":\"Where is my notebook\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Can you repeat that, please?\",\"translation\":\"Tekrar eder misiniz l\\u00fctfen?\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
