(19,4,'Kelimeler','vocabulary','lesson',0,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"get up\",\"kalkmak\"],[\"have breakfast\",\"kahvalt\\u0131 yapmak\"],[\"go to school\",\"okula gitmek\"],[\"come home\",\"eve gelmek\"],[\"do homework\",\"\\u00f6dev yapmak\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"watch TV\\\" ne demek?\",\"options\":[\"okula gitmek\",\"televizyon izlemek\",\"her zaman\",\"asla\"],\"answer\":1,\"audio\":\"watch TV\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"It\'s half past three\",\"options\":[\"It\'s half past three\",\"It\'s quarter past three\",\"It\'s half past two\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Genellikle yedide kalkar\\u0131m.\",\"answer\":\"I usually get up at seven\",\"alternatives\":[],\"tiles\":[\"get\",\"I\",\"usually\",\"seven\",\"never\",\"at\",\"go to bed\",\"up\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"watch TV\",\"televizyon izlemek\"],[\"go to bed\",\"yatmak\"],[\"always\",\"her zaman\"],[\"sometimes\",\"bazen\"],[\"never\",\"asla\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"bazen\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"sometimes\",\"come home\",\"always\",\"have breakfast\"],\"answer\":0},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"She always has breakfast with her family.\",\"translation\":\"O her zaman ailesiyle kahvalt\\u0131 yapar.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"We never watch TV in the morning\",\"answer\":\"We never watch TV in the morning\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(20,4,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"He ___ to work by bus.\",\"options\":[\"go\",\"goes\",\"going\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"She ___ like coffee.\",\"options\":[\"don\'t\",\"doesn\'t\",\"isn\'t\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"___ you play basketball?\",\"options\":[\"Do\",\"Does\",\"Are\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"My brother ___ his homework after dinner.\",\"options\":[\"do\",\"does\",\"doing\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Her sabah \\u00e7ay i\\u00e7erim.\",\"answer\":\"I drink tea every morning\",\"alternatives\":[],\"tiles\":[\"morning\",\"drinks\",\"tea\",\"the\",\"every\",\"drink\",\"I\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"She\",\"don\'t\",\"like\",\"fish\"],\"error_index\":1,\"options\":[\"doesn\'t\",\"not\",\"isn\'t\"],\"answer\":0,\"explanation_tr\":\"He \\/ she \\/ it ile olumsuzda \\\"doesn\'t\\\" kullan\\u0131l\\u0131r; \\\"don\'t\\\" I, you, we, they i\\u00e7indir. Do\\u011frusu: She doesn\'t like fish.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I have breakfast at eight.\",\"translation\":\"Sekizde kahvalt\\u0131 yapar\\u0131m.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(21,4,'Kelime oyunu','vocabulary','words',2,15,0,NULL,NULL,'[]','{\"game\":\"truefalse\",\"words\":[{\"word\":\"get up\",\"translation\":\"kalkmak\",\"example\":\"I usually get up at seven.\"},{\"word\":\"have breakfast\",\"translation\":\"kahvalt\\u0131 yapmak\",\"example\":\"I have breakfast at eight.\"},{\"word\":\"go to school\",\"translation\":\"okula gitmek\"},{\"word\":\"come home\",\"translation\":\"eve gelmek\"},{\"word\":\"do homework\",\"translation\":\"\\u00f6dev yapmak\"},{\"word\":\"watch TV\",\"translation\":\"televizyon izlemek\",\"example\":\"We never watch TV in the morning\"},{\"word\":\"go to bed\",\"translation\":\"yatmak\",\"example\":\"What time do you go to bed?\"},{\"word\":\"always\",\"translation\":\"her zaman\",\"example\":\"She always has breakfast with her family.\"},{\"word\":\"sometimes\",\"translation\":\"bazen\"},{\"word\":\"never\",\"translation\":\"asla\",\"example\":\"We never watch TV in the morning\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(22,4,'Dinle ve konuş','listening','lesson',3,15,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir arkada\\u015f\\u0131n hafta i\\u00e7i program\\u0131n\\u0131 soruyor.\",\"lines\":[{\"who\":\"Sam\",\"text\":\"What do you usually do after school?\"}],\"options\":[\"I usually do my homework and then I play football.\",\"I am usually do homework.\",\"Usually I doing homework.\"],\"answer\":0,\"note_tr\":\"Rutinler i\\u00e7in geni\\u015f zaman: \\\"I usually do \\u2026\\\". S\\u0131kl\\u0131k zarf\\u0131 fiilden \\u00f6nce gelir.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"He takes a shower\",\"options\":[\"He takes a shower\",\"He takes a flower\",\"He takes the car\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"She works in a bank\",\"answer\":\"She works in a bank\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"What time do you go to bed?\",\"translation\":\"Saat ka\\u00e7ta yatars\\u0131n?\"},{\"type\":\"translate\",\"prompt\":\"O asla ge\\u00e7 kalmaz.\",\"answer\":\"She is never late\",\"alternatives\":[\"She\'s never late\",\"He is never late\",\"He\'s never late\"],\"tiles\":[\"late\",\"never\",\"never\",\"is\",\"She\",\"does\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I go to bed at ten\",\"answer\":\"I go to bed at ten\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It\'s half past seven.\",\"translation\":\"Saat yedi bu\\u00e7uk.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
