(25,5,'Kelimeler','vocabulary','lesson',0,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"kitchen\",\"mutfak\"],[\"bedroom\",\"yatak odas\\u0131\"],[\"bathroom\",\"banyo\"],[\"living room\",\"oturma odas\\u0131\"],[\"sofa\",\"kanepe\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"table\\\" ne demek?\",\"options\":[\"pencere\",\"yan\\u0131nda\",\"masa\",\"banyo\"],\"answer\":2,\"audio\":\"table\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"There are two bedrooms\",\"options\":[\"There are two bedrooms\",\"There are two bathrooms\",\"There is a bedroom\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Oturma odas\\u0131nda b\\u00fcy\\u00fck bir kanepe var.\",\"answer\":\"There is a big sofa in the living room\",\"alternatives\":[],\"tiles\":[\"a\",\"sofa\",\"room\",\"kitchen\",\"living\",\"is\",\"There\",\"in\",\"window\",\"the\",\"big\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"table\",\"masa\"],[\"chair\",\"sandalye\"],[\"window\",\"pencere\"],[\"under\",\"alt\\u0131nda\"],[\"next to\",\"yan\\u0131nda\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"alt\\u0131nda\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"under\",\"window\",\"living room\",\"bedroom\"],\"answer\":0},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"My bag is under the table.\",\"translation\":\"\\u00c7antam masan\\u0131n alt\\u0131nda.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"The lamp is next to the bed\",\"answer\":\"The lamp is next to the bed\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(26,5,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"There ___ a balcony in my flat.\",\"options\":[\"is\",\"are\",\"be\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"There ___ three chairs in the kitchen.\",\"options\":[\"is\",\"are\",\"am\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"The cat is sleeping ___ the sofa.\",\"options\":[\"on\",\"at\",\"to\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"___ there a bathroom upstairs?\",\"options\":[\"Are\",\"Is\",\"Does\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Mutfakta bir masa var.\",\"answer\":\"There is a table in the kitchen\",\"alternatives\":[\"There\'s a table in the kitchen\"],\"tiles\":[\"the\",\"There\",\"is\",\"a\",\"table\",\"in\",\"kitchen\",\"on\",\"are\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"There\",\"are\",\"a\",\"big\",\"window\",\"in\",\"my\",\"room\"],\"error_index\":1,\"options\":[\"is\",\"be\",\"have\"],\"answer\":0,\"explanation_tr\":\"\\\"A big window\\\" tekil oldu\\u011fu i\\u00e7in \\\"there is\\\" kullan\\u0131l\\u0131r. Do\\u011frusu: There is a big window in my room.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"My bedroom is small but nice.\",\"translation\":\"Yatak odam k\\u00fc\\u00e7\\u00fck ama g\\u00fczel.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(27,5,'Kelime oyunu','vocabulary','words',2,15,0,NULL,NULL,'[]','{\"game\":\"scramble\",\"words\":[{\"word\":\"kitchen\",\"translation\":\"mutfak\",\"example\":\"The bathroom is next to the kitchen.\"},{\"word\":\"bedroom\",\"translation\":\"yatak odas\\u0131\",\"example\":\"My bedroom is small but nice.\"},{\"word\":\"bathroom\",\"translation\":\"banyo\",\"example\":\"The bathroom is next to the kitchen.\"},{\"word\":\"living room\",\"translation\":\"oturma odas\\u0131\",\"example\":\"There is a big sofa in the living room.\"},{\"word\":\"sofa\",\"translation\":\"kanepe\",\"example\":\"There is a big sofa in the living room.\"},{\"word\":\"table\",\"translation\":\"masa\",\"example\":\"My bag is under the table.\"},{\"word\":\"chair\",\"translation\":\"sandalye\"},{\"word\":\"window\",\"translation\":\"pencere\"},{\"word\":\"under\",\"translation\":\"alt\\u0131nda\",\"example\":\"My bag is under the table.\"},{\"word\":\"next to\",\"translation\":\"yan\\u0131nda\",\"example\":\"The lamp is next to the bed\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(28,5,'Dinle ve konuş','listening','lesson',3,15,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Kiral\\u0131k ev bak\\u0131yorsun. Emlak\\u00e7\\u0131 soruyor.\",\"lines\":[{\"who\":\"Agent\",\"text\":\"Is there anything you need in the flat?\"}],\"options\":[\"Is there a balcony? I\'d like a place for plants.\",\"Have balcony?\",\"There balcony is?\"],\"answer\":0,\"note_tr\":\"Bir \\u015feyin var olup olmad\\u0131\\u011f\\u0131n\\u0131 sormak i\\u00e7in \\\"Is there \\u2026?\\\" kal\\u0131b\\u0131 kullan\\u0131l\\u0131r.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"The keys are on the table\",\"options\":[\"The keys are on the table\",\"The keys are under the table\",\"The kids are on the table\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"There is a cat in the garden\",\"answer\":\"There is a cat in the garden\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"There are two windows in the living room.\",\"translation\":\"Oturma odas\\u0131nda iki pencere var.\"},{\"type\":\"translate\",\"prompt\":\"Kitaplar yata\\u011f\\u0131n alt\\u0131nda.\",\"answer\":\"The books are under the bed\",\"alternatives\":[],\"tiles\":[\"under\",\"the\",\"is\",\"bed\",\"are\",\"on\",\"books\",\"The\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"My room is next to the bathroom\",\"answer\":\"My room is next to the bathroom\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"The bathroom is next to the kitchen.\",\"translation\":\"Banyo mutfa\\u011f\\u0131n yan\\u0131nda.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
