(31,6,'Kelimeler','vocabulary','lesson',0,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"bread\",\"ekmek\"],[\"cheese\",\"peynir\"],[\"egg\",\"yumurta\"],[\"milk\",\"s\\u00fct\"],[\"water\",\"su\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"apple\\\" ne demek?\",\"options\":[\"yumurta\",\"\\u015fi\\u015fe\",\"ucuz\",\"elma\"],\"answer\":3,\"audio\":\"apple\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"A glass of water, please\",\"options\":[\"A glass of water, please\",\"A class of water, please\",\"A glass of wine, please\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bir \\u015fi\\u015fe su alabilir miyim l\\u00fctfen?\",\"answer\":\"Can I have a bottle of water, please\",\"alternatives\":[],\"tiles\":[\"of\",\"expensive\",\"cheese\",\"have\",\"I\",\"water\",\"a\",\"Can\",\"please\",\"bottle\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"apple\",\"elma\"],[\"tomato\",\"domates\"],[\"cheap\",\"ucuz\"],[\"expensive\",\"pahal\\u0131\"],[\"bottle\",\"\\u015fi\\u015fe\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"pahal\\u0131\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"cheap\",\"milk\",\"expensive\",\"cheese\"],\"answer\":2},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Tomatoes are cheap today.\",\"translation\":\"Domatesler bug\\u00fcn ucuz.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"We need some bread and cheese\",\"answer\":\"We need some bread and cheese\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(32,6,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"Is there ___ milk in the fridge?\",\"options\":[\"some\",\"any\",\"a\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"I would ___ a sandwich, please.\",\"options\":[\"like\",\"likes\",\"liking\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"How ___ apples do you want?\",\"options\":[\"much\",\"many\",\"any\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"There is ___ cheese on the table.\",\"options\":[\"some\",\"any\",\"an\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bir kahve l\\u00fctfen.\",\"answer\":\"A coffee please\",\"alternatives\":[\"A coffee, please\",\"One coffee please\",\"One coffee, please\"],\"tiles\":[\"A\",\"please\",\"coffee\",\"is\",\"the\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"want\",\"two\",\"breads\",\"please\"],\"error_index\":3,\"options\":[\"loaves of bread\",\"bread\",\"breads\"],\"answer\":0,\"explanation_tr\":\"\\\"Bread\\\" say\\u0131lamayan bir isimdir, \\u00e7o\\u011ful -s almaz. \\\"\\u0130ki ekmek\\\" i\\u00e7in \\\"two loaves of bread\\\" ya da \\\"two pieces of bread\\\" denir.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Can I have the bill, please?\",\"translation\":\"Hesab\\u0131 alabilir miyim?\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
