(34,6,'Dinle ve konuş','listening','lesson',3,15,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Londra\'da bir kafedesin. S\\u0131ra sende.\",\"scene\":\"scenarios\\/order-at-a-cafe\",\"lines\":[{\"who\":\"Barista\",\"text\":\"Hi there! What can I get for you today?\"}],\"options\":[\"Give me one coffee.\",\"I\'d like a coffee, please.\",\"I want coffee now.\"],\"answer\":1,\"note_tr\":\"Sipari\\u015fte \\\"I want\\\" biraz sert durur, \\\"Give me\\\" ise emir gibidir. Kibar h\\u00e2li: I\\u2019d like \\u2026 , please.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"fifteen\",\"options\":[\"fifty\",\"fifteen\",\"five\"],\"answer\":1},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"How much is the cheese\",\"answer\":\"How much is the cheese\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'d like a cheese sandwich, please.\",\"translation\":\"Peynirli sandvi\\u00e7 istiyorum l\\u00fctfen.\"},{\"type\":\"translate\",\"prompt\":\"Bu ne kadar?\",\"answer\":\"How much is this\",\"alternatives\":[\"How much is it\",\"How much\'s this\"],\"tiles\":[\"are\",\"How\",\"this\",\"many\",\"is\",\"much\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I would like some eggs\",\"answer\":\"I would like some eggs\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"How much are the apples?\",\"translation\":\"Elmalar ne kadar?\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
