(37,7,'Kelimeler','vocabulary','lesson',0,15,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"station\",\"istasyon\"],[\"pharmacy\",\"eczane\"],[\"hospital\",\"hastane\"],[\"bank\",\"banka\"],[\"museum\",\"m\\u00fcze\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"street\\\" ne demek?\",\"options\":[\"kar\\u015f\\u0131s\\u0131nda\",\"sokak\",\"hastane\",\"sa\\u011fa d\\u00f6n\"],\"answer\":1,\"audio\":\"street\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Turn left at the bank\",\"options\":[\"Turn left at the bank\",\"Turn right at the bank\",\"Turn left at the park\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Eczane bankan\\u0131n kar\\u015f\\u0131s\\u0131nda.\",\"answer\":\"The pharmacy is opposite the bank\",\"alternatives\":[],\"tiles\":[\"opposite\",\"is\",\"bank\",\"opposite\",\"pharmacy\",\"The\",\"the\",\"hospital\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"street\",\"sokak\"],[\"turn left\",\"sola d\\u00f6n\"],[\"turn right\",\"sa\\u011fa d\\u00f6n\"],[\"go straight\",\"d\\u00fcz git\"],[\"opposite\",\"kar\\u015f\\u0131s\\u0131nda\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"d\\u00fcz git\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"turn right\",\"bank\",\"pharmacy\",\"go straight\"],\"answer\":3},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Go straight and turn left at the lights.\",\"translation\":\"D\\u00fcz git ve \\u0131\\u015f\\u0131klardan sola d\\u00f6n.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Where is the museum\",\"answer\":\"Where is the museum\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(38,7,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"She ___ speak three languages.\",\"options\":[\"can\",\"cans\",\"is\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I can ___ a bike.\",\"options\":[\"ride\",\"rides\",\"riding\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"___ I sit here?\",\"options\":[\"Can\",\"Do\",\"Am\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Sorry, I ___ swim.\",\"options\":[\"can\'t\",\"don\'t can\",\"not can\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"M\\u00fcze nerede?\",\"answer\":\"Where is the museum\",\"alternatives\":[\"Where\'s the museum\"],\"tiles\":[\"a\",\"museum\",\"are\",\"the\",\"is\",\"Where\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"He\",\"can\",\"speaks\",\"English\",\"very\",\"well\"],\"error_index\":2,\"options\":[\"speak\",\"speaking\",\"to speak\"],\"answer\":0,\"explanation_tr\":\"\\\"Can\\\" kendisinden sonra yal\\u0131n fiil ister; fiile -s eklenmez. Do\\u011frusu: He can speak English very well.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Excuse me, how can I get to the station?\",\"translation\":\"Affedersiniz, istasyona nas\\u0131l gidebilirim?\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(39,7,'Kelime oyunu','vocabulary','words',2,15,0,NULL,NULL,'[]','{\"game\":\"search\",\"words\":[{\"word\":\"station\",\"translation\":\"istasyon\",\"example\":\"Excuse me, how can I get to the station?\"},{\"word\":\"pharmacy\",\"translation\":\"eczane\",\"example\":\"The pharmacy is opposite the bank.\"},{\"word\":\"hospital\",\"translation\":\"hastane\"},{\"word\":\"bank\",\"translation\":\"banka\",\"example\":\"The pharmacy is opposite the bank.\"},{\"word\":\"museum\",\"translation\":\"m\\u00fcze\",\"example\":\"Where is the museum\"},{\"word\":\"street\",\"translation\":\"sokak\"},{\"word\":\"turn left\",\"translation\":\"sola d\\u00f6n\",\"example\":\"Go straight and turn left at the lights.\"},{\"word\":\"turn right\",\"translation\":\"sa\\u011fa d\\u00f6n\"},{\"word\":\"go straight\",\"translation\":\"d\\u00fcz git\",\"example\":\"Go straight and turn left at the lights.\"},{\"word\":\"opposite\",\"translation\":\"kar\\u015f\\u0131s\\u0131nda\",\"example\":\"The pharmacy is opposite the bank.\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(40,7,'Dinle ve konuş','listening','lesson',3,15,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir turist sana yol soruyor.\",\"lines\":[{\"who\":\"Tourist\",\"text\":\"Excuse me, where is the nearest pharmacy?\"}],\"options\":[\"Go straight on and turn right. It\'s opposite the bank.\",\"Pharmacy there is.\",\"You go pharmacy right.\"],\"answer\":0,\"note_tr\":\"Yol tarifinde emir c\\u00fcmleleri kullan\\u0131l\\u0131r: Go straight on, turn right\\u2026 Hedefi en sona b\\u0131rak.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"Where is the bus stop\",\"options\":[\"Where is the bus stop\",\"Where is the bookshop\",\"When is the bus\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Go straight on\",\"answer\":\"Go straight on\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It\'s on your right.\",\"translation\":\"Sa\\u011f taraf\\u0131n\\u0131zda.\"},{\"type\":\"translate\",\"prompt\":\"Bana yard\\u0131m edebilir misin?\",\"answer\":\"Can you help me\",\"alternatives\":[\"Could you help me\"],\"tiles\":[\"me\",\"to\",\"you\",\"helps\",\"Can\",\"help\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"The station is on your right\",\"answer\":\"The station is on your right\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Is it far from here?\",\"translation\":\"Buradan uzak m\\u0131?\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
