(44,8,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"Look! It ___ snowing.\",\"options\":[\"is\",\"are\",\"am\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"They are ___ football in the park.\",\"options\":[\"play\",\"playing\",\"plays\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"What ___ you doing now?\",\"options\":[\"is\",\"are\",\"do\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"I ___ sleeping, I\'m reading.\",\"options\":[\"am not\",\"not\",\"don\'t\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"\\u015eu an ya\\u011fmur ya\\u011f\\u0131yor.\",\"answer\":\"It is raining now\",\"alternatives\":[\"It\'s raining now\"],\"tiles\":[\"rains\",\"is\",\"raining\",\"now\",\"are\",\"It\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Listen!\",\"The\",\"baby\",\"cry\"],\"error_index\":3,\"options\":[\"is crying\",\"cries\",\"crying\"],\"answer\":0,\"explanation_tr\":\"\\\"Listen!\\\" konu\\u015fma an\\u0131n\\u0131 g\\u00f6sterir, bu y\\u00fczden \\u015fimdiki zaman gerekir: The baby is crying.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It\'s very cold today.\",\"translation\":\"Bug\\u00fcn hava \\u00e7ok so\\u011fuk.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
