(50,9,'Dilbilgisi','grammar','lesson',1,15,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I like ___ to music.\",\"options\":[\"listen\",\"listening\",\"listens\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"She ___ swimming in the sea.\",\"options\":[\"love\",\"loves\",\"loving\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"___ do you go to the cinema? Once a month.\",\"options\":[\"How often\",\"How much\",\"What\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"They enjoy ___ games online.\",\"options\":[\"play\",\"playing\",\"to playing\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Hafta sonu yemek yapmay\\u0131 severim.\",\"answer\":\"I like cooking at the weekend\",\"alternatives\":[\"I like to cook at the weekend\",\"I love cooking at the weekend\"],\"tiles\":[\"in\",\"I\",\"the\",\"cook\",\"at\",\"weekend\",\"cooking\",\"like\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"enjoy\",\"swim\",\"in\",\"summer\"],\"error_index\":2,\"options\":[\"swimming\",\"swims\",\"to swimming\"],\"answer\":0,\"explanation_tr\":\"\\\"Enjoy\\\" kendisinden sonra -ing ister: I enjoy swimming in summer.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"At the weekend I usually meet my friends.\",\"translation\":\"Hafta sonlar\\u0131 genellikle arkada\\u015flar\\u0131mla bulu\\u015furum.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
