(63,11,'Dilbilgisi','grammar','lesson',1,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"We ___ a great film yesterday.\",\"options\":[\"see\",\"saw\",\"seen\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"I didn\'t ___ to the party.\",\"options\":[\"go\",\"went\",\"gone\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"___ you buy that jacket online?\",\"options\":[\"Did\",\"Were\",\"Do\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"He ___ the bus to school this morning.\",\"options\":[\"take\",\"took\",\"taken\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Ge\\u00e7en yaz \\u0130talya\'ya gittik.\",\"answer\":\"We went to Italy last summer\",\"alternatives\":[\"Last summer we went to Italy\"],\"tiles\":[\"went\",\"to\",\"We\",\"last\",\"go\",\"in\",\"Italy\",\"summer\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Yesterday\",\"I\",\"didn\'t\",\"went\",\"to\",\"school\"],\"error_index\":3,\"options\":[\"go\",\"gone\",\"going\"],\"answer\":0,\"explanation_tr\":\"\\\"didn\'t\\\" zaten ge\\u00e7mi\\u015fi ta\\u015f\\u0131r; yan\\u0131ndaki fiil yal\\u0131n kal\\u0131r. Do\\u011frusu: I didn\'t go.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I visited my grandparents last weekend.\",\"translation\":\"Ge\\u00e7en hafta sonu b\\u00fcy\\u00fckanne ve b\\u00fcy\\u00fckbabam\\u0131 ziyaret ettim.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(64,11,'Kelime oyunu','vocabulary','words',2,18,0,NULL,NULL,'[]','{\"game\":\"choice\",\"words\":[{\"word\":\"went\",\"translation\":\"gitti\",\"example\":\"First we went to the beach, then we ate fish.\"},{\"word\":\"saw\",\"translation\":\"g\\u00f6rd\\u00fc\",\"example\":\"We saw a great film yesterday.\"},{\"word\":\"bought\",\"translation\":\"sat\\u0131n ald\\u0131\",\"example\":\"She bought a new phone\"},{\"word\":\"ate\",\"translation\":\"yedi\",\"example\":\"First we went to the beach, then we ate fish.\"},{\"word\":\"took\",\"translation\":\"ald\\u0131, g\\u00f6t\\u00fcrd\\u00fc\",\"example\":\"He took the bus to school this morning.\"},{\"word\":\"found\",\"translation\":\"buldu\",\"example\":\"I found my keys under the sofa.\"},{\"word\":\"first\",\"translation\":\"\\u00f6nce\",\"example\":\"First we went to the beach, then we ate fish.\"},{\"word\":\"then\",\"translation\":\"sonra\",\"example\":\"First we went to the beach, then we ate fish.\"},{\"word\":\"after that\",\"translation\":\"ondan sonra\"},{\"word\":\"finally\",\"translation\":\"sonunda\",\"example\":\"Finally, we got home at midnight.\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(65,11,'Dinle ve konuş','listening','lesson',3,18,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Arkada\\u015f\\u0131n tatilini soruyor.\",\"lines\":[{\"who\":\"Mia\",\"text\":\"Did you have a good holiday?\"}],\"options\":[\"Yes, I did! We went to Cappadocia and took a balloon ride.\",\"Yes, I did go Cappadocia.\",\"Yes, we goed to Cappadocia.\"],\"answer\":0,\"note_tr\":\"K\\u0131sa cevap \\\"Yes, I did\\\" ile ba\\u015fla, sonra ge\\u00e7mi\\u015f zamanla bir detay ver.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"She bought a new phone\",\"options\":[\"She bought a new phone\",\"She brought a new phone\",\"She buys a new phone\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"We went to the cinema\",\"answer\":\"We went to the cinema\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"What did you do on your holiday?\",\"translation\":\"Tatilinde ne yapt\\u0131n?\"},{\"type\":\"translate\",\"prompt\":\"Kahvalt\\u0131da ne yedin?\",\"answer\":\"What did you eat for breakfast\",\"alternatives\":[\"What did you have for breakfast\"],\"tiles\":[\"do\",\"eat\",\"did\",\"breakfast\",\"What\",\"ate\",\"you\",\"for\"]},{\"type\":\"sequence\",\"prompt\":\"D\\u00fcn ak\\u015fam\\u0131n\\u0131 anlat. C\\u00fcmleleri olay s\\u0131ras\\u0131na diz.\",\"items\":[\"I finished work at six.\",\"I met my friend at the metro station.\",\"We had dinner at a small restaurant.\",\"I got home just before midnight.\"],\"answer\":[0,1,2,3]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"What did you buy\",\"answer\":\"What did you buy\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Finally, we got home at midnight.\",\"translation\":\"Sonunda gece yar\\u0131s\\u0131 eve vard\\u0131k.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
