(68,12,'Kelimeler','vocabulary','lesson',0,18,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"holiday\",\"tatil\"],[\"plan\",\"plan\"],[\"book a ticket\",\"bilet ay\\u0131rtmak\"],[\"pack\",\"bavul haz\\u0131rlamak\"],[\"beach\",\"plaj\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"mountain\\\" ne demek?\",\"options\":[\"yurt d\\u0131\\u015f\\u0131nda\",\"da\\u011f\",\"yar\\u0131n\",\"bilet ay\\u0131rtmak\"],\"answer\":1,\"audio\":\"mountain\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"It\'s going to rain\",\"options\":[\"It\'s going to rain\",\"It\'s going to train\",\"It\'s going to snow\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Biletlerimizi bu ak\\u015fam ay\\u0131rtaca\\u011f\\u0131z.\",\"answer\":\"We\'re going to book our tickets tonight\",\"alternatives\":[],\"tiles\":[\"book\",\"going\",\"tonight\",\"next week\",\"to\",\"mountain\",\"tickets\",\"our\",\"We\'re\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"mountain\",\"da\\u011f\"],[\"tent\",\"\\u00e7ad\\u0131r\"],[\"tomorrow\",\"yar\\u0131n\"],[\"next week\",\"gelecek hafta\"],[\"abroad\",\"yurt d\\u0131\\u015f\\u0131nda\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"gelecek hafta\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"plan\",\"next week\",\"tomorrow\",\"pack\"],\"answer\":1},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"She is going to study abroad next year.\",\"translation\":\"Gelecek y\\u0131l yurt d\\u0131\\u015f\\u0131nda okuyacak.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I\'m going to pack my bag\",\"answer\":\"I\'m going to pack my bag\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(69,12,'Dilbilgisi','grammar','lesson',1,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I\'m going ___ my grandparents.\",\"options\":[\"visit\",\"to visit\",\"visiting\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"They ___ going to stay in a tent.\",\"options\":[\"is\",\"are\",\"am\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"Look at the sky! It ___ to rain.\",\"options\":[\"\'s going\",\"goes\",\"\'re going\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"What ___ you going to do this summer?\",\"options\":[\"are\",\"do\",\"will\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Yar\\u0131n erken kalkaca\\u011f\\u0131m.\",\"answer\":\"I\'m going to get up early tomorrow\",\"alternatives\":[\"I am going to get up early tomorrow\"],\"tiles\":[\"will\",\"at\",\"up\",\"early\",\"going\",\"to\",\"get\",\"tomorrow\",\"I\'m\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"We\'re\",\"going\",\"to\",\"visiting\",\"Paris\",\"next\",\"month\"],\"error_index\":3,\"options\":[\"visit\",\"visited\",\"visits\"],\"answer\":0,\"explanation_tr\":\"\\\"Going to\\\"dan sonra fiil yal\\u0131n kal\\u0131r: We\'re going to visit Paris.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'m going to travel to Japan one day.\",\"translation\":\"Bir g\\u00fcn Japonya\'ya seyahat edece\\u011fim.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
