(71,12,'Dinle ve konuş','listening','lesson',3,18,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Arkada\\u015f\\u0131n yaz planlar\\u0131n\\u0131 soruyor.\",\"lines\":[{\"who\":\"Tom\",\"text\":\"Any plans for the summer?\"}],\"options\":[\"Yes! I\'m going to work in a caf\\u00e9 and then go camping.\",\"Yes, I go work caf\\u00e9.\",\"Yes, I will going to work.\"],\"answer\":0,\"note_tr\":\"\\u00d6nceden kararla\\u015ft\\u0131r\\u0131lm\\u0131\\u015f planlar i\\u00e7in be going to kullan\\u0131l\\u0131r.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"We\'re going to book a hotel\",\"options\":[\"We\'re going to book a hotel\",\"We\'re going to look at a hotel\",\"We went to a hotel\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I\'m going to pack my bag\",\"answer\":\"I\'m going to pack my bag\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Are you going to come to my party?\",\"translation\":\"Partime gelecek misin?\"},{\"type\":\"translate\",\"prompt\":\"Bu yaz ne yapacaks\\u0131n?\",\"answer\":\"What are you going to do this summer\",\"alternatives\":[],\"tiles\":[\"do\",\"What\",\"you\",\"to\",\"this\",\"do\",\"going\",\"summer\",\"are\",\"will\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Are you going to come\",\"answer\":\"Are you going to come\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"We\'re going to stay for a week.\",\"translation\":\"Bir hafta kalaca\\u011f\\u0131z.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
