(99,17,'Dilbilgisi','grammar','lesson',1,18,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"You ___ smoke in the hospital.\",\"options\":[\"mustn\'t\",\"don\'t have to\",\"must\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"It\'s Saturday. I ___ get up early.\",\"options\":[\"don\'t have to\",\"mustn\'t\",\"must\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"She ___ wear glasses to read.\",\"options\":[\"has to\",\"have to\",\"must to\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Yesterday I ___ work until nine.\",\"options\":[\"must\",\"had to\",\"have to\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Zaman\\u0131nda gelmelisin.\",\"answer\":\"You must be on time\",\"alternatives\":[\"You have to be on time\"],\"tiles\":[\"to\",\"must\",\"time\",\"be\",\"You\",\"have\",\"on\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Yesterday\",\"I\",\"must\",\"work\",\"until\",\"nine\"],\"error_index\":2,\"options\":[\"had to\",\"have to\",\"must to\"],\"answer\":0,\"explanation_tr\":\"\\\"Must\\\"\\u0131n ge\\u00e7mi\\u015f h\\u00e2li yoktur; ge\\u00e7mi\\u015fteki zorunluluk i\\u00e7in \\\"had to\\\" kullan\\u0131l\\u0131r: Yesterday I had to work until nine.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Do I have to pay now?\",\"translation\":\"\\u015eimdi \\u00f6demek zorunda m\\u0131y\\u0131m?\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(100,17,'Kelime oyunu','vocabulary','words',2,18,0,NULL,NULL,'[]','{\"game\":\"kelimle\",\"words\":[{\"word\":\"must\",\"translation\":\"zorunda olmak, -meli\",\"example\":\"You must wear a seatbelt in the car.\"},{\"word\":\"mustn\'t\",\"translation\":\"-memeli (yasak)\",\"example\":\"You mustn\'t run in the corridor\"},{\"word\":\"have to\",\"translation\":\"zorunda olmak\",\"example\":\"We don\'t have to wear a uniform on Fridays.\"},{\"word\":\"don\'t have to\",\"translation\":\"gerek yok\",\"example\":\"We don\'t have to wear a uniform on Fridays.\"},{\"word\":\"rule\",\"translation\":\"kural\"},{\"word\":\"allowed\",\"translation\":\"izinli\"},{\"word\":\"uniform\",\"translation\":\"\\u00fcniforma\",\"example\":\"We don\'t have to wear a uniform on Fridays.\"},{\"word\":\"seatbelt\",\"translation\":\"emniyet kemeri\",\"example\":\"You must wear a seatbelt in the car.\"},{\"word\":\"quiet\",\"translation\":\"sessiz\",\"example\":\"We must be quiet in the library.\"},{\"word\":\"on time\",\"translation\":\"zaman\\u0131nda\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(101,17,'Dinle ve konuş','listening','lesson',3,18,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Yeni bir spor salonuna kaydoluyorsun.\",\"lines\":[{\"who\":\"Receptionist\",\"text\":\"Any questions about the gym rules?\"}],\"options\":[\"Do I have to bring my own towel?\",\"I must to bring towel?\",\"Have I to bring towel?\"],\"answer\":0,\"note_tr\":\"Bir zorunlulu\\u011fu sormak i\\u00e7in \\\"Do I have to \\u2026?\\\" kal\\u0131b\\u0131 kullan\\u0131l\\u0131r.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"We don\'t have to hurry\",\"options\":[\"We don\'t have to hurry\",\"We have to hurry\",\"We don\'t have to worry\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"You must wear a seatbelt\",\"answer\":\"You must wear a seatbelt\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"You don\'t have to bring anything.\",\"translation\":\"Bir \\u015fey getirmek zorunda de\\u011filsin.\"},{\"type\":\"translate\",\"prompt\":\"Burada foto\\u011fraf \\u00e7ekmek yasak.\",\"answer\":\"You mustn\'t take photos here\",\"alternatives\":[\"You must not take photos here\"],\"tiles\":[\"take\",\"mustn\'t\",\"photos\",\"don\'t\",\"have\",\"here\",\"You\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I had to work late\",\"answer\":\"I had to work late\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"We must be quiet in the library.\",\"translation\":\"K\\u00fct\\u00fcphanede sessiz olmal\\u0131y\\u0131z.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
