(104,17,'A2 seviye sınavı','mixed','checkpoint',6,50,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"They ___ very excited about the trip.\",\"options\":[\"was\",\"were\",\"are\"],\"answer\":1},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"Yesterday\",\"I\",\"didn\'t\",\"went\",\"to\",\"school\"],\"error_index\":3,\"options\":[\"go\",\"gone\",\"going\"],\"answer\":0,\"explanation_tr\":\"\\\"didn\'t\\\" zaten ge\\u00e7mi\\u015fi ta\\u015f\\u0131r; yan\\u0131ndaki fiil yal\\u0131n kal\\u0131r. Do\\u011frusu: I didn\'t go.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"It\'s going to rain\",\"options\":[\"It\'s going to rain\",\"It\'s going to train\",\"It\'s going to snow\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"T\\u00fcrkiye\'nin en b\\u00fcy\\u00fck \\u015fehri hangisi?\",\"answer\":\"What is the biggest city in Turkey\",\"alternatives\":[\"What\'s the biggest city in Turkey\",\"Which is the biggest city in Turkey\"],\"tiles\":[\"Turkey\",\"biggest\",\"is\",\"in\",\"What\",\"bigger\",\"city\",\"in\",\"the\"]},{\"type\":\"fill\",\"prompt\":\"You shouldn\'t ___ so much coffee.\",\"options\":[\"drink\",\"drinks\",\"to drink\"],\"answer\":0},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"will\",\"calling\",\"you\",\"tomorrow\"],\"error_index\":2,\"options\":[\"call\",\"calls\",\"called\"],\"answer\":0,\"explanation_tr\":\"\\\"Will\\\"den sonra fiil yal\\u0131n kal\\u0131r: I will call you tomorrow.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I\'ve never been to Paris\",\"options\":[\"I\'ve never been to Paris\",\"I\'ve never seen Paris\",\"I\'ll never go to Paris\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Burada foto\\u011fraf \\u00e7ek