(105,18,'Kelimeler','vocabulary','lesson',0,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"since\",\"-den beri\"],[\"for\",\"s\\u00fcredir\"],[\"already\",\"\\u00e7oktan\"],[\"yet\",\"hen\\u00fcz\"],[\"just\",\"az \\u00f6nce\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"recently\\\" ne demek?\",\"options\":[\"\\u00f6m\\u00fcr boyu\",\"geli\\u015ftirmek\",\"son zamanlarda\",\"\\u00e7oktan\"],\"answer\":2,\"audio\":\"recently\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I\'ve never been to Japan\",\"options\":[\"I\'ve never been to Japan\",\"I never went to Japan\",\"I\'d never been to Japan\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Projemi az \\u00f6nce bitirdim.\",\"answer\":\"I\'ve just finished my project\",\"alternatives\":[],\"tiles\":[\"finished\",\"just\",\"achieve\",\"my\",\"project\",\"yet\",\"I\'ve\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"recently\",\"son zamanlarda\"],[\"achieve\",\"ba\\u015farmak\"],[\"improve\",\"geli\\u015ftirmek\"],[\"career\",\"kariyer\"],[\"lifetime\",\"\\u00f6m\\u00fcr boyu\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"kariyer\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"career\",\"yet\",\"for\",\"improve\"],\"answer\":0},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"She has worked here since 2019.\",\"translation\":\"2019\'dan beri burada \\u00e7al\\u0131\\u015f\\u0131yor.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Have you finished your homework yet\",\"answer\":\"Have you finished your homework yet\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(106,18,'Dilbilgisi','grammar','lesson',1,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"Have you ever ___ sushi?\",\"options\":[\"eat\",\"ate\",\"eaten\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"I\'ve lived here ___ 2019.\",\"options\":[\"for\",\"since\",\"from\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"She\'s worked here ___ five years.\",\"options\":[\"for\",\"since\",\"during\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"I ___ my keys yesterday.\",\"options\":[\"lost\",\"\'ve lost\",\"lose\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bu filmi \\u00fc\\u00e7 kez izledim.\",\"answer\":\"I\'ve watched this film three times\",\"alternatives\":[\"I have watched this film three times\",\"I\'ve seen this film three times\",\"I have seen this film three times\"],\"tiles\":[\"three\",\"times\",\"watched\",\"this\",\"film\",\"I\'ve\",\"watch\",\"did\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"live\",\"in\",\"Ankara\",\"since\",\"2015\"],\"error_index\":1,\"options\":[\"have lived\",\"lived\",\"am living\"],\"answer\":0,\"explanation_tr\":\"H\\u00e2l\\u00e2 devam eden bir durum \\\"since\\\" ile anlat\\u0131l\\u0131yorsa present perfect gerekir: I\'ve lived in Ankara since 2015. T\\u00fcrk\\u00e7edeki \\\"-den beri ya\\u015f\\u0131yorum\\\" yap\\u0131s\\u0131 bu hatay\\u0131 \\u00e7ok yapt\\u0131r\\u0131r.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'ve been learning English for two years.\",\"translation\":\"\\u0130ki y\\u0131ld\\u0131r \\u0130ngilizce \\u00f6\\u011freniyorum.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
