(123,21,'Kelimeler','vocabulary','lesson',0,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"would\",\"-erdi, -ard\\u0131\"],[\"wish\",\"ke\\u015fke, dilemek\"],[\"lottery\",\"piyango\"],[\"afford\",\"paras\\u0131 yetmek\"],[\"island\",\"ada\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"imagine\\\" ne demek?\",\"options\":[\"piyango\",\"hayal etmek\",\"senin yerinde olsam\",\"yurt d\\u0131\\u015f\\u0131\"],\"answer\":1,\"audio\":\"imagine\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"If I had a car, I\'d drive to work\",\"options\":[\"If I had a car, I\'d drive to work\",\"If I have a car, I\'ll drive to work\",\"If I had a card, I\'d drive to work\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Piyangoyu kazansam d\\u00fcnyay\\u0131 gezerdim.\",\"answer\":\"If I won the lottery, I\'d travel around the world\",\"alternatives\":[],\"tiles\":[\"lottery\",\"travel\",\"the\",\"rich\",\"abroad\",\"I\",\"If\",\"won\",\"the\",\"around\",\"I\'d\",\"world\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"imagine\",\"hayal etmek\"],[\"rich\",\"zengin\"],[\"if I were you\",\"senin yerinde olsam\"],[\"dream\",\"hayal\"],[\"abroad\",\"yurt d\\u0131\\u015f\\u0131\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"hayal\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"dream\",\"afford\",\"if I were you\",\"wish\"],\"answer\":0},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I wish I could speak French.\",\"translation\":\"Ke\\u015fke Frans\\u0131zca konu\\u015fabilsem.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"If I were you I would take the job\",\"answer\":\"If I were you I would take the job\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(124,21,'Dilbilgisi','grammar','lesson',1,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"If I ___ more money, I\'d buy a car.\",\"options\":[\"have\",\"had\",\"would have\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"If she studied more, she ___ pass.\",\"options\":[\"will\",\"would\",\"is\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"I wish I ___ taller.\",\"options\":[\"am\",\"were\",\"will be\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"If I ___ you, I\'d apologise.\",\"options\":[\"am\",\"were\",\"would be\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Senin yerinde olsam o i\\u015fi al\\u0131rd\\u0131m.\",\"answer\":\"If I were you, I\'d take that job\",\"alternatives\":[\"If I were you I would take that job\",\"If I were you, I would take that job\"],\"tiles\":[\"I\'d\",\"take\",\"were\",\"will\",\"If\",\"you\",\"I\",\"was\",\"that\",\"job\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"If\",\"I\",\"have\",\"more\",\"time\",\"I\",\"would\",\"travel\",\"more\"],\"error_index\":2,\"options\":[\"had\",\"would have\",\"will have\"],\"answer\":0,\"explanation_tr\":\"Second conditional\'da \\\"if\\\" k\\u0131sm\\u0131nda past simple kullan\\u0131l\\u0131r: If I had more time, I would travel more.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"If I could live anywhere, I\'d choose Lisbon.\",\"translation\":\"Her yerde ya\\u015fayabilseydim Lizbon\'u se\\u00e7erdim.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(125,21,'Kelime oyunu','vocabulary','words',2,20,0,NULL,NULL,'[]','{\"game\":\"truefalse\",\"words\":[{\"word\":\"would\",\"translation\":\"-erdi, -ard\\u0131\",\"example\":\"If I were you I would take the job\"},{\"word\":\"wish\",\"translation\":\"ke\\u015fke, dilemek\",\"example\":\"I wish I could speak French.\"},{\"word\":\"lottery\",\"translation\":\"piyango\",\"example\":\"If I won the lottery, I\'d travel around the world.\"},{\"word\":\"afford\",\"translation\":\"paras\\u0131 yetmek\"},{\"word\":\"island\",\"translation\":\"ada\"},{\"word\":\"imagine\",\"translation\":\"hayal etmek\"},{\"word\":\"rich\",\"translation\":\"zengin\"},{\"word\":\"if I were you\",\"translation\":\"senin yerinde olsam\",\"example\":\"If I were you I would take the job\"},{\"word\":\"dream\",\"translation\":\"hayal\"},{\"word\":\"abroad\",\"translation\":\"yurt d\\u0131\\u015f\\u0131\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(126,21,'Dinle ve konuş','listening','lesson',3,20,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir arkada\\u015f\\u0131n zor bir karar\\u0131n e\\u015fi\\u011finde.\",\"lines\":[{\"who\":\"Nick\",\"text\":\"I got two job offers. One pays more, the other is closer to home. What would you do?\"}],\"options\":[\"If I were you, I\'d choose the closer one. Time is more important.\",\"If I am you, I will choose closer.\",\"If I would be you, I choose.\"],\"answer\":0,\"note_tr\":\"Tavsiye i\\u00e7in en do\\u011fal kal\\u0131p: If I were you, I\'d \\u2026\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I wish I knew the answer\",\"options\":[\"I wish I knew the answer\",\"I wish I know the answer\",\"I wish I had the answer\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"What would you do\",\"answer\":\"What would you do\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"What would you do if you were invisible?\",\"translation\":\"G\\u00f6r\\u00fcnmez olsan ne yapard\\u0131n?\"},{\"type\":\"translate\",\"prompt\":\"Ke\\u015fke denize yak\\u0131n ya\\u015fasam.\",\"answer\":\"I wish I lived near the sea\",\"alternatives\":[\"I wish I lived by the sea\"],\"tiles\":[\"would\",\"lived\",\"near\",\"sea\",\"I\",\"I\",\"the\",\"wish\",\"live\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I wish I could fly\",\"answer\":\"I wish I could fly\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I wish I had more free time.\",\"translation\":\"Ke\\u015fke daha \\u00e7ok bo\\u015f vaktim olsa.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
