(130,22,'Dilbilgisi','grammar','lesson',1,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"English ___ in many countries.\",\"options\":[\"speaks\",\"is spoken\",\"spoke\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"The Galata Tower ___ in 1348.\",\"options\":[\"built\",\"was built\",\"is building\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"A new hospital ___ next year.\",\"options\":[\"will open\",\"will be opened\",\"opens\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"The thief ___ by the police last night.\",\"options\":[\"arrested\",\"was arrested\",\"has arrest\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Bu roman Elif \\u015eafak taraf\\u0131ndan yaz\\u0131ld\\u0131.\",\"answer\":\"This novel was written by Elif Shafak\",\"alternatives\":[\"This novel was written by Elif \\u015eafak\"],\"tiles\":[\"from\",\"was\",\"written\",\"wrote\",\"novel\",\"by\",\"This\",\"Elif\",\"Shafak\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"The\",\"new\",\"bridge\",\"was\",\"build\",\"last\",\"year\"],\"error_index\":4,\"options\":[\"built\",\"builded\",\"building\"],\"answer\":0,\"explanation_tr\":\"Passive\'de fiilin 3. h\\u00e2li kullan\\u0131l\\u0131r: build \\u2192 built \\u2192 built. Do\\u011frusu: was built.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"The museum is visited by millions of people every year.\",\"translation\":\"M\\u00fcze her y\\u0131l milyonlarca ki\\u015fi taraf\\u0131ndan ziyaret ediliyor.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
