(132,22,'Dinle ve konuş','listening','lesson',3,20,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir haber sunucusu olarak son dakika haberini okuyorsun.\",\"lines\":[{\"who\":\"Producer\",\"text\":\"We\'re live in ten seconds. What happened at the stadium?\"}],\"options\":[\"The match was stopped after the lights were damaged by the storm.\",\"Storm damaged lights was stopped match.\",\"The match stopping by storm.\"],\"answer\":0,\"note_tr\":\"Haber dilinde olay\\u0131 \\u00f6ne almak i\\u00e7in passive kullan\\u0131l\\u0131r.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"It was built in 1973\",\"options\":[\"It was built in 1973\",\"It was filled in 1973\",\"It is built in 1973\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"The road was closed\",\"answer\":\"The road was closed\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Nobody was injured in the accident.\",\"translation\":\"Kazada kimse yaralanmad\\u0131.\"},{\"type\":\"translate\",\"prompt\":\"Toplant\\u0131 ertelendi.\",\"answer\":\"The meeting has been postponed\",\"alternatives\":[\"The meeting was postponed\"],\"tiles\":[\"meeting\",\"has\",\"The\",\"is\",\"postponed\",\"been\",\"postponed\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"The letter has been sent\",\"answer\":\"The letter has been sent\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"The match has been cancelled because of the rain.\",\"translation\":\"Ma\\u00e7 ya\\u011fmur y\\u00fcz\\u00fcnden iptal edildi.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
