(141,24,'Kelimeler','vocabulary','lesson',0,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"who\",\"ki o (insan)\"],[\"which\",\"ki o (e\\u015fya)\"],[\"where\",\"\\u2026 olan yer\"],[\"whose\",\"ki onun\"],[\"neighbour\",\"kom\\u015fu\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"colleague\\\" ne demek?\",\"options\":[\"g\\u00fcvenilir\",\"i\\u015f arkada\\u015f\\u0131\",\"\\u2026 olan yer\",\"ki\\u015filik\"],\"answer\":1,\"audio\":\"colleague\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"the woman who lives next door\",\"options\":[\"the woman who lives next door\",\"the woman who leaves next door\",\"the woman who lived next door\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Yan dairede oturan kad\\u0131n pilot.\",\"answer\":\"The woman who lives next door is a pilot\",\"alternatives\":[],\"tiles\":[\"who\",\"woman\",\"where\",\"a\",\"next\",\"is\",\"The\",\"door\",\"lives\",\"reliable\",\"pilot\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"colleague\",\"i\\u015f arkada\\u015f\\u0131\"],[\"describe\",\"tarif etmek\"],[\"personality\",\"ki\\u015filik\"],[\"generous\",\"c\\u00f6mert\"],[\"reliable\",\"g\\u00fcvenilir\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"c\\u00f6mert\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"personality\",\"whose\",\"which\",\"generous\"],\"answer\":3},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"This is the caf\\u00e9 where we first met.\",\"translation\":\"Buras\\u0131 ilk tan\\u0131\\u015ft\\u0131\\u011f\\u0131m\\u0131z kafe.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I have a friend whose father is a chef\",\"answer\":\"I have a friend whose father is a chef\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(142,24,'Dilbilgisi','grammar','lesson',1,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"The man ___ called you is my uncle.\",\"options\":[\"who\",\"which\",\"where\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"That\'s the school ___ my mother teaches.\",\"options\":[\"which\",\"where\",\"who\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"The book ___ you lent me was amazing.\",\"options\":[\"who\",\"which\",\"whose\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"I met a girl ___ brother plays for Fenerbah\\u00e7e.\",\"options\":[\"who\",\"whose\",\"which\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"D\\u00fcn izledi\\u011fimiz film harikayd\\u0131.\",\"answer\":\"The film we watched yesterday was great\",\"alternatives\":[\"The film that we watched yesterday was great\",\"The film which we watched yesterday was great\"],\"tiles\":[\"film\",\"which was\",\"The\",\"yesterday\",\"was\",\"great\",\"we\",\"watched\",\"who\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"The\",\"man\",\"which\",\"works\",\"here\",\"is\",\"very\",\"friendly\"],\"error_index\":2,\"options\":[\"who\",\"where\",\"whose\"],\"answer\":0,\"explanation_tr\":\"\\u0130nsanlar i\\u00e7in \\\"who\\\" (ya da \\\"that\\\") kullan\\u0131l\\u0131r; \\\"which\\\" e\\u015fya ve hayvanlar i\\u00e7indir.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"My best friend is someone who always tells the truth.\",\"translation\":\"En iyi arkada\\u015f\\u0131m her zaman do\\u011fruyu s\\u00f6yleyen biri.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(143,24,'Kelime oyunu','vocabulary','words',2,20,0,NULL,NULL,'[]','{\"game\":\"search\",\"words\":[{\"word\":\"who\",\"translation\":\"ki o (insan)\",\"example\":\"The woman who lives next door is a pilot.\"},{\"word\":\"which\",\"translation\":\"ki o (e\\u015fya)\",\"example\":\"The book which you lent me was amazing.\"},{\"word\":\"where\",\"translation\":\"\\u2026 olan yer\",\"example\":\"This is the caf\\u00e9 where we first met.\"},{\"word\":\"whose\",\"translation\":\"ki onun\",\"example\":\"I have a friend whose father is a chef\"},{\"word\":\"neighbour\",\"translation\":\"kom\\u015fu\"},{\"word\":\"colleague\",\"translation\":\"i\\u015f arkada\\u015f\\u0131\"},{\"word\":\"describe\",\"translation\":\"tarif etmek\"},{\"word\":\"personality\",\"translation\":\"ki\\u015filik\"},{\"word\":\"generous\",\"translation\":\"c\\u00f6mert\"},{\"word\":\"reliable\",\"translation\":\"g\\u00fcvenilir\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(144,24,'Dinle ve konuş','listening','lesson',3,20,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir partide arkada\\u015f\\u0131n birini soruyor.\",\"lines\":[{\"who\":\"Kate\",\"text\":\"Who is that woman by the window?\"}],\"options\":[\"That\'s Selin. She\'s the colleague who helped me with my project.\",\"That Selin which help me.\",\"Selin that window woman.\"],\"answer\":0,\"note_tr\":\"Bir ki\\u015fiyi tan\\u0131mlarken \\\"who\\\" ile c\\u00fcmlecik kurmak do\\u011fal ve nettir.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"the caf\\u00e9 where we met\",\"options\":[\"the caf\\u00e9 where we met\",\"the caf\\u00e9 we were met\",\"the caf\\u00e9 where we meet\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"The man who called you is here\",\"answer\":\"The man who called you is here\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Izmir is the city where I grew up.\",\"translation\":\"\\u0130zmir b\\u00fcy\\u00fcd\\u00fc\\u011f\\u00fcm \\u015fehir.\"},{\"type\":\"translate\",\"prompt\":\"Bana yard\\u0131m eden kad\\u0131n bir doktordu.\",\"answer\":\"The woman who helped me was a doctor\",\"alternatives\":[\"The woman that helped me was a doctor\"],\"tiles\":[\"helps\",\"helped\",\"The\",\"was\",\"which\",\"woman\",\"doctor\",\"a\",\"me\",\"who\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"This is the house where I was born\",\"answer\":\"This is the house where I was born\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Is this the bag you were looking for?\",\"translation\":\"Arad\\u0131\\u011f\\u0131n \\u00e7anta bu mu?\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
