(147,25,'Kelimeler','vocabulary','lesson',0,20,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"apply for\",\"ba\\u015fvurmak\"],[\"position\",\"pozisyon\"],[\"CV\",\"\\u00f6zge\\u00e7mi\\u015f\"],[\"deadline\",\"son teslim tarihi\"],[\"colleague\",\"i\\u015f arkada\\u015f\\u0131\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"manager\\\" ne demek?\",\"options\":[\"\\u00f6zge\\u00e7mi\\u015f\",\"d\\u00f6rt g\\u00f6zle beklemek\",\"m\\u00fcd\\u00fcr\",\"i\\u015fe almak\"],\"answer\":2,\"audio\":\"manager\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I look forward to hearing from you\",\"options\":[\"I look forward to hearing from you\",\"I look forward to hear from you\",\"I looked for hearing from you\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Sat\\u0131\\u015f asistan\\u0131 pozisyonuna ba\\u015fvurmak i\\u00e7in yaz\\u0131yorum.\",\"answer\":\"I am writing to apply for the position of sales assistant\",\"alternatives\":[],\"tiles\":[\"deadline\",\"position\",\"am\",\"apply for\",\"I\",\"assistant\",\"sales\",\"of\",\"apply\",\"to\",\"writing\",\"for\",\"the\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"manager\",\"m\\u00fcd\\u00fcr\"],[\"salary\",\"maa\\u015f\"],[\"look forward to\",\"d\\u00f6rt g\\u00f6zle beklemek\"],[\"avoid\",\"ka\\u00e7\\u0131nmak\"],[\"hire\",\"i\\u015fe almak\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"ka\\u00e7\\u0131nmak\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"look forward to\",\"avoid\",\"deadline\",\"position\"],\"answer\":1},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I look forward to hearing from you.\",\"translation\":\"Sizden haber almay\\u0131 d\\u00f6rt g\\u00f6zle bekliyorum.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"We decided to hire a new designer\",\"answer\":\"We decided to hire a new designer\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(148,25,'Dilbilgisi','grammar','lesson',1,20,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I look forward to ___ you.\",\"options\":[\"meet\",\"meeting\",\"to meet\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"She decided ___ the job offer.\",\"options\":[\"accept\",\"to accept\",\"accepting\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"Would you mind ___ the window?\",\"options\":[\"open\",\"to open\",\"opening\"],\"answer\":2},{\"type\":\"fill\",\"prompt\":\"We should avoid ___ mistakes in the report.\",\"options\":[\"make\",\"to make\",\"making\"],\"answer\":2},{\"type\":\"translate\",\"prompt\":\"Pazarlama pozisyonuna ba\\u015fvurmak istiyorum.\",\"answer\":\"I\'d like to apply for the marketing position\",\"alternatives\":[\"I would like to apply for the marketing position\"],\"tiles\":[\"like\",\"the\",\"apply\",\"applying\",\"I\'d\",\"position\",\"to the\",\"for\",\"marketing\",\"to\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"look\",\"forward\",\"to\",\"hear\",\"from\",\"you\"],\"error_index\":4,\"options\":[\"hearing\",\"heard\",\"to hear\"],\"answer\":0,\"explanation_tr\":\"\\\"Look forward to\\\" kal\\u0131b\\u0131nda \\\"to\\\" bir edatt\\u0131r; arkas\\u0131ndan -ing gelir: I look forward to hearing from you.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Could you please send me more information about the position?\",\"translation\":\"Pozisyon hakk\\u0131nda daha fazla bilgi g\\u00f6nderebilir misiniz l\\u00fctfen?\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(149,25,'Kelime oyunu','vocabulary','words',2,20,0,NULL,NULL,'[]','{\"game\":\"kelimle\",\"words\":[{\"word\":\"apply for\",\"translation\":\"ba\\u015fvurmak\",\"example\":\"I am writing to apply for the position of sales assistant.\"},{\"word\":\"position\",\"translation\":\"pozisyon\",\"example\":\"I am writing to apply for the position of sales assistant.\"},{\"word\":\"CV\",\"translation\":\"\\u00f6zge\\u00e7mi\\u015f\"},{\"word\":\"deadline\",\"translation\":\"son teslim tarihi\"},{\"word\":\"colleague\",\"translation\":\"i\\u015f arkada\\u015f\\u0131\"},{\"word\":\"manager\",\"translation\":\"m\\u00fcd\\u00fcr\"},{\"word\":\"salary\",\"translation\":\"maa\\u015f\"},{\"word\":\"look forward to\",\"translation\":\"d\\u00f6rt g\\u00f6zle beklemek\",\"example\":\"I look forward to hearing from you.\"},{\"word\":\"avoid\",\"translation\":\"ka\\u00e7\\u0131nmak\",\"example\":\"We should avoid making mistakes in the report.\"},{\"word\":\"hire\",\"translation\":\"i\\u015fe almak\",\"example\":\"We decided to hire a new designer\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(150,25,'Dinle ve konuş','listening','lesson',3,20,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Resm\\u00ee bir e-postan\\u0131n son c\\u00fcmlesini se\\u00e7iyorsun.\",\"lines\":[{\"who\":\"E-mail\",\"text\":\"Dear Ms Clark, I am writing to apply for the position of receptionist advertised on your website. \\u2026 \"}],\"options\":[\"I look forward to hearing from you. Kind regards,\",\"Waiting your answer. Bye!\",\"Answer me quickly please.\"],\"answer\":0,\"note_tr\":\"Resm\\u00ee e-posta kibar ve kal\\u0131pla\\u015fm\\u0131\\u015f bir kapan\\u0131\\u015fla biter: I look forward to hearing from you.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"We\'ve decided to hire her\",\"options\":[\"We\'ve decided to hire her\",\"We\'ve decided to fire her\",\"We decide to hire her\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Thank you for your email\",\"answer\":\"Thank you for your email\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'m good at working in a team.\",\"translation\":\"Tak\\u0131m \\u00e7al\\u0131\\u015fmas\\u0131nda iyiyimdir.\"},{\"type\":\"translate\",\"prompt\":\"Raporu cumaya kadar bitirmeyi planl\\u0131yoruz.\",\"answer\":\"We plan to finish the report by Friday\",\"alternatives\":[\"We are planning to finish the report by Friday\"],\"tiles\":[\"finish\",\"Friday\",\"by\",\"finishing\",\"until\",\"report\",\"to\",\"the\",\"We\",\"plan\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I would like to apply for the job\",\"answer\":\"I would like to apply for the job\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Thank you for considering my application.\",\"translation\":\"Ba\\u015fvurumu de\\u011ferlendirdi\\u011finiz i\\u00e7in te\\u015fekk\\u00fcr ederim.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
