(168,28,'Kelime oyunu','vocabulary','words',2,22,0,NULL,NULL,'[]','{\"game\":\"swipe\",\"words\":[{\"word\":\"research\",\"translation\":\"ara\\u015ft\\u0131rma\"},{\"word\":\"data\",\"translation\":\"veri\",\"example\":\"The data must be checked before the report is published.\"},{\"word\":\"experiment\",\"translation\":\"deney\",\"example\":\"The experiment must be repeated\"},{\"word\":\"device\",\"translation\":\"cihaz\",\"example\":\"It is believed that the device was invented in China.\"},{\"word\":\"invention\",\"translation\":\"icat\"},{\"word\":\"artificial intelligence\",\"translation\":\"yapay zek\\u00e2\"},{\"word\":\"develop\",\"translation\":\"geli\\u015ftirmek\"},{\"word\":\"replace\",\"translation\":\"yerini almak\",\"example\":\"It is said that robots will replace many jobs.\"},{\"word\":\"reliable\",\"translation\":\"g\\u00fcvenilir\"},{\"word\":\"significant\",\"translation\":\"\\u00f6nemli, kayda de\\u011fer\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(169,28,'Dinle ve konuş','listening','lesson',3,22,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Bir bilim fuar\\u0131nda projeni anlat\\u0131yorsun.\",\"lines\":[{\"who\":\"Judge\",\"text\":\"How was the data collected?\"}],\"options\":[\"The data was collected from 200 students and then analysed with a simple program.\",\"We collect data students and analyse.\",\"Data collecting by students.\"],\"answer\":0,\"note_tr\":\"Y\\u00f6ntem anlat\\u0131rken passive kullanmak bilimsel ve nesnel durur.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I had my phone repaired\",\"options\":[\"I had my phone repaired\",\"I had my phone replaced\",\"I have my phone repaired\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"The results were published last year\",\"answer\":\"The results were published last year\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It is said that robots will replace many jobs.\",\"translation\":\"Robotlar\\u0131n bir\\u00e7ok i\\u015fin yerini alaca\\u011f\\u0131 s\\u00f6yleniyor.\"},{\"type\":\"translate\",\"prompt\":\"Bu cihaz\\u0131n 2030\'a kadar yayg\\u0131nla\\u015fmas\\u0131 bekleniyor.\",\"answer\":\"This device is expected to become common by 2030\",\"alternatives\":[\"This device is expected to be common by 2030\"],\"tiles\":[\"expected\",\"common\",\"expects\",\"to\",\"device\",\"This\",\"become\",\"2030\",\"by\",\"will\",\"is\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I need to have my car fixed\",\"answer\":\"I need to have my car fixed\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'m getting my eyes tested next week.\",\"translation\":\"Gelecek hafta g\\u00f6zlerimi test ettirece\\u011fim.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
