(184,31,'Kelimeler','vocabulary','lesson',0,22,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"community\",\"topluluk\"],[\"public transport\",\"toplu ta\\u015f\\u0131ma\"],[\"council\",\"belediye meclisi\"],[\"resident\",\"sakin\"],[\"volunteer\",\"g\\u00f6n\\u00fcll\\u00fc\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"inequality\\\" ne demek?\",\"options\":[\"belediye meclisi\",\"iyile\\u015ftirmek\",\"konut\",\"e\\u015fitsizlik\"],\"answer\":3,\"audio\":\"inequality\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I\'d rather stay at home\",\"options\":[\"I\'d rather stay at home\",\"I\'d rather stayed at home\",\"I\'d better stay at home\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Kalabal\\u0131k bir otob\\u00fcse binmektense y\\u00fcr\\u00fcmeyi tercih ederim.\",\"answer\":\"I\'d rather walk than take a crowded bus\",\"alternatives\":[],\"tiles\":[\"walk\",\"take\",\"rather\",\"crowded\",\"a\",\"I\'d\",\"crowded\",\"than\",\"public transport\",\"bus\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"inequality\",\"e\\u015fitsizlik\"],[\"affordable\",\"uygun fiyatl\\u0131\"],[\"housing\",\"konut\"],[\"crowded\",\"kalabal\\u0131k\"],[\"improve\",\"iyile\\u015ftirmek\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"kalabal\\u0131k\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"housing\",\"resident\",\"crowded\",\"public transport\"],\"answer\":2},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It\'s time the council built more parks.\",\"translation\":\"Belediyenin daha fazla park yapmas\\u0131n\\u0131n zaman\\u0131 geldi.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Could you tell me where the town hall is\",\"answer\":\"Could you tell me where the town hall is\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(185,31,'Dilbilgisi','grammar','lesson',1,22,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I\'d rather ___ at home tonight.\",\"options\":[\"stay\",\"to stay\",\"staying\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"It\'s time we ___ something about the traffic.\",\"options\":[\"do\",\"did\",\"will do\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"You\'d better ___ an umbrella.\",\"options\":[\"take\",\"to take\",\"taking\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Could you tell me where the station ___?\",\"options\":[\"is\",\"does\",\"be\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bence \\u015fehrin daha fazla bisiklet yoluna ihtiyac\\u0131 var.\",\"answer\":\"In my opinion, the city needs more cycle lanes\",\"alternatives\":[\"I think the city needs more cycle lanes\",\"In my opinion the city needs more cycle lanes\"],\"tiles\":[\"need\",\"lanes\",\"needs\",\"In\",\"the\",\"much\",\"my\",\"city\",\"cycle\",\"opinion\",\"more\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"It\'s\",\"time\",\"we\",\"go\",\"home\"],\"error_index\":3,\"options\":[\"went\",\"going\",\"will go\"],\"answer\":0,\"explanation_tr\":\"\\\"It\'s time\\\" kal\\u0131b\\u0131ndan sonra past simple kullan\\u0131l\\u0131r, ama anlam \\u015fimdiki zamand\\u0131r: It\'s time we went home.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I\'d rather live in a small town than a big city.\",\"translation\":\"B\\u00fcy\\u00fck \\u015fehirdense k\\u00fc\\u00e7\\u00fck bir kasabada ya\\u015famay\\u0131 tercih ederim.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(186,31,'Kelime oyunu','vocabulary','words',2,22,0,NULL,NULL,'[]','{\"game\":\"memory\",\"words\":[{\"word\":\"community\",\"translation\":\"topluluk\"},{\"word\":\"public transport\",\"translation\":\"toplu ta\\u015f\\u0131ma\"},{\"word\":\"council\",\"translation\":\"belediye meclisi\",\"example\":\"It\'s time the council built more parks.\"},{\"word\":\"resident\",\"translation\":\"sakin\"},{\"word\":\"volunteer\",\"translation\":\"g\\u00f6n\\u00fcll\\u00fc\"},{\"word\":\"inequality\",\"translation\":\"e\\u015fitsizlik\"},{\"word\":\"affordable\",\"translation\":\"uygun fiyatl\\u0131\"},{\"word\":\"housing\",\"translation\":\"konut\"},{\"word\":\"crowded\",\"translation\":\"kalabal\\u0131k\",\"example\":\"I\'d rather walk than take a crowded bus.\"},{\"word\":\"improve\",\"translation\":\"iyile\\u015ftirmek\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(187,31,'Dinle ve konuş','listening','lesson',3,22,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Belediyeye kibar bir talepte bulunuyorsun.\",\"lines\":[{\"who\":\"Officer\",\"text\":\"Good morning. How can I help you?\"}],\"options\":[\"Good morning. I was wondering if you could tell me how to apply for a volunteer position.\",\"Tell me volunteer job where.\",\"I want volunteer, give form.\"],\"answer\":0,\"note_tr\":\"Resm\\u00ee ortamda dolayl\\u0131 sorular kibar ve profesyonel durur: I was wondering if\\u2026\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"It\'s time we left\",\"options\":[\"It\'s time we left\",\"It\'s time we leave\",\"It\'s time to leave\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"It is time we went home\",\"answer\":\"It is time we went home\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"It\'s high time we did something about pollution.\",\"translation\":\"Kirlilik hakk\\u0131nda bir \\u015feyler yapmam\\u0131z\\u0131n vakti \\u00e7oktan geldi.\"},{\"type\":\"translate\",\"prompt\":\"Bana yard\\u0131m edebilir misiniz diye merak ediyordum.\",\"answer\":\"I was wondering if you could help me\",\"alternatives\":[\"I was wondering whether you could help me\"],\"tiles\":[\"can\",\"wondering\",\"you\",\"whether\",\"if\",\"I\",\"me\",\"help\",\"could\",\"was\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"I\'d rather take the train\",\"answer\":\"I\'d rather take the train\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I was wondering if you could give me some advice.\",\"translation\":\"Bana biraz tavsiye verebilir misiniz diye merak ediyordum.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
