(196,33,'Kelimeler','vocabulary','lesson',0,22,0,NULL,NULL,'[{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"give up\",\"vazge\\u00e7mek, b\\u0131rakmak\"],[\"look after\",\"bakmak\"],[\"turn down\",\"reddetmek\"],[\"come up with\",\"(fikir) bulmak\"],[\"put off\",\"ertelemek\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"find out\\\" ne demek?\",\"options\":[\"reddetmek\",\"\\u00e7ok kolay\",\"\\u00f6\\u011frenmek\",\"art arda izlemek\"],\"answer\":2,\"audio\":\"find out\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"She turned down the offer\",\"options\":[\"She turned down the offer\",\"She turned up the offer\",\"She turned down the officer\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"\\u0130\\u015f teklifini reddetti.\",\"answer\":\"She turned down the job offer\",\"alternatives\":[],\"tiles\":[\"She\",\"turned\",\"come up with\",\"job\",\"give up\",\"down\",\"offer\",\"the\"]},{\"type\":\"match\",\"prompt\":\"E\\u015fle\\u015ftir\",\"pairs\":[[\"find out\",\"\\u00f6\\u011frenmek\"],[\"break the ice\",\"buzlar\\u0131 k\\u0131rmak\"],[\"a piece of cake\",\"\\u00e7ok kolay\"],[\"once in a blue moon\",\"k\\u0131rk y\\u0131lda bir\"],[\"binge-watch\",\"art arda izlemek\"]]},{\"type\":\"choice\",\"prompt\":\"\\\"k\\u0131rk y\\u0131lda bir\\\" \\u0130ngilizcede hangisi?\",\"options\":[\"a piece of cake\",\"once in a blue moon\",\"come up with\",\"look after\"],\"answer\":1},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Don\'t put off your homework until Sunday.\",\"translation\":\"\\u00d6devini pazara kadar erteleme.\"},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"We came up with a brilliant idea\",\"answer\":\"We came up with a brilliant idea\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(197,33,'Dilbilgisi','grammar','lesson',1,22,0,NULL,NULL,'[{\"type\":\"fill\",\"prompt\":\"I\'m trying to ___ sugar. (b\\u0131rakmak)\",\"options\":[\"give up\",\"give in\",\"give out\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"Can you ___ my cat while I\'m away?\",\"options\":[\"look for\",\"look after\",\"look up\"],\"answer\":1},{\"type\":\"fill\",\"prompt\":\"We need to ___ a better plan.\",\"options\":[\"come up with\",\"come across\",\"come down\"],\"answer\":0},{\"type\":\"fill\",\"prompt\":\"The music is too loud. Please turn it ___.\",\"options\":[\"up\",\"down\",\"off\"],\"answer\":1},{\"type\":\"translate\",\"prompt\":\"Toplant\\u0131y\\u0131 gelecek haftaya erteledik.\",\"answer\":\"We put off the meeting until next week\",\"alternatives\":[\"We put the meeting off until next week\",\"We postponed the meeting until next week\"],\"tiles\":[\"next\",\"put\",\"week\",\"We\",\"off\",\"meeting\",\"put on\",\"the\",\"until\",\"to\"]},{\"type\":\"spot_error\",\"prompt\":\"Bu c\\u00fcmle bir T\\u00fcrk \\u00f6\\u011frencinin a\\u011fz\\u0131ndan \\u00e7\\u0131kt\\u0131. Hatal\\u0131 kelimeyi bul.\",\"words\":[\"I\",\"gave\",\"in\",\"smoking\",\"two\",\"years\",\"ago\"],\"error_index\":2,\"options\":[\"up\",\"out\",\"off\"],\"answer\":0,\"explanation_tr\":\"\\\"Give up\\\" b\\u0131rakmak demektir: I gave up smoking. \\\"Give in\\\" ise pes etmek, boyun e\\u011fmek anlam\\u0131na gelir.\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I only see my cousins once in a blue moon.\",\"translation\":\"Kuzenlerimi k\\u0131rk y\\u0131lda bir g\\u00f6r\\u00fcyorum.\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(198,33,'Kelime oyunu','vocabulary','words',2,22,0,NULL,NULL,'[]','{\"game\":\"match\",\"words\":[{\"word\":\"give up\",\"translation\":\"vazge\\u00e7mek, b\\u0131rakmak\",\"example\":\"Do not give up\"},{\"word\":\"look after\",\"translation\":\"bakmak\",\"example\":\"Can you look after my cat while I\'m away?\"},{\"word\":\"turn down\",\"translation\":\"reddetmek\"},{\"word\":\"come up with\",\"translation\":\"(fikir) bulmak\",\"example\":\"We need to come up with a better plan.\"},{\"word\":\"put off\",\"translation\":\"ertelemek\",\"example\":\"Don\'t put off your homework until Sunday.\"},{\"word\":\"find out\",\"translation\":\"\\u00f6\\u011frenmek\",\"example\":\"We need to find out the truth\"},{\"word\":\"break the ice\",\"translation\":\"buzlar\\u0131 k\\u0131rmak\",\"example\":\"Let me tell a joke to break the ice.\"},{\"word\":\"a piece of cake\",\"translation\":\"\\u00e7ok kolay\"},{\"word\":\"once in a blue moon\",\"translation\":\"k\\u0131rk y\\u0131lda bir\",\"example\":\"I only see my cousins once in a blue moon.\"},{\"word\":\"binge-watch\",\"translation\":\"art arda izlemek\"}]}','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(199,33,'Dinle ve konuş','listening','lesson',3,22,0,NULL,NULL,'[{\"type\":\"dialogue\",\"prompt\":\"Arkada\\u015f\\u0131n yeni bir diziyi \\u00f6neriyor.\",\"lines\":[{\"who\":\"Mia\",\"text\":\"Have you started the new series yet? I binge-watched the whole thing this weekend!\"}],\"options\":[\"Not yet, I keep putting it off because of exams. No spoilers, please!\",\"I am not start it, I postpone it off.\",\"Not yet, I keep putting off it.\"],\"answer\":0,\"note_tr\":\"\\\"Put off\\\" ertelemek demektir; \\\"keep putting it off\\\" s\\u00fcrekli ertelemeyi anlat\\u0131r.\"},{\"type\":\"listen_choice\",\"prompt\":\"Ne duydun?\",\"audio\":\"I\'ve given up sugar\",\"options\":[\"I\'ve given up sugar\",\"I\'ve given in sugar\",\"I\'ve given up sugar and salt\"],\"answer\":0},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"We need to find out the truth\",\"answer\":\"We need to find out the truth\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"Let me tell a joke to break the ice.\",\"translation\":\"Buzlar\\u0131 k\\u0131rmak i\\u00e7in bir f\\u0131kra anlatay\\u0131m.\"},{\"type\":\"translate\",\"prompt\":\"Bu s\\u0131nav \\u00e7ocuk oyunca\\u011f\\u0131yd\\u0131.\",\"answer\":\"This exam was a piece of cake\",\"alternatives\":[\"The exam was a piece of cake\"],\"tiles\":[\"child\",\"piece\",\"was\",\"an\",\"of\",\"cake\",\"a\",\"exam\",\"This\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"Do not give up\",\"answer\":\"Do not give up\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I can\'t believe you turned down that offer!\",\"translation\":\"O teklifi reddetti\\u011fine inanam\\u0131yorum!\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
