\",\"audio\":\"The results indicate a significant decline\",\"options\":[\"The results indicate a significant decline\",\"The results indicate a significant design\",\"The result indicates a slight decline\"],\"answer\":0},{\"type\":\"translate\",\"prompt\":\"Bu s\\u0131nav \\u00e7ocuk oyunca\\u011f\\u0131yd\\u0131.\",\"answer\":\"This exam was a piece of cake\",\"alternatives\":[\"The exam was a piece of cake\"],\"tiles\":[\"child\",\"piece\",\"was\",\"an\",\"of\",\"cake\",\"a\",\"exam\",\"This\"]},{\"type\":\"listen_type\",\"prompt\":\"Duydu\\u011funu yaz\",\"audio\":\"We need to find out the truth\",\"answer\":\"We need to find out the truth\"},{\"type\":\"speak\",\"prompt\":\"Sesli s\\u00f6yle\",\"text\":\"I can\'t believe you turned down that offer!\",\"translation\":\"O teklifi reddetti\\u011fine inanam\\u0131yorum!\"}]',NULL,'2026-10-03 04:21:53','2026-10-03 04:21:53');
