(32,'freeze_pair','Seri Koruma İkilisi','2 seri dondurucu, tek tek almaktan 50 elmas ucuz.','bundle','{\"items\":[{\"item\":\"streak_freeze\",\"qty\":2}]}',350,'snowflake','common',1,31,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
