(36,'mystery_chest','Gizemli Sandık','Elmas, XP takviyesi, seri dondurucu, iş ortaklarımızdan hediye kuponları... ya da efsanevi bir kart!','chest','{\"pool\":[{\"weight\":36,\"type\":\"gems\",\"amount\":150},{\"weight\":22,\"type\":\"item\",\"item\":\"xp_boost_15\"},{\"weight\":18,\"type\":\"item\",\"item\":\"streak_freeze\"},{\"weight\":10,\"type\":\"partner\"},{\"weight\":8,\"type\":\"item\",\"item\":\"premium_3d\"},{\"weight\":5,\"type\":\"item\",\"item\":\"discount_20\"},{\"weight\":1,\"type\":\"item\",\"item\":\"live_lesson\"}]}',300,'chest','rare',1,35,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
