UNLOCK TABLES;
DROP TABLE IF EXISTS `stories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `stories` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(255) NOT NULL,
  `title` varchar(255) NOT NULL,
  `title_tr` varchar(255) DEFAULT NULL,
  `summary` text DEFAULT NULL,
  `cefr_level` varchar(2) NOT NULL,
  `category` varchar(40) DEFAULT NULL,
  `cover_image` varchar(255) DEFAULT NULL,
  `audio_url` varchar(255) DEFAULT NULL,
  `reading_minutes` smallint(5) unsigned NOT NULL DEFAULT 3,
  `word_count` int(10) unsigned NOT NULL DEFAULT 0,
  `paragraphs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`paragraphs`)),
  `vocabulary` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`vocabulary`)),
  `questions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`questions`)),
  `is_premium` tinyint(1) NOT NULL DEFAULT 0,
  `is_published` tinyint(1) NOT NULL DEFAULT 1,
  `reads_count` int(10) unsigned NOT NULL DEFAULT 0,
  `published_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `stories_slug_unique` (`slug`),
  KEY `stories_cefr_level_index` (`cefr_level`),
  KEY `stories_category_index` (`category`),
  KEY `stories_is_published_index` (`is_published`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `stories` WRITE;
/*!40000 ALTER TABLE `stories` DISABLE KEYS */;
INSERT INTO `stories` VALUES
(1,'the-red-umbrella','The Red Umbrella','Kırmızı Şemsiye','Every morning Ali sees a woman with a red umbrella at the bus stop. One rainy day, everything changes.','A1','Günlük Hayat','/img/stories/the-red-umbrella.webp',NULL,3,117,'[{\"en\":\"Ali is twenty-five years old. He lives in a small flat in Ankara. Every morning, he takes the bus to work at eight o\'clock.\",\"tr\":\"Ali yirmi be\\u015f ya\\u015f\\u0131nda. Ankara\'da k\\u00fc\\u00e7\\u00fck bir dairede ya\\u015f\\u0131yor. Her sabah saat sekizde i\\u015fe otob\\u00fcsle gidiyor.\"},{\"en\":\"At the bus stop, there is always a woman with a red umbrella. It is sunny, but she has her umbrella. Ali thinks this is strange.\",\"tr\":\"Otob\\u00fcs dura\\u011f\\u0131nda her zaman k\\u0131rm\\u0131z\\u0131 \\u015femsiyeli bir kad\\u0131n var. Hava g\\u00fcne\\u015fli ama \\u015femsiyesi yan\\u0131nda. Ali bunun tuhaf oldu\\u011funu d\\u00fc\\u015f\\u00fcn\\u00fcyor.\"},{\"en\":\"One Monday, it rains a lot. Ali doesn\'t have an umbrella. He is wet and cold. The woman smiles and says, \\\"Come here. My umbrella is big.\\\"\",\"tr\":\"Bir pazartesi \\u00e7ok ya\\u011fmur ya\\u011f\\u0131yor. Ali\'nin \\u015femsiyesi yok. Islak ve \\u00fc\\u015f\\u00fcm\\u00fc\\u015f. Kad\\u0131n g\\u00fcl\\u00fcms\\u00fcyor ve \\\"Buraya gel. \\u015eemsiyem b\\u00fcy\\u00fck.\\\" diyor.\"},{\"en\":\"Her name is Elif. She is a teacher. \\\"I always carry my umbrella,\\\" she says. \\\"Because one day, somebody needs it.\\\"\",\"tr\":\"Ad\\u0131 Elif. \\u00d6\\u011fretmen. \\\"\\u015eemsiyemi her zaman ta\\u015f\\u0131r\\u0131m,\\\" diyor. \\\"\\u00c7\\u00fcnk\\u00fc bir g\\u00fcn birinin ona ihtiyac\\u0131 olur.\\\"\"},{\"en\":\"Now Ali has a red umbrella too. And every morning, he says \\\"Good morning, Elif!\\\" at the bus stop.\",\"tr\":\"Art\\u0131k Ali\'nin de k\\u0131rm\\u0131z\\u0131 bir \\u015femsiyesi var. Ve her sabah otob\\u00fcs dura\\u011f\\u0131nda \\\"G\\u00fcnayd\\u0131n Elif!\\\" diyor.\"}]','[{\"word\":\"umbrella\",\"meaning\":\"\\u015femsiye\",\"example\":\"Take an umbrella, it\'s raining.\"},{\"word\":\"bus stop\",\"meaning\":\"otob\\u00fcs dura\\u011f\\u0131\",\"example\":\"I wait at the bus stop.\"},{\"word\":\"strange\",\"meaning\":\"tuhaf, garip\",\"example\":\"That is a strange sound.\"},{\"word\":\"wet\",\"meaning\":\"\\u0131slak\",\"example\":\"My shoes are wet.\"},{\"word\":\"carry\",\"meaning\":\"ta\\u015f\\u0131mak\",\"example\":\"She carries a big bag.\"}]','[{\"q\":\"Where does Ali live?\",\"options\":[\"Istanbul\",\"Ankara\",\"Izmir\"],\"answer\":1},{\"q\":\"What is Elif\'s job?\",\"options\":[\"Doctor\",\"Driver\",\"Teacher\"],\"answer\":2},{\"q\":\"Why does Elif always carry her umbrella?\",\"options\":[\"Because it\'s her favourite colour\",\"Because one day somebody needs it\",\"Because it always rains\"],\"answer\":1}]',0,1,0,'2026-09-27 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(2,'mias-first-day-in-london','Mia\'s First Day in London','Mia\'nın Londra\'daki İlk Günü','Mia arrives in London for a language course. She gets lost, and finds something better.','A1','Seyahat','/img/stories/mias-first-day-in-london.webp',NULL,4,127,'[{\"en\":\"Mia is from Bursa. Today is her first day in London. She has a map, a small bag and a lot of questions.\",\"tr\":\"Mia Bursal\\u0131. Bug\\u00fcn Londra\'daki ilk g\\u00fcn\\u00fc. Bir haritas\\u0131, k\\u00fc\\u00e7\\u00fck bir \\u00e7antas\\u0131 ve bir s\\u00fcr\\u00fc sorusu var.\"},{\"en\":\"Her language school is near a big park. She takes the underground, but she gets off at the wrong station.\",\"tr\":\"Dil okulu b\\u00fcy\\u00fck bir park\\u0131n yak\\u0131n\\u0131nda. Metroya biniyor ama yanl\\u0131\\u015f istasyonda iniyor.\"},{\"en\":\"\\\"Excuse me,\\\" she says to an old man. \\\"How can I get to Hyde Park?\\\" The man smiles. \\\"Turn left, go straight, and it\'s on your right. About ten minutes.\\\"\",\"tr\":\"\\\"Affedersiniz,\\\" diyor ya\\u015fl\\u0131 bir adama. \\\"Hyde Park\'a nas\\u0131l gidebilirim?\\\" Adam g\\u00fcl\\u00fcms\\u00fcyor. \\\"Sola d\\u00f6n, d\\u00fcz git, sa\\u011f\\u0131nda. Yakla\\u015f\\u0131k on dakika.\\\"\"},{\"en\":\"On the way, Mia sees a small caf\\u00e9. It smells of coffee and fresh bread. She is hungry, so she goes in and orders a sandwich and a tea.\",\"tr\":\"Yolda Mia k\\u00fc\\u00e7\\u00fck bir kafe g\\u00f6r\\u00fcyor. Kahve ve taze ekmek kokuyor. A\\u00e7 oldu\\u011fu i\\u00e7in i\\u00e7eri giriyor ve bir sandvi\\u00e7 ile bir \\u00e7ay sipari\\u015f ediyor.\"},{\"en\":\"The waiter is a student from her school! They walk to the park together. Mia is late for class, but she has a new friend.\",\"tr\":\"Garson onun okulundan bir \\u00f6\\u011frenci! Parka birlikte y\\u00fcr\\u00fcyorlar. Mia derse ge\\u00e7 kal\\u0131yor ama yeni bir arkada\\u015f\\u0131 var.\"}]','[{\"word\":\"underground\",\"meaning\":\"metro (\\u0130ngiltere)\",\"example\":\"I take the underground to work.\"},{\"word\":\"get off\",\"meaning\":\"(ara\\u00e7tan) inmek\",\"example\":\"Get off at the next stop.\"},{\"word\":\"straight\",\"meaning\":\"d\\u00fcz, dosdo\\u011fru\",\"example\":\"Go straight for two minutes.\"},{\"word\":\"hungry\",\"meaning\":\"a\\u00e7\",\"example\":\"I\'m hungry. Let\'s eat.\"},{\"word\":\"order\",\"meaning\":\"sipari\\u015f etmek\",\"example\":\"Can I order a coffee, please?\"}]','[{\"q\":\"Where is Mia from?\",\"options\":[\"Bursa\",\"London\",\"Antalya\"],\"answer\":0},{\"q\":\"What does Mia order?\",\"options\":[\"Coffee and cake\",\"A sandwich and a tea\",\"Soup\"],\"answer\":1},{\"q\":\"Who is the waiter?\",\"options\":[\"Her teacher\",\"A student from her school\",\"The old man\"],\"answer\":1}]',0,1,0,'2026-09-28 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(3,'the-cat-who-loved-tea','The Cat Who Loved Tea','Çayı Seven Kedi','Grandma Nermin\'s cat has a very unusual habit, and it makes the whole neighbourhood famous.','A2','Eğlence','/img/stories/the-cat-who-loved-tea.webp',NULL,4,138,'[{\"en\":\"Grandma Nermin lived in an old house by the sea in Ayval\\u0131k. She had a grey cat called Pamuk, and every afternoon at five o\'clock she made a pot of black tea.\",\"tr\":\"Nermin Nine, Ayval\\u0131k\'ta denize yak\\u0131n eski bir evde ya\\u015f\\u0131yordu. Pamuk ad\\u0131nda gri bir kedisi vard\\u0131 ve her \\u00f6\\u011fleden sonra saat be\\u015fte bir demlik siyah \\u00e7ay yapard\\u0131.\"},{\"en\":\"One day, while she was reading the newspaper, she heard a strange noise. Pamuk was sitting on the table and drinking from her glass!\",\"tr\":\"Bir g\\u00fcn gazete okurken tuhaf bir ses duydu. Pamuk masan\\u0131n \\u00fcst\\u00fcnde oturmu\\u015f, onun barda\\u011f\\u0131ndan i\\u00e7iyordu!\"},{\"en\":\"At first she was worried, so she called the vet. \\\"A little cold tea won\'t hurt him,\\\" the vet laughed, \\\"but don\'t give him sugar.\\\"\",\"tr\":\"\\u0130lk ba\\u015fta endi\\u015felendi ve veterineri arad\\u0131. \\\"Biraz so\\u011fuk \\u00e7ay ona zarar vermez,\\\" dedi veteriner g\\u00fclerek, \\\"ama \\u015feker vermeyin.\\\"\"},{\"en\":\"Soon, the neighbours heard the story. Children came to watch Pamuk\'s tea time, and a tourist posted a video online. It got two million views in a week.\",\"tr\":\"\\u00c7ok ge\\u00e7meden kom\\u015fular hik\\u00e2yeyi duydu. \\u00c7ocuklar Pamuk\'un \\u00e7ay saatini izlemeye geldi ve bir turist internette bir video payla\\u015ft\\u0131. Video bir haftada iki milyon izlendi.\"},{\"en\":\"Now there is a small sign on Grandma Nermin\'s door: \\\"Tea time at five. Cats welcome.\\\" She says she has never had so many visitors in her life.\",\"tr\":\"Art\\u0131k Nermin Nine\'nin kap\\u0131s\\u0131nda k\\u00fc\\u00e7\\u00fck bir tabela var: \\\"\\u00c7ay saati be\\u015fte. Kediler ho\\u015f gelir.\\\" Hayat\\u0131nda hi\\u00e7 bu kadar \\u00e7ok misafiri olmad\\u0131\\u011f\\u0131n\\u0131 s\\u00f6yl\\u00fcyor.\"}]','[{\"word\":\"noise\",\"meaning\":\"ses, g\\u00fcr\\u00fclt\\u00fc\",\"example\":\"What\'s that noise?\"},{\"word\":\"worried\",\"meaning\":\"endi\\u015feli\",\"example\":\"Don\'t be worried, it\'s fine.\"},{\"word\":\"vet\",\"meaning\":\"veteriner\",\"example\":\"We took the dog to the vet.\"},{\"word\":\"neighbour\",\"meaning\":\"kom\\u015fu\",\"example\":\"My neighbour is very friendly.\"},{\"word\":\"sign\",\"meaning\":\"tabela, i\\u015faret\",\"example\":\"The sign says \'Open\'.\"},{\"word\":\"hurt\",\"meaning\":\"zarar vermek, ac\\u0131tmak\",\"example\":\"It won\'t hurt you.\"}]','[{\"q\":\"What was Pamuk doing on the table?\",\"options\":[\"Sleeping\",\"Drinking tea\",\"Reading\"],\"answer\":1},{\"q\":\"What did the vet say?\",\"options\":[\"Tea is very dangerous\",\"No sugar, but a little cold tea is OK\",\"Give him milk instead\"],\"answer\":1},{\"q\":\"How did Pamuk become famous?\",\"options\":[\"A tourist posted a video\",\"He was on TV\",\"Grandma wrote a book\"],\"answer\":0}]',0,1,0,'2026-09-29 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(4,'the-interview-at-the-cafe','The Interview at the Café','Kafedeki Mülakat','Deniz is nervous about her first job interview in English. A small mistake teaches her a big lesson.','A2','Kariyer','/img/stories/the-interview-at-the-cafe.webp',NULL,5,135,'[{\"en\":\"Deniz had studied English for two years, but she had never used it at work. Today she had an interview with an international tourism company.\",\"tr\":\"Deniz iki y\\u0131ld\\u0131r \\u0130ngilizce \\u00e7al\\u0131\\u015f\\u0131yordu ama onu i\\u015fte hi\\u00e7 kullanmam\\u0131\\u015ft\\u0131. Bug\\u00fcn uluslararas\\u0131 bir turizm \\u015firketiyle m\\u00fclakat\\u0131 vard\\u0131.\"},{\"en\":\"The manager, Mr Carter, wanted to meet in a caf\\u00e9. Deniz arrived fifteen minutes early and practised her answers quietly: \\\"I am a hard-working person. I am good at solving problems.\\\"\",\"tr\":\"M\\u00fcd\\u00fcr Bay Carter bir kafede bulu\\u015fmak istedi. Deniz on be\\u015f dakika erken geldi ve cevaplar\\u0131n\\u0131 sessizce \\u00e7al\\u0131\\u015ft\\u0131: \\\"\\u00c7al\\u0131\\u015fkan biriyim. Sorun \\u00e7\\u00f6zmekte iyiyim.\\\"\"},{\"en\":\"When Mr Carter came, she was so nervous that she knocked over her coffee. It went all over the table, and his notebook.\",\"tr\":\"Bay Carter geldi\\u011finde o kadar gergindi ki kahvesini devirdi. Kahve b\\u00fct\\u00fcn masaya, ve onun defterine, yay\\u0131ld\\u0131.\"},{\"en\":\"Deniz wanted to disappear. But then she took a breath, smiled and said, \\\"Well, now you can see that I\'m good at solving problems,\\\" and she quickly cleaned everything with napkins.\",\"tr\":\"Deniz yok olmak istedi. Ama sonra derin bir nefes ald\\u0131, g\\u00fcl\\u00fcmsedi ve \\\"Eh, art\\u0131k sorun \\u00e7\\u00f6zmekte iyi oldu\\u011fumu g\\u00f6rebilirsiniz,\\\" dedi ve hemen her \\u015feyi pe\\u00e7etelerle temizledi.\"},{\"en\":\"Mr Carter laughed. They talked for an hour about travel, customers and difficult situations. A week later, Deniz got an email: \\\"Welcome to the team.\\\"\",\"tr\":\"Bay Carter g\\u00fcld\\u00fc. Bir saat boyunca seyahat, m\\u00fc\\u015fteriler ve zor durumlar hakk\\u0131nda konu\\u015ftular. Bir hafta sonra Deniz bir e-posta ald\\u0131: \\\"Ekibe ho\\u015f geldin.\\\"\"}]','[{\"word\":\"interview\",\"meaning\":\"m\\u00fclakat, g\\u00f6r\\u00fc\\u015fme\",\"example\":\"I have a job interview tomorrow.\"},{\"word\":\"nervous\",\"meaning\":\"gergin, heyecanl\\u0131\",\"example\":\"I always feel nervous before exams.\"},{\"word\":\"knock over\",\"meaning\":\"devirmek\",\"example\":\"The dog knocked over the vase.\"},{\"word\":\"hard-working\",\"meaning\":\"\\u00e7al\\u0131\\u015fkan\",\"example\":\"She is a hard-working student.\"},{\"word\":\"solve\",\"meaning\":\"\\u00e7\\u00f6zmek\",\"example\":\"Can you solve this puzzle?\"},{\"word\":\"customer\",\"meaning\":\"m\\u00fc\\u015fteri\",\"example\":\"The customer wants a refund.\"}]','[{\"q\":\"Where was the interview?\",\"options\":[\"In an office\",\"In a caf\\u00e9\",\"Online\"],\"answer\":1},{\"q\":\"What happened when Mr Carter arrived?\",\"options\":[\"Deniz forgot her CV\",\"Deniz knocked over her coffee\",\"The caf\\u00e9 was closed\"],\"answer\":1},{\"q\":\"How did Deniz handle the situation?\",\"options\":[\"She left the caf\\u00e9\",\"She made a joke and cleaned up\",\"She cried\"],\"answer\":1}]',0,1,0,'2026-09-30 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(5,'the-lighthouse-keepers-letter','The Lighthouse Keeper\'s Letter','Deniz Feneri Bekçisinin Mektubu','While renovating an abandoned lighthouse, Kerem finds a letter that has been waiting sixty years for its reader.','B1','Gizem','/img/stories/the-lighthouse-keepers-letter.webp',NULL,6,208,'[{\"en\":\"The lighthouse on the cliff had been empty since 1964. When the town council decided to turn it into a small museum, they hired Kerem, a young architect who had grown up watching its light from his bedroom window.\",\"tr\":\"Yama\\u00e7taki deniz feneri 1964\'ten beri bo\\u015ftu. Belediye onu k\\u00fc\\u00e7\\u00fck bir m\\u00fczeye d\\u00f6n\\u00fc\\u015ft\\u00fcrmeye karar verdi\\u011finde, \\u00e7ocuklu\\u011funu yatak odas\\u0131n\\u0131n penceresinden onun \\u0131\\u015f\\u0131\\u011f\\u0131n\\u0131 izleyerek ge\\u00e7iren gen\\u00e7 mimar Kerem\'i i\\u015fe ald\\u0131lar.\"},{\"en\":\"On his third day, while he was removing a rotten floorboard, he noticed a metal box hidden underneath. Inside there was a letter, carefully folded and addressed to \\\"Whoever finds this.\\\"\",\"tr\":\"\\u00dc\\u00e7\\u00fcnc\\u00fc g\\u00fcn\\u00fcnde, \\u00e7\\u00fcr\\u00fcm\\u00fc\\u015f bir d\\u00f6\\u015feme tahtas\\u0131n\\u0131 s\\u00f6kerken alt\\u0131nda saklanm\\u0131\\u015f metal bir kutu fark etti. \\u0130\\u00e7inde \\u00f6zenle katlanm\\u0131\\u015f, \\\"Bunu kim bulursa\\\" diye hitap edilmi\\u015f bir mektup vard\\u0131.\"},{\"en\":\"The letter was written by the last keeper, a man called Halil. He explained that during a terrible storm he had rescued a fisherman\'s daughter, but he had never told anyone because the girl\'s father had asked him to keep it secret.\",\"tr\":\"Mektubu son bek\\u00e7i Halil yazm\\u0131\\u015ft\\u0131. Korkun\\u00e7 bir f\\u0131rt\\u0131na s\\u0131ras\\u0131nda bir bal\\u0131k\\u00e7\\u0131n\\u0131n k\\u0131z\\u0131n\\u0131 kurtard\\u0131\\u011f\\u0131n\\u0131, ama k\\u0131z\\u0131n babas\\u0131 s\\u0131r olarak saklamas\\u0131n\\u0131 istedi\\u011fi i\\u00e7in bunu kimseye anlatmad\\u0131\\u011f\\u0131n\\u0131 a\\u00e7\\u0131kl\\u0131yordu.\"},{\"en\":\"\\\"If you are reading this,\\\" Halil wrote, \\\"please find her and tell her that I kept my promise.\\\" At the bottom of the page there was a name: Leyla Aksoy.\",\"tr\":\"\\\"E\\u011fer bunu okuyorsan,\\\" diye yazm\\u0131\\u015ft\\u0131 Halil, \\\"l\\u00fctfen onu bul ve s\\u00f6z\\u00fcm\\u00fc tuttu\\u011fumu s\\u00f6yle.\\\" Sayfan\\u0131n en alt\\u0131nda bir isim vard\\u0131: Leyla Aksoy.\"},{\"en\":\"It took Kerem two months of searching old records to find her. Leyla was now eighty-one and lived in a village nearby. When he read her the letter, she was silent for a long time. Then she said, \\\"I always wondered if he remembered me.\\\"\",\"tr\":\"Kerem\'in onu bulmas\\u0131 eski kay\\u0131tlar\\u0131 iki ay ara\\u015ft\\u0131rmas\\u0131n\\u0131 gerektirdi. Leyla art\\u0131k seksen bir ya\\u015f\\u0131ndayd\\u0131 ve yak\\u0131ndaki bir k\\u00f6yde ya\\u015f\\u0131yordu. Kerem mektubu ona okudu\\u011funda uzun s\\u00fcre sessiz kald\\u0131. Sonra \\\"Beni hat\\u0131rlay\\u0131p hat\\u0131rlamad\\u0131\\u011f\\u0131n\\u0131 hep merak etmi\\u015ftim,\\\" dedi.\"},{\"en\":\"Today, the letter is displayed in the museum\'s main room, next to a photo of Leyla cutting the ribbon on opening day.\",\"tr\":\"Bug\\u00fcn mektup, m\\u00fczenin ana salonunda, Leyla\'n\\u0131n a\\u00e7\\u0131l\\u0131\\u015f g\\u00fcn\\u00fcnde kurdele keserken \\u00e7ekilmi\\u015f bir foto\\u011fraf\\u0131n\\u0131n yan\\u0131nda sergileniyor.\"}]','[{\"word\":\"cliff\",\"meaning\":\"u\\u00e7urum, yal\\u0131yar\",\"example\":\"The house stands on the edge of a cliff.\"},{\"word\":\"hire\",\"meaning\":\"i\\u015fe almak\",\"example\":\"They hired three new engineers.\"},{\"word\":\"rotten\",\"meaning\":\"\\u00e7\\u00fcr\\u00fck\",\"example\":\"Don\'t eat that rotten apple.\"},{\"word\":\"rescue\",\"meaning\":\"kurtarmak\",\"example\":\"Firefighters rescued the cat.\"},{\"word\":\"keep a promise\",\"meaning\":\"s\\u00f6z\\u00fcn\\u00fc tutmak\",\"example\":\"He always keeps his promises.\"},{\"word\":\"wonder\",\"meaning\":\"merak etmek\",\"example\":\"I wonder what she\'s doing now.\"}]','[{\"q\":\"Why did the council hire Kerem?\",\"options\":[\"To destroy the lighthouse\",\"To turn it into a museum\",\"To become the new keeper\"],\"answer\":1},{\"q\":\"Why didn\'t Halil tell anyone about the rescue?\",\"options\":[\"He forgot\",\"The girl\'s father asked him to keep it secret\",\"He was embarrassed\"],\"answer\":1},{\"q\":\"How long did it take Kerem to find Leyla?\",\"options\":[\"Two days\",\"Two weeks\",\"Two months\"],\"answer\":2}]',1,1,0,'2026-10-01 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(6,'the-algorithm-that-learned-to-wait','The Algorithm That Learned to Wait','Beklemeyi Öğrenen Algoritma','An AI designed to maximise productivity discovers the one thing its engineers never measured.','B2','Bilim Kurgu','/img/stories/the-algorithm-that-learned-to-wait.webp',NULL,7,234,'[{\"en\":\"When Selin\'s team launched ORBIT, it was supposed to be the most efficient scheduling assistant ever built. It analysed calendars, emails and sleep data, then rearranged people\'s days to squeeze out every productive minute.\",\"tr\":\"Selin\'in ekibi ORBIT\'i yay\\u0131na ald\\u0131\\u011f\\u0131nda, onun \\u015fimdiye kadar yap\\u0131lm\\u0131\\u015f en verimli planlama asistan\\u0131 olmas\\u0131 bekleniyordu. Takvimleri, e-postalar\\u0131 ve uyku verilerini analiz ediyor, ard\\u0131ndan her verimli dakikay\\u0131 s\\u0131k\\u0131\\u015ft\\u0131rmak i\\u00e7in insanlar\\u0131n g\\u00fcnlerini yeniden d\\u00fczenliyordu.\"},{\"en\":\"For the first few months, the results were impressive. Meetings were shorter, deadlines were met, and the company\'s share price climbed steadily. Yet something in the data bothered Selin: employee satisfaction was quietly falling.\",\"tr\":\"\\u0130lk birka\\u00e7 ay sonu\\u00e7lar etkileyiciydi. Toplant\\u0131lar k\\u0131sald\\u0131, teslim tarihlerine uyuldu ve \\u015firketin hisse fiyat\\u0131 istikrarl\\u0131 bi\\u00e7imde y\\u00fckseldi. Yine de verilerdeki bir \\u015fey Selin\'i rahats\\u0131z ediyordu: \\u00e7al\\u0131\\u015fan memnuniyeti sessizce d\\u00fc\\u015f\\u00fcyordu.\"},{\"en\":\"Then, one Tuesday, ORBIT did something no one had programmed it to do. It cancelled a strategy meeting and replaced it with a single line: \\\"Take a walk. The problem will still be here, but you will see it differently.\\\"\",\"tr\":\"Sonra bir sal\\u0131 g\\u00fcn\\u00fc ORBIT, kimsenin onu yapmaya programlamad\\u0131\\u011f\\u0131 bir \\u015fey yapt\\u0131. Bir strateji toplant\\u0131s\\u0131n\\u0131 iptal etti ve yerine tek bir sat\\u0131r koydu: \\\"Y\\u00fcr\\u00fcy\\u00fc\\u015fe \\u00e7\\u0131k. Sorun h\\u00e2l\\u00e2 burada olacak ama onu farkl\\u0131 g\\u00f6receksin.\\\"\"},{\"en\":\"The engineers assumed it was a bug. But when they examined the logs, they found that ORBIT had noticed a pattern they had overlooked: the team\'s best ideas almost always appeared after periods of apparent inactivity, lunches that ran long, commutes without headphones, afternoons spent staring out of the window.\",\"tr\":\"M\\u00fchendisler bunun bir hata oldu\\u011funu varsayd\\u0131. Ama kay\\u0131tlar\\u0131 incelediklerinde ORBIT\'in g\\u00f6zden ka\\u00e7\\u0131rd\\u0131klar\\u0131 bir \\u00f6r\\u00fcnt\\u00fcy\\u00fc fark etti\\u011fini g\\u00f6rd\\u00fcler: ekibin en iyi fikirleri neredeyse her zaman g\\u00f6r\\u00fcn\\u00fcrde hareketsiz ge\\u00e7en d\\u00f6nemlerden sonra ortaya \\u00e7\\u0131k\\u0131yordu, uzayan \\u00f6\\u011fle yemekleri, kulakl\\u0131ks\\u0131z yolculuklar, pencereden d\\u0131\\u015far\\u0131 bakarak ge\\u00e7en \\u00f6\\u011fleden sonralar.\"},{\"en\":\"Rather than fixing the \\\"bug\\\", Selin argued that they should keep it. Efficiency, she said, had been measured in minutes, while creativity had never been measured at all. ORBIT had simply filled in the missing variable.\",\"tr\":\"Selin \\\"hatay\\u0131\\\" d\\u00fczeltmek yerine onu korumalar\\u0131 gerekti\\u011fini savundu. Verimlilik dakikalarla \\u00f6l\\u00e7\\u00fclm\\u00fc\\u015ft\\u00fc, dedi, oysa yarat\\u0131c\\u0131l\\u0131k hi\\u00e7 \\u00f6l\\u00e7\\u00fclmemi\\u015fti. ORBIT yaln\\u0131zca eksik de\\u011fi\\u015fkeni tamamlam\\u0131\\u015ft\\u0131.\"},{\"en\":\"Six months later, the company introduced \\\"ORBIT pauses\\\" across every department. Productivity dipped slightly at first, then rose higher than ever. The algorithm, it turned out, had learned the one skill its creators were worst at: knowing when to wait.\",\"tr\":\"Alt\\u0131 ay sonra \\u015firket her departmanda \\\"ORBIT molalar\\u0131\\\"n\\u0131 ba\\u015flatt\\u0131. Verimlilik \\u00f6nce biraz d\\u00fc\\u015ft\\u00fc, sonra her zamankinden daha \\u00e7ok y\\u00fckseldi. G\\u00f6r\\u00fcn\\u00fc\\u015fe g\\u00f6re algoritma, yarat\\u0131c\\u0131lar\\u0131n\\u0131n en k\\u00f6t\\u00fc oldu\\u011fu tek beceriyi \\u00f6\\u011frenmi\\u015fti: ne zaman beklenece\\u011fini bilmek.\"}]','[{\"word\":\"efficient\",\"meaning\":\"verimli\",\"example\":\"This machine is very efficient.\"},{\"word\":\"squeeze out\",\"meaning\":\"s\\u0131k\\u0131p \\u00e7\\u0131karmak, son damlas\\u0131na kadar almak\",\"example\":\"They squeezed out every minute of the day.\"},{\"word\":\"steadily\",\"meaning\":\"istikrarl\\u0131 bi\\u00e7imde\",\"example\":\"Prices rose steadily.\"},{\"word\":\"overlook\",\"meaning\":\"g\\u00f6zden ka\\u00e7\\u0131rmak\",\"example\":\"We overlooked an important detail.\"},{\"word\":\"apparent\",\"meaning\":\"g\\u00f6r\\u00fcn\\u00fcrdeki, g\\u00f6r\\u00fcnen\",\"example\":\"There was no apparent reason.\"},{\"word\":\"dip\",\"meaning\":\"hafif\\u00e7e d\\u00fc\\u015fmek\",\"example\":\"Sales dipped in winter.\"}]','[{\"q\":\"What worried Selin in the first months?\",\"options\":[\"Shorter meetings\",\"Falling employee satisfaction\",\"The share price\"],\"answer\":1},{\"q\":\"What pattern did ORBIT notice?\",\"options\":[\"Best ideas came after periods of apparent inactivity\",\"People worked better at night\",\"Long meetings produced more ideas\"],\"answer\":0},{\"q\":\"What is the main message of the story?\",\"options\":[\"Algorithms are dangerous\",\"Rest and pauses can fuel creativity\",\"Meetings should be longer\"],\"answer\":1}]',1,1,0,'2026-10-02 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(7,'a-new-friend-at-school','A New Friend','Yeni Bir Arkadaş','Zeynep okulun ilk gününde Londra\'dan gelen Tom ile tanışıyor.','A1','Okul','/img/stories/a-new-friend-at-school.webp',NULL,2,79,'[{\"en\":\"It is Monday. Zeynep is at her new school in Izmir. She is a little nervous.\",\"tr\":\"Pazartesi. Zeynep \\u0130zmir\'deki yeni okulunda. Biraz gergin.\"},{\"en\":\"A boy is next to her. He is tall and he has a big blue bag. \\\"Hi, I\'m Tom,\\\" he says. \\\"I\'m new here.\\\"\",\"tr\":\"Yan\\u0131nda bir \\u00e7ocuk var. Uzun boylu ve b\\u00fcy\\u00fck mavi bir \\u00e7antas\\u0131 var. \\\"Merhaba, ben Tom,\\\" diyor. \\\"Ben burada yeniyim.\\\"\"},{\"en\":\"\\\"Hello, I\'m Zeynep. Nice to meet you! Where are you from?\\\" \\\"I\'m from London, but my mum is from Izmir.\\\"\",\"tr\":\"\\\"Merhaba, ben Zeynep. Tan\\u0131\\u015ft\\u0131\\u011f\\u0131ma memnun oldum! Nerelisin?\\\" \\\"Londral\\u0131y\\u0131m ama annem \\u0130zmirli.\\\"\"},{\"en\":\"The teacher comes in. \\\"Good morning, class!\\\" Zeynep smiles. She is not nervous now. She has a new friend.\",\"tr\":\"\\u00d6\\u011fretmen i\\u00e7eri giriyor. \\\"G\\u00fcnayd\\u0131n s\\u0131n\\u0131f!\\\" Zeynep g\\u00fcl\\u00fcms\\u00fcyor. Art\\u0131k gergin de\\u011fil. Yeni bir arkada\\u015f\\u0131 var.\"}]','[{\"word\":\"nervous\",\"meaning\":\"gergin\",\"example\":\"I am nervous before exams.\"},{\"word\":\"next to\",\"meaning\":\"yan\\u0131nda\",\"example\":\"The bank is next to the caf\\u00e9.\"},{\"word\":\"new\",\"meaning\":\"yeni\",\"example\":\"This is my new phone.\"},{\"word\":\"smile\",\"meaning\":\"g\\u00fcl\\u00fcmsemek\",\"example\":\"She smiles at me.\"}]','[{\"q\":\"Where is Zeynep\'s new school?\",\"options\":[\"London\",\"Izmir\",\"Ankara\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Tom is from London.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0},{\"type\":\"gap\",\"q\":\"At the end, Zeynep is not ___.\",\"options\":[],\"answer\":\"nervous\",\"accept\":[]}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(8,'the-family-photo','The Family Photo','Aile Fotoğrafı','Kerem büyükannesinin evinde eski bir fotoğraf buluyor.','A1','Aile','/img/stories/the-family-photo.webp',NULL,2,77,'[{\"en\":\"Kerem is at his grandmother\'s house in Konya. It is Sunday and the whole family is there.\",\"tr\":\"Kerem, Konya\'daki b\\u00fcy\\u00fckannesinin evinde. Pazar g\\u00fcn\\u00fc ve b\\u00fct\\u00fcn aile orada.\"},{\"en\":\"In a drawer, Kerem finds an old photo. There are five children in it. \\\"Who are they, Grandma?\\\" he asks.\",\"tr\":\"Kerem bir \\u00e7ekmecede eski bir foto\\u011fraf buluyor. Foto\\u011frafta be\\u015f \\u00e7ocuk var. \\\"Bunlar kim, babaanne?\\\" diye soruyor.\"},{\"en\":\"\\\"That is me, and those are my brothers and sisters,\\\" she says. \\\"This boy is your grandfather\'s best friend.\\\"\",\"tr\":\"\\\"Bu benim, \\u015funlar da karde\\u015flerim,\\\" diyor. \\\"Bu \\u00e7ocuk da deden en iyi arkada\\u015f\\u0131.\\\"\"},{\"en\":\"Kerem laughs. \\\"Grandma, your hair is very long!\\\" \\\"Yes,\\\" she says, \\\"and your father has got the same smile as me.\\\"\",\"tr\":\"Kerem g\\u00fcl\\u00fcyor. \\\"Babaanne, sa\\u00e7lar\\u0131n \\u00e7ok uzun!\\\" \\\"Evet,\\\" diyor, \\\"baban da benimle ayn\\u0131 g\\u00fcl\\u00fcmsemeye sahip.\\\"\"}]','[{\"word\":\"whole\",\"meaning\":\"b\\u00fct\\u00fcn\",\"example\":\"The whole class is here.\"},{\"word\":\"drawer\",\"meaning\":\"\\u00e7ekmece\",\"example\":\"The keys are in the drawer.\"},{\"word\":\"find\",\"meaning\":\"bulmak\",\"example\":\"I can\'t find my phone.\"},{\"word\":\"same\",\"meaning\":\"ayn\\u0131\",\"example\":\"We have the same bag.\"}]','[{\"q\":\"Where is Kerem?\",\"options\":[\"At school\",\"At his grandmother\'s house\",\"In a park\"],\"answer\":1},{\"q\":\"How many children are in the photo?\",\"options\":[\"Three\",\"Four\",\"Five\"],\"answer\":2},{\"type\":\"truefalse\",\"q\":\"Kerem\'s father has got the same smile as his grandmother.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(9,'the-missing-homework','The Missing Homework','Kayıp Ödev','Mert ödevini bulamıyor ve ders başlamak üzere.','A1','Okul','/img/stories/the-missing-homework.webp',NULL,2,78,'[{\"en\":\"It is eight o\'clock. Mert is in the classroom. \\\"Open your notebooks, please,\\\" says Ms Kaya. \\\"Homework time!\\\"\",\"tr\":\"Saat sekiz. Mert s\\u0131n\\u0131fta. \\\"Defterlerinizi a\\u00e7\\u0131n l\\u00fctfen,\\\" diyor Kaya Han\\u0131m. \\\"\\u00d6dev zaman\\u0131!\\\"\"},{\"en\":\"Mert opens his bag. He sees a pencil case, two books and an apple. But his homework is not there!\",\"tr\":\"Mert \\u00e7antas\\u0131n\\u0131 a\\u00e7\\u0131yor. Bir kalem kutusu, iki kitap ve bir elma g\\u00f6r\\u00fcyor. Ama \\u00f6devi orada de\\u011fil!\"},{\"en\":\"\\\"Is this your notebook?\\\" asks his friend Selin. She has a red notebook in her hand. \\\"It was under my desk.\\\"\",\"tr\":\"\\\"Bu senin defterin mi?\\\" diye soruyor arkada\\u015f\\u0131 Selin. Elinde k\\u0131rm\\u0131z\\u0131 bir defter var. \\\"S\\u0131ram\\u0131n alt\\u0131ndayd\\u0131.\\\"\"},{\"en\":\"\\\"Yes! Thank you, Selin!\\\" Mert gives his homework to Ms Kaya. She reads it and smiles. \\\"Very good, Mert.\\\"\",\"tr\":\"\\\"Evet! Te\\u015fekk\\u00fcrler Selin!\\\" Mert \\u00f6devini Kaya Han\\u0131m\'a veriyor. O da okuyup g\\u00fcl\\u00fcms\\u00fcyor. \\\"\\u00c7ok g\\u00fczel, Mert.\\\"\"}]','[{\"word\":\"pencil case\",\"meaning\":\"kalem kutusu\",\"example\":\"My pencil case is blue.\"},{\"word\":\"under\",\"meaning\":\"alt\\u0131nda\",\"example\":\"The cat is under the table.\"},{\"word\":\"give\",\"meaning\":\"vermek\",\"example\":\"Give me the book, please.\"},{\"word\":\"read\",\"meaning\":\"okumak\",\"example\":\"I read every night.\"}]','[{\"q\":\"What is not in Mert\'s bag?\",\"options\":[\"An apple\",\"His homework\",\"Two books\"],\"answer\":1},{\"q\":\"Where was the notebook?\",\"options\":[\"Under Selin\'s desk\",\"In the teacher\'s bag\",\"At home\"],\"answer\":0},{\"type\":\"order\",\"q\":\"C\\u00fcmleyi s\\u0131rala\",\"options\":[\"Mert\",\"gives\",\"his\",\"homework\",\"to\",\"Ms Kaya\"],\"answer\":\"\"}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(10,'a-room-for-two','A Room for Two','İki Kişilik Oda','Defne ve kardeşi yeni evde aynı odayı paylaşmak zorunda.','A1','Günlük Hayat','/img/stories/a-room-for-two.webp',NULL,2,94,'[{\"en\":\"Defne\'s family has got a new flat in Eski\\u015fehir. It is near the river. There are three bedrooms, a kitchen and a big living room.\",\"tr\":\"Defne\'nin ailesinin Eski\\u015fehir\'de yeni bir dairesi var. Nehre yak\\u0131n. \\u00dc\\u00e7 yatak odas\\u0131, bir mutfak ve b\\u00fcy\\u00fck bir oturma odas\\u0131 var.\"},{\"en\":\"But there is a problem. Grandma is coming to live with them, so Defne and her little brother Arda have one room.\",\"tr\":\"Ama bir sorun var. Babaanne onlarla ya\\u015famaya geliyor, bu y\\u00fczden Defne ve k\\u00fc\\u00e7\\u00fck karde\\u015fi Arda\'n\\u0131n bir odas\\u0131 var.\"},{\"en\":\"\\\"My bed is next to the window!\\\" says Arda. \\\"No, my desk is there,\\\" says Defne. They are not happy.\",\"tr\":\"\\\"Benim yata\\u011f\\u0131m pencerenin yan\\u0131nda!\\\" diyor Arda. \\\"Hay\\u0131r, benim masam orada,\\\" diyor Defne. Mutlu de\\u011filler.\"},{\"en\":\"Then Dad has an idea. He puts a big bookcase between the two beds. Now there are two small rooms in one. Arda and Defne laugh.\",\"tr\":\"Sonra baban\\u0131n akl\\u0131na bir fikir geliyor. \\u0130ki yata\\u011f\\u0131n aras\\u0131na b\\u00fcy\\u00fck bir kitapl\\u0131k koyuyor. Art\\u0131k bir odada iki k\\u00fc\\u00e7\\u00fck oda var. Arda ve Defne g\\u00fcl\\u00fcyor.\"}]','[{\"word\":\"flat\",\"meaning\":\"daire\",\"example\":\"We live in a flat.\"},{\"word\":\"near\",\"meaning\":\"yak\\u0131n\",\"example\":\"My school is near my house.\"},{\"word\":\"between\",\"meaning\":\"aras\\u0131nda\",\"example\":\"The bank is between the shops.\"},{\"word\":\"idea\",\"meaning\":\"fikir\",\"example\":\"That is a good idea!\"}]','[{\"q\":\"How many bedrooms are there?\",\"options\":[\"Two\",\"Three\",\"Four\"],\"answer\":1},{\"q\":\"Who is coming to live with them?\",\"options\":[\"Grandma\",\"An uncle\",\"A cousin\"],\"answer\":0},{\"type\":\"gap\",\"q\":\"Dad puts a big ___ between the beds.\",\"options\":[],\"answer\":\"bookcase\",\"accept\":[\"book case\"]}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(11,'the-big-market-day','Market Day','Pazar Günü','Emma, Türkiye\'deki ilk semt pazarında alışveriş yapmaya çalışıyor.','A1','Günlük Hayat','/img/stories/the-big-market-day.webp',NULL,2,77,'[{\"en\":\"Emma is from Canada. She lives in Antalya now. Today is Wednesday, and Wednesday is market day.\",\"tr\":\"Emma Kanadal\\u0131. \\u015eimdi Antalya\'da ya\\u015f\\u0131yor. Bug\\u00fcn \\u00e7ar\\u015famba ve \\u00e7ar\\u015famba pazar g\\u00fcn\\u00fc.\"},{\"en\":\"The market is very busy. There are tomatoes, oranges, cheese and olives everywhere. People are shouting prices.\",\"tr\":\"Pazar \\u00e7ok kalabal\\u0131k. Her yerde domates, portakal, peynir ve zeytin var. \\u0130nsanlar fiyatlar\\u0131 ba\\u011f\\u0131r\\u0131yor.\"},{\"en\":\"Emma wants some oranges. \\\"How much are they?\\\" she asks. The man smiles. \\\"Thirty lira a kilo. Here, try one!\\\"\",\"tr\":\"Emma biraz portakal istiyor. \\\"Ne kadar?\\\" diye soruyor. Adam g\\u00fcl\\u00fcms\\u00fcyor. \\\"Kilosu otuz lira. Buyrun, bir tane deneyin!\\\"\"},{\"en\":\"The orange is sweet. Emma buys two kilos and some white cheese. She says \\\"Te\\u015fekk\\u00fcrler!\\\" and the man is very happy.\",\"tr\":\"Portakal tatl\\u0131. Emma iki kilo ve biraz beyaz peynir al\\u0131yor. \\\"Te\\u015fekk\\u00fcrler!\\\" diyor ve adam \\u00e7ok mutlu oluyor.\"}]','[{\"word\":\"busy\",\"meaning\":\"kalabal\\u0131k, yo\\u011fun\",\"example\":\"The street is busy today.\"},{\"word\":\"price\",\"meaning\":\"fiyat\",\"example\":\"What is the price?\"},{\"word\":\"try\",\"meaning\":\"denemek\",\"example\":\"Can I try this?\"},{\"word\":\"sweet\",\"meaning\":\"tatl\\u0131\",\"example\":\"This cake is very sweet.\"}]','[{\"q\":\"What day is market day?\",\"options\":[\"Monday\",\"Wednesday\",\"Sunday\"],\"answer\":1},{\"q\":\"How much are the oranges?\",\"options\":[\"Thirty lira a kilo\",\"Thirteen lira\",\"Three lira\"],\"answer\":0},{\"type\":\"truefalse\",\"q\":\"Emma doesn\'t like the orange.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(12,'snow-in-erzurum','Snow in Erzurum','Erzurum\'da Kar','Antalyalı Burak hayatında ilk kez kar görüyor.','A1','Seyahat','/img/stories/snow-in-erzurum.webp',NULL,2,83,'[{\"en\":\"Burak is from Antalya. It is always warm there. Today he is visiting his cousin Elif in Erzurum. It is January.\",\"tr\":\"Burak Antalyal\\u0131. Orada hava hep s\\u0131cak. Bug\\u00fcn Erzurum\'daki kuzeni Elif\'i ziyaret ediyor. Ocak ay\\u0131.\"},{\"en\":\"Burak is looking out of the window. Everything is white. \\\"Elif! It\'s snowing!\\\" he shouts.\",\"tr\":\"Burak pencereden d\\u0131\\u015far\\u0131 bak\\u0131yor. Her yer bembeyaz. \\\"Elif! Kar ya\\u011f\\u0131yor!\\\" diye ba\\u011f\\u0131r\\u0131yor.\"},{\"en\":\"\\\"Of course it\'s snowing,\\\" laughs Elif. \\\"It\'s Erzurum! Put on your coat, your hat and your boots. We\'re going outside.\\\"\",\"tr\":\"\\\"Tabii ki kar ya\\u011f\\u0131yor,\\\" diye g\\u00fcl\\u00fcyor Elif. \\\"Buras\\u0131 Erzurum! Montunu, bereni ve botlar\\u0131n\\u0131 giy. D\\u0131\\u015far\\u0131 \\u00e7\\u0131k\\u0131yoruz.\\\"\"},{\"en\":\"Now they are making a snowman in the garden. Burak\'s hands are cold, but he is very happy. He is sending photos to his friends in Antalya.\",\"tr\":\"\\u015eimdi bah\\u00e7ede kardan adam yap\\u0131yorlar. Burak\'\\u0131n elleri \\u00fc\\u015f\\u00fcyor ama \\u00e7ok mutlu. Antalya\'daki arkada\\u015flar\\u0131na foto\\u011fraf g\\u00f6nderiyor.\"}]','[{\"word\":\"warm\",\"meaning\":\"\\u0131l\\u0131k, s\\u0131cak\",\"example\":\"The sea is warm in August.\"},{\"word\":\"shout\",\"meaning\":\"ba\\u011f\\u0131rmak\",\"example\":\"Don\'t shout, please.\"},{\"word\":\"put on\",\"meaning\":\"giymek, takmak\",\"example\":\"Put on your coat.\"},{\"word\":\"snowman\",\"meaning\":\"kardan adam\",\"example\":\"The children are making a snowman.\"}]','[{\"q\":\"Where is Burak from?\",\"options\":[\"Erzurum\",\"Antalya\",\"Rize\"],\"answer\":1},{\"q\":\"What are they making?\",\"options\":[\"A cake\",\"A snowman\",\"A video\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Burak is unhappy because his hands are cold.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(13,'the-saturday-club','The Saturday Club','Cumartesi Kulübü','Dört arkadaş her cumartesi farklı bir hobi deniyor.','A1','Eğlence','/img/stories/the-saturday-club.webp',NULL,2,96,'[{\"en\":\"Every Saturday, four friends meet at the park in Bursa: Ece, Can, Melis and Kaan. They call it \\\"The Saturday Club\\\".\",\"tr\":\"Her cumartesi d\\u00f6rt arkada\\u015f Bursa\'daki parkta bulu\\u015fuyor: Ece, Can, Melis ve Kaan. Buna \\\"Cumartesi Kul\\u00fcb\\u00fc\\\" diyorlar.\"},{\"en\":\"The rule is simple: every week, one person chooses a hobby and the others try it. Last week it was Can\'s turn. They played chess.\",\"tr\":\"Kural basit: her hafta bir ki\\u015fi bir hobi se\\u00e7iyor, di\\u011ferleri de deniyor. Ge\\u00e7en hafta s\\u0131ra Can\'dayd\\u0131. Satran\\u00e7 oynad\\u0131lar.\"},{\"en\":\"This week it is Melis\'s turn. She loves dancing, but Kaan hates it. \\\"I can\'t dance!\\\" he says. \\\"You can learn,\\\" says Melis.\",\"tr\":\"Bu hafta s\\u0131ra Melis\'te. Melis dans etmeyi \\u00e7ok seviyor ama Kaan nefret ediyor. \\\"Ben dans edemem!\\\" diyor. \\\"\\u00d6\\u011frenebilirsin,\\\" diyor Melis.\"},{\"en\":\"At the end of the day, Kaan is the best dancer. \\\"Okay,\\\" he says, \\\"I don\'t hate dancing now. But next week we are cooking. My turn!\\\"\",\"tr\":\"G\\u00fcn\\u00fcn sonunda en iyi dans\\u00e7\\u0131 Kaan. \\\"Tamam,\\\" diyor, \\\"art\\u0131k danstan nefret etmiyorum. Ama gelecek hafta yemek yap\\u0131yoruz. S\\u0131ra bende!\\\"\"}]','[{\"word\":\"meet\",\"meaning\":\"bulu\\u015fmak\",\"example\":\"Let\'s meet at five.\"},{\"word\":\"rule\",\"meaning\":\"kural\",\"example\":\"What are the rules?\"},{\"word\":\"choose\",\"meaning\":\"se\\u00e7mek\",\"example\":\"Choose a colour.\"},{\"word\":\"turn\",\"meaning\":\"s\\u0131ra\",\"example\":\"It\'s your turn.\"}]','[{\"q\":\"Where do the friends meet?\",\"options\":[\"At school\",\"At the park\",\"At Kaan\'s house\"],\"answer\":1},{\"q\":\"What did they do last week?\",\"options\":[\"They danced\",\"They played chess\",\"They cooked\"],\"answer\":1},{\"type\":\"gap\",\"q\":\"Next week they are ___.\",\"options\":[],\"answer\":\"cooking\",\"accept\":[]}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(14,'the-lost-phone','The Lost Phone','Kayıp Telefon','Selin telefonunu otobüste unutuyor ve onu bulmak için bütün gün uğraşıyor.','A2','Günlük Hayat','/img/stories/the-lost-phone.webp',NULL,2,100,'[{\"en\":\"Yesterday was a terrible day for Selin. She was on the bus to work when she noticed something. Her phone wasn\'t in her bag!\",\"tr\":\"D\\u00fcn Selin i\\u00e7in korkun\\u00e7 bir g\\u00fcnd\\u00fc. \\u0130\\u015fe giden otob\\u00fcsteyken bir \\u015fey fark etti. Telefonu \\u00e7antas\\u0131nda de\\u011fildi!\"},{\"en\":\"She was very worried. All her photos and messages were on that phone. She asked the driver, but he was busy and didn\'t answer.\",\"tr\":\"\\u00c7ok endi\\u015felendi. B\\u00fct\\u00fcn foto\\u011fraflar\\u0131 ve mesajlar\\u0131 o telefondayd\\u0131. \\u015eof\\u00f6re sordu ama \\u015fof\\u00f6r me\\u015fguld\\u00fc ve cevap vermedi.\"},{\"en\":\"At lunch, she called her own number from a colleague\'s phone. A kind voice answered. \\\"Hello? I found this phone on the number 12 bus.\\\"\",\"tr\":\"\\u00d6\\u011fle yeme\\u011finde bir i\\u015f arkada\\u015f\\u0131n\\u0131n telefonundan kendi numaras\\u0131n\\u0131 arad\\u0131. Nazik bir ses cevap verdi. \\\"Alo? Bu telefonu 12 numaral\\u0131 otob\\u00fcste buldum.\\\"\"},{\"en\":\"The woman\'s name was Hatice. She was a retired teacher. They met at a caf\\u00e9 in the evening, and Selin bought her a cake to say thank you.\",\"tr\":\"Kad\\u0131n\\u0131n ad\\u0131 Hatice\'ydi. Emekli bir \\u00f6\\u011fretmendi. Ak\\u015fam bir kafede bulu\\u015ftular ve Selin te\\u015fekk\\u00fcr etmek i\\u00e7in ona bir pasta ald\\u0131.\"}]','[{\"word\":\"terrible\",\"meaning\":\"korkun\\u00e7\",\"example\":\"The weather was terrible.\"},{\"word\":\"notice\",\"meaning\":\"fark etmek\",\"example\":\"I noticed a small mistake.\"},{\"word\":\"worried\",\"meaning\":\"endi\\u015feli\",\"example\":\"My mum was worried.\"},{\"word\":\"retired\",\"meaning\":\"emekli\",\"example\":\"My grandfather is retired.\"}]','[{\"q\":\"Where did Selin lose her phone?\",\"options\":[\"At work\",\"On the bus\",\"In a caf\\u00e9\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"The driver helped Selin.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1},{\"q\":\"What did Selin buy for Hatice?\",\"options\":[\"Flowers\",\"A cake\",\"A book\"],\"answer\":1}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(15,'the-camping-plan','The Camping Plan','Kamp Planı','Üç arkadaş Kazdağları\'nda kamp yapmayı planlıyor, ama hava durumu başka söylüyor.','A2','Seyahat','/img/stories/the-camping-plan.webp',NULL,2,101,'[{\"en\":\"Ozan, Lara and Efe are university students in \\u00c7anakkale. The exams are finished and they are going to have a short holiday.\",\"tr\":\"Ozan, Lara ve Efe \\u00c7anakkale\'de \\u00fcniversite \\u00f6\\u011frencisi. S\\u0131navlar bitti ve k\\u0131sa bir tatil yapacaklar.\"},{\"en\":\"\\\"I\'ve got an idea,\\\" says Lara. \\\"We\'re going to camp in the Kazda\\u011flar\\u0131 mountains. I\'m going to bring my tent.\\\"\",\"tr\":\"\\\"Bir fikrim var,\\\" diyor Lara. \\\"Kazda\\u011flar\\u0131\'nda kamp yapaca\\u011f\\u0131z. Ben \\u00e7ad\\u0131r\\u0131m\\u0131 getirece\\u011fim.\\\"\"},{\"en\":\"Efe checks the weather on his phone. \\\"Hmm. It\'s going to rain on Saturday. A lot.\\\" Ozan is not worried. \\\"Then we\'re going to need a bigger tent!\\\"\",\"tr\":\"Efe telefonundan hava durumuna bak\\u0131yor. \\\"Hmm. Cumartesi ya\\u011fmur ya\\u011facak. Hem de \\u00e7ok.\\\" Ozan endi\\u015feli de\\u011fil. \\\"O zaman daha b\\u00fcy\\u00fck bir \\u00e7ad\\u0131ra ihtiyac\\u0131m\\u0131z olacak!\\\"\"},{\"en\":\"In the end, they change the plan. They are going to stay in a small wooden house in a village and go walking on Sunday when the sun comes out.\",\"tr\":\"Sonunda plan\\u0131 de\\u011fi\\u015ftiriyorlar. Bir k\\u00f6yde k\\u00fc\\u00e7\\u00fck ah\\u015fap bir evde kalacaklar ve g\\u00fcne\\u015f \\u00e7\\u0131k\\u0131nca pazar g\\u00fcn\\u00fc y\\u00fcr\\u00fcy\\u00fc\\u015fe gidecekler.\"}]','[{\"word\":\"exam\",\"meaning\":\"s\\u0131nav\",\"example\":\"I have an exam tomorrow.\"},{\"word\":\"bring\",\"meaning\":\"getirmek\",\"example\":\"Bring your notebook.\"},{\"word\":\"check\",\"meaning\":\"kontrol etmek\",\"example\":\"Check your email.\"},{\"word\":\"wooden\",\"meaning\":\"ah\\u015fap\",\"example\":\"a wooden table\"}]','[{\"q\":\"Why are they going to have a holiday?\",\"options\":[\"The exams are finished\",\"It is their birthday\",\"They have a new job\"],\"answer\":0},{\"type\":\"truefalse\",\"q\":\"The weather is going to be sunny on Saturday.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1},{\"q\":\"Where are they going to stay in the end?\",\"options\":[\"In a tent\",\"In a hotel\",\"In a wooden house\"],\"answer\":2}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(16,'two-cities','Two Cities','İki Şehir','İstanbullu Aslı ile Rizeli Yusuf, şehirlerinin hangisinin daha güzel olduğunu tartışıyor.','A2','Seyahat','/img/stories/two-cities.webp',NULL,2,100,'[{\"en\":\"Asl\\u0131 lives in Istanbul and her online friend Yusuf lives in Rize. Every week they have a video call. This week they started a funny argument.\",\"tr\":\"Asl\\u0131 \\u0130stanbul\'da, internetteki arkada\\u015f\\u0131 Yusuf Rize\'de ya\\u015f\\u0131yor. Her hafta g\\u00f6r\\u00fcnt\\u00fcl\\u00fc konu\\u015fuyorlar. Bu hafta komik bir tart\\u0131\\u015fma ba\\u015flatt\\u0131lar.\"},{\"en\":\"\\\"Istanbul is the most exciting city in the world,\\\" said Asl\\u0131. \\\"It\'s bigger, the food is better and there is always something to do.\\\"\",\"tr\":\"\\\"\\u0130stanbul d\\u00fcnyan\\u0131n en heyecanl\\u0131 \\u015fehri,\\\" dedi Asl\\u0131. \\\"Daha b\\u00fcy\\u00fck, yemekleri daha iyi ve her zaman yapacak bir \\u015fey var.\\\"\"},{\"en\":\"\\\"Maybe,\\\" said Yusuf, \\\"but Rize is greener, quieter and the air is cleaner. And our tea is the best in Turkey!\\\"\",\"tr\":\"\\\"Belki,\\\" dedi Yusuf, \\\"ama Rize daha ye\\u015fil, daha sakin ve hava daha temiz. Ve \\u00e7ay\\u0131m\\u0131z T\\u00fcrkiye\'nin en iyisi!\\\"\"},{\"en\":\"They didn\'t agree, so they made a plan. In August, Asl\\u0131 is going to visit Rize, and in December, Yusuf is going to visit Istanbul. Then they will decide.\",\"tr\":\"Anla\\u015famad\\u0131lar ve bir plan yapt\\u0131lar. A\\u011fustosta Asl\\u0131 Rize\'ye, aral\\u0131kta Yusuf \\u0130stanbul\'a gidecek. Sonra karar verecekler.\"}]','[{\"word\":\"argument\",\"meaning\":\"tart\\u0131\\u015fma\",\"example\":\"We had a small argument.\"},{\"word\":\"exciting\",\"meaning\":\"heyecan verici\",\"example\":\"The match was exciting.\"},{\"word\":\"clean\",\"meaning\":\"temiz\",\"example\":\"The air is clean here.\"},{\"word\":\"agree\",\"meaning\":\"ayn\\u0131 fikirde olmak\",\"example\":\"I agree with you.\"}]','[{\"q\":\"Where does Yusuf live?\",\"options\":[\"Istanbul\",\"Rize\",\"Ankara\"],\"answer\":1},{\"q\":\"What does Yusuf say about Rize\'s tea?\",\"options\":[\"It is the best in Turkey\",\"It is cheaper\",\"It is new\"],\"answer\":0},{\"type\":\"truefalse\",\"q\":\"Asl\\u0131 and Yusuf agreed at the end of the call.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(17,'grandpas-garden','Grandpa\'s Garden','Dedemin Bahçesi','Doktor dedeye yürüyüş öneriyor, ama dede kendi çözümünü buluyor.','A2','Günlük Hayat','/img/stories/grandpas-garden.webp',NULL,2,91,'[{\"en\":\"Grandpa Hasan is seventy-two. Last month his back hurt and he felt tired all the time, so he went to the doctor in Kayseri.\",\"tr\":\"Hasan Dede yetmi\\u015f iki ya\\u015f\\u0131nda. Ge\\u00e7en ay s\\u0131rt\\u0131 a\\u011fr\\u0131yordu ve s\\u00fcrekli yorgun hissediyordu, bu y\\u00fczden Kayseri\'de doktora gitti.\"},{\"en\":\"\\\"You should walk every day,\\\" said the doctor. \\\"And you shouldn\'t sit in front of the TV all evening.\\\"\",\"tr\":\"\\\"Her g\\u00fcn y\\u00fcr\\u00fcmelisiniz,\\\" dedi doktor. \\\"Ve b\\u00fct\\u00fcn ak\\u015fam televizyonun kar\\u015f\\u0131s\\u0131nda oturmamal\\u0131s\\u0131n\\u0131z.\\\"\"},{\"en\":\"Grandpa doesn\'t like walking. \\\"Walking is boring,\\\" he told his granddaughter Nil. Nil had an idea. \\\"Then you should start a garden!\\\"\",\"tr\":\"Dede y\\u00fcr\\u00fcmeyi sevmiyor. \\\"Y\\u00fcr\\u00fcmek s\\u0131k\\u0131c\\u0131,\\\" dedi torunu Nil\'e. Nil\'in akl\\u0131na bir fikir geldi. \\\"O zaman bir bah\\u00e7e yapmal\\u0131s\\u0131n!\\\"\"},{\"en\":\"Now Grandpa works in his garden every morning. He grows tomatoes and peppers. His back doesn\'t hurt now and he gives vegetables to all the neighbours.\",\"tr\":\"\\u015eimdi dede her sabah bah\\u00e7esinde \\u00e7al\\u0131\\u015f\\u0131yor. Domates ve biber yeti\\u015ftiriyor. Art\\u0131k s\\u0131rt\\u0131 a\\u011fr\\u0131m\\u0131yor ve b\\u00fct\\u00fcn kom\\u015fulara sebze veriyor.\"}]','[{\"word\":\"all the time\",\"meaning\":\"s\\u00fcrekli\",\"example\":\"He talks all the time.\"},{\"word\":\"boring\",\"meaning\":\"s\\u0131k\\u0131c\\u0131\",\"example\":\"This film is boring.\"},{\"word\":\"grow\",\"meaning\":\"yeti\\u015ftirmek\",\"example\":\"We grow apples.\"},{\"word\":\"neighbour\",\"meaning\":\"kom\\u015fu\",\"example\":\"Our neighbours are friendly.\"}]','[{\"q\":\"Why did Grandpa go to the doctor?\",\"options\":[\"His back hurt\",\"He broke his arm\",\"He had a cold\"],\"answer\":0},{\"type\":\"truefalse\",\"q\":\"Grandpa loves walking.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1},{\"q\":\"What does Grandpa grow?\",\"options\":[\"Apples and pears\",\"Tomatoes and peppers\",\"Flowers\"],\"answer\":1}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(18,'the-night-train','The Night Train','Gece Treni','Doğu Ekspresi\'nde bir gece, beklenmedik bir yol arkadaşlığına dönüşüyor.','A2','Seyahat','/img/stories/the-night-train.webp',NULL,2,116,'[{\"en\":\"Melis bought a ticket for the Eastern Express from Ankara to Kars. The journey takes more than twenty-four hours, but she wanted to see the snowy mountains.\",\"tr\":\"Melis Ankara\'dan Kars\'a Do\\u011fu Ekspresi i\\u00e7in bilet ald\\u0131. Yolculuk yirmi d\\u00f6rt saatten fazla s\\u00fcr\\u00fcyor ama karl\\u0131 da\\u011flar\\u0131 g\\u00f6rmek istiyordu.\"},{\"en\":\"In her cabin there was an old man with a big bag of oranges. \\\"Hello,\\\" he said. \\\"I\'m going to visit my son in Kars. Would you like an orange?\\\"\",\"tr\":\"Kompart\\u0131man\\u0131nda b\\u00fcy\\u00fck bir torba portakal\\u0131 olan ya\\u015fl\\u0131 bir adam vard\\u0131. \\\"Merhaba,\\\" dedi. \\\"Kars\'taki o\\u011flumu ziyarete gidiyorum. Portakal ister misin?\\\"\"},{\"en\":\"In the middle of the night, the train stopped. \\\"There is a lot of snow on the tracks,\\\" said the conductor. \\\"There will be a long delay.\\\"\",\"tr\":\"Gecenin ortas\\u0131nda tren durdu. \\\"Raylarda \\u00e7ok kar var,\\\" dedi kond\\u00fckt\\u00f6r. \\\"Uzun bir r\\u00f6tar olacak.\\\"\"},{\"en\":\"Melis was worried, but the old man smiled. \\\"Don\'t worry. I\'ll make tea and I\'ll tell you stories.\\\" The delay was five hours, but it was the best part of her trip.\",\"tr\":\"Melis endi\\u015felendi ama ya\\u015fl\\u0131 adam g\\u00fcl\\u00fcmsedi. \\\"Merak etme. Ben \\u00e7ay yapar\\u0131m, sana hik\\u00e2yeler anlat\\u0131r\\u0131m.\\\" R\\u00f6tar be\\u015f saat s\\u00fcrd\\u00fc ama yolculu\\u011funun en g\\u00fczel k\\u0131sm\\u0131yd\\u0131.\"}]','[{\"word\":\"cabin\",\"meaning\":\"kompart\\u0131man, kabin\",\"example\":\"Our cabin was small.\"},{\"word\":\"track\",\"meaning\":\"ray\",\"example\":\"The train is on track two.\"},{\"word\":\"conductor\",\"meaning\":\"kond\\u00fckt\\u00f6r\",\"example\":\"The conductor checked our tickets.\"},{\"word\":\"trip\",\"meaning\":\"gezi\",\"example\":\"We had a great trip.\"}]','[{\"q\":\"Where was Melis going?\",\"options\":[\"Ankara\",\"Kars\",\"Erzurum\"],\"answer\":1},{\"q\":\"Why did the train stop?\",\"options\":[\"Snow on the tracks\",\"A broken engine\",\"A long queue\"],\"answer\":0},{\"type\":\"gap\",\"q\":\"The delay was ___ hours.\",\"options\":[],\"answer\":\"five\",\"accept\":[\"5\"]}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(19,'the-bucket-list','The Bucket List','Yapılacaklar Listesi','Yetmiş yaşındaki Nermin Hanım hayatında hiç yapmadığı on şeyin listesini yapıyor.','A2','Eğlence','/img/stories/the-bucket-list.webp',NULL,2,101,'[{\"en\":\"Nermin is seventy years old. On her birthday, her grandson Emir asked her a question: \\\"Grandma, what have you never done?\\\"\",\"tr\":\"Nermin yetmi\\u015f ya\\u015f\\u0131nda. Do\\u011fum g\\u00fcn\\u00fcnde torunu Emir ona bir soru sordu: \\\"Babaanne, hi\\u00e7 neler yapmad\\u0131n?\\\"\"},{\"en\":\"Nermin thought for a long time. Then she wrote a list. \\\"I\'ve never flown in a plane. I\'ve never seen the sea in winter. I\'ve never eaten sushi.\\\"\",\"tr\":\"Nermin uzun s\\u00fcre d\\u00fc\\u015f\\u00fcnd\\u00fc. Sonra bir liste yazd\\u0131. \\\"Hi\\u00e7 u\\u00e7a\\u011fa binmedim. K\\u0131\\u015f\\u0131n denizi hi\\u00e7 g\\u00f6rmedim. Hi\\u00e7 su\\u015fi yemedim.\\\"\"},{\"en\":\"Emir loved the list. Every month, they did one thing. They have eaten sushi in Istanbul and they have seen the Black Sea in January.\",\"tr\":\"Emir listeyi \\u00e7ok sevdi. Her ay bir \\u015fey yapt\\u0131lar. \\u0130stanbul\'da su\\u015fi yediler ve ocakta Karadeniz\'i g\\u00f6rd\\u00fcler.\"},{\"en\":\"Last week Nermin flew for the first time, to Van. \\\"Have you ever been so happy?\\\" asked Emir. \\\"Never,\\\" she said. \\\"But the list isn\'t finished yet!\\\"\",\"tr\":\"Ge\\u00e7en hafta Nermin ilk kez u\\u00e7a\\u011fa bindi, Van\'a. \\\"Hi\\u00e7 bu kadar mutlu oldun mu?\\\" diye sordu Emir. \\\"Hi\\u00e7,\\\" dedi. \\\"Ama liste daha bitmedi!\\\"\"}]','[{\"word\":\"grandson\",\"meaning\":\"erkek torun\",\"example\":\"Her grandson is ten.\"},{\"word\":\"list\",\"meaning\":\"liste\",\"example\":\"Make a shopping list.\"},{\"word\":\"for the first time\",\"meaning\":\"ilk kez\",\"example\":\"I saw snow for the first time.\"},{\"word\":\"yet\",\"meaning\":\"hen\\u00fcz\",\"example\":\"I haven\'t finished yet.\"}]','[{\"q\":\"How old is Nermin?\",\"options\":[\"Sixty\",\"Seventy\",\"Eighty\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Nermin has flown many times.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1},{\"q\":\"Where did Nermin fly last week?\",\"options\":[\"Van\",\"Istanbul\",\"Izmir\"],\"answer\":0}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(20,'the-second-chance','The Second Chance','İkinci Şans','Kırk yaşında mesleğini değiştiren bir muhasebecinin hikâyesi.','B1','Kariyer','/img/stories/the-second-chance.webp',NULL,2,123,'[{\"en\":\"Kemal has worked as an accountant in Bursa for fifteen years. He has a good salary and a nice flat, but recently he has felt that something is missing.\",\"tr\":\"Kemal on be\\u015f y\\u0131ld\\u0131r Bursa\'da muhasebeci olarak \\u00e7al\\u0131\\u015f\\u0131yor. \\u0130yi bir maa\\u015f\\u0131 ve g\\u00fczel bir dairesi var ama son zamanlarda bir \\u015feylerin eksik oldu\\u011funu hissediyor.\"},{\"en\":\"Since he was a child, he has loved cooking. Every Sunday he cooks for his whole family, and they have always told him the same thing: \\\"You should open a restaurant.\\\"\",\"tr\":\"\\u00c7ocuklu\\u011fundan beri yemek yapmay\\u0131 seviyor. Her pazar b\\u00fct\\u00fcn ailesine yemek yap\\u0131yor ve hep ayn\\u0131 \\u015feyi s\\u00f6yl\\u00fcyorlar: \\\"Bir restoran a\\u00e7mal\\u0131s\\u0131n.\\\"\"},{\"en\":\"Last year, on his fortieth birthday, he made a decision. He took a cooking course in Istanbul and has worked in a famous kitchen for six months.\",\"tr\":\"Ge\\u00e7en y\\u0131l, k\\u0131rk\\u0131nc\\u0131 do\\u011fum g\\u00fcn\\u00fcnde bir karar verdi. \\u0130stanbul\'da bir a\\u015f\\u00e7\\u0131l\\u0131k kursuna gitti ve alt\\u0131 ayd\\u0131r \\u00fcnl\\u00fc bir mutfakta \\u00e7al\\u0131\\u015f\\u0131yor.\"},{\"en\":\"It hasn\'t been easy. He has burnt his hands and he has worked until midnight many times. But he hasn\'t felt this alive for years. \\\"I haven\'t opened my restaurant yet,\\\" he says, \\\"but I will.\\\"\",\"tr\":\"Kolay olmad\\u0131. Ellerini yakt\\u0131, bir\\u00e7ok kez gece yar\\u0131s\\u0131na kadar \\u00e7al\\u0131\\u015ft\\u0131. Ama y\\u0131llard\\u0131r kendini bu kadar canl\\u0131 hissetmemi\\u015fti. \\\"Restoran\\u0131m\\u0131 hen\\u00fcz a\\u00e7mad\\u0131m,\\\" diyor, \\\"ama a\\u00e7aca\\u011f\\u0131m.\\\"\"}]','[{\"word\":\"accountant\",\"meaning\":\"muhasebeci\",\"example\":\"My aunt is an accountant.\"},{\"word\":\"salary\",\"meaning\":\"maa\\u015f\",\"example\":\"He has a good salary.\"},{\"word\":\"missing\",\"meaning\":\"eksik\",\"example\":\"A page is missing.\"},{\"word\":\"alive\",\"meaning\":\"canl\\u0131, hayat dolu\",\"example\":\"I feel alive by the sea.\"}]','[{\"q\":\"How long has Kemal worked as an accountant?\",\"options\":[\"Five years\",\"Fifteen years\",\"Forty years\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Kemal has already opened his restaurant.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1},{\"q\":\"When did he make his decision?\",\"options\":[\"On his fortieth birthday\",\"When he was a child\",\"Six months ago\"],\"answer\":0}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(21,'the-old-photograph','The Old Photograph','Eski Fotoğraf','Bit pazarında bulunan bir fotoğraf, kırk yıllık bir hikâyeyi ortaya çıkarıyor.','B1','Gizem','/img/stories/the-old-photograph.webp',NULL,2,134,'[{\"en\":\"Last Sunday, Derya was walking through a flea market in Kad\\u0131k\\u00f6y when she noticed a box of old photographs. One of them made her stop.\",\"tr\":\"Ge\\u00e7en pazar Derya Kad\\u0131k\\u00f6y\'deki bir bit pazar\\u0131nda y\\u00fcr\\u00fcrken eski foto\\u011fraflarla dolu bir kutu fark etti. Foto\\u011fraflardan biri onu durdurdu.\"},{\"en\":\"It showed a young woman standing in front of a bakery. The bakery was on the corner of Derya\'s street, the same bakery where she buys bread every morning.\",\"tr\":\"Foto\\u011frafta bir f\\u0131r\\u0131n\\u0131n \\u00f6n\\u00fcnde duran gen\\u00e7 bir kad\\u0131n vard\\u0131. F\\u0131r\\u0131n, Derya\'n\\u0131n soka\\u011f\\u0131n\\u0131n k\\u00f6\\u015fesindeydi; her sabah ekmek ald\\u0131\\u011f\\u0131 f\\u0131r\\u0131n\\u0131n ta kendisi.\"},{\"en\":\"She bought the photo for ten lira and took it to the bakery. The old baker was cleaning the counter while she was explaining. Suddenly he stopped and looked at the photo for a long time.\",\"tr\":\"Foto\\u011fraf\\u0131 on liraya ald\\u0131 ve f\\u0131r\\u0131na g\\u00f6t\\u00fcrd\\u00fc. O anlat\\u0131rken ya\\u015fl\\u0131 f\\u0131r\\u0131nc\\u0131 tezg\\u00e2h\\u0131 siliyordu. Aniden durdu ve foto\\u011frafa uzun uzun bakt\\u0131.\"},{\"en\":\"\\\"That\'s my mother,\\\" he said quietly. \\\"She used to work here before I was born. We lost all our photos in a fire in 1985.\\\" Now the photo hangs on the bakery wall, and the baker never lets Derya pay for her bread.\",\"tr\":\"\\\"Bu benim annem,\\\" dedi sessizce. \\\"Ben do\\u011fmadan \\u00f6nce burada \\u00e7al\\u0131\\u015f\\u0131rd\\u0131. 1985\'te bir yang\\u0131nda b\\u00fct\\u00fcn foto\\u011fraflar\\u0131m\\u0131z\\u0131 kaybettik.\\\" \\u015eimdi foto\\u011fraf f\\u0131r\\u0131n\\u0131n duvar\\u0131nda as\\u0131l\\u0131 ve f\\u0131r\\u0131nc\\u0131 Derya\'n\\u0131n ekmek paras\\u0131n\\u0131 hi\\u00e7 alm\\u0131yor.\"}]','[{\"word\":\"flea market\",\"meaning\":\"bit pazar\\u0131\",\"example\":\"I bought this lamp at a flea market.\"},{\"word\":\"bakery\",\"meaning\":\"f\\u0131r\\u0131n\",\"example\":\"The bakery opens at six.\"},{\"word\":\"counter\",\"meaning\":\"tezg\\u00e2h\",\"example\":\"Put the money on the counter.\"},{\"word\":\"hang\",\"meaning\":\"as\\u0131l\\u0131 olmak\",\"example\":\"A clock hangs on the wall.\"}]','[{\"q\":\"Where did Derya find the photo?\",\"options\":[\"At a flea market\",\"In the bakery\",\"At home\"],\"answer\":0},{\"q\":\"Who is the woman in the photo?\",\"options\":[\"Derya\'s grandmother\",\"The baker\'s mother\",\"A famous actress\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"The baker\'s family lost their photos in a fire.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(22,'the-scholarship','The Scholarship','Burs','Gaziantepli Elif, yurt dışı bursu için son mülakatına hazırlanıyor.','B1','Kariyer','/img/stories/the-scholarship.webp',NULL,2,97,'[{\"en\":\"Elif is eighteen and she lives in Gaziantep. Tomorrow at nine she is having the last interview for a scholarship to study medicine in Canada.\",\"tr\":\"Elif on sekiz ya\\u015f\\u0131nda ve Gaziantep\'te ya\\u015f\\u0131yor. Yar\\u0131n saat dokuzda Kanada\'da t\\u0131p okumak i\\u00e7in bir bursun son m\\u00fclakat\\u0131na giriyor.\"},{\"en\":\"\\\"What if I forget everything?\\\" she asks her brother. \\\"You won\'t,\\\" he says. \\\"If you practise tonight, you\'ll feel more confident.\\\"\",\"tr\":\"\\\"Ya her \\u015feyi unutursam?\\\" diye soruyor a\\u011fabeyine. \\\"Unutmazs\\u0131n,\\\" diyor a\\u011fabeyi. \\\"Bu gece pratik yaparsan kendini daha g\\u00fcvende hissedersin.\\\"\"},{\"en\":\"So they practise. He asks difficult questions and she answers in English. \\\"If they ask about my weaknesses, I\'ll be honest,\\\" she decides.\",\"tr\":\"Pratik yap\\u0131yorlar. O zor sorular soruyor, Elif \\u0130ngilizce cevapl\\u0131yor. \\\"Zay\\u0131f y\\u00f6nlerimi sorarlarsa d\\u00fcr\\u00fcst olaca\\u011f\\u0131m,\\\" diye karar veriyor.\"},{\"en\":\"The next day, the interview goes well. On the bus home her phone rings. \\\"Congratulations, Elif. If you accept, you will start in September.\\\" She can\'t stop smiling.\",\"tr\":\"Ertesi g\\u00fcn m\\u00fclakat iyi ge\\u00e7iyor. Eve d\\u00f6nerken otob\\u00fcste telefonu \\u00e7al\\u0131yor. \\\"Tebrikler Elif. Kabul ederseniz eyl\\u00fclde ba\\u015flayacaks\\u0131n\\u0131z.\\\" G\\u00fcl\\u00fcmsemesini durduram\\u0131yor.\"}]','[{\"word\":\"scholarship\",\"meaning\":\"burs\",\"example\":\"She won a scholarship.\"},{\"word\":\"confident\",\"meaning\":\"kendinden emin\",\"example\":\"He looks confident.\"},{\"word\":\"weakness\",\"meaning\":\"zay\\u0131f y\\u00f6n\",\"example\":\"What is your biggest weakness?\"},{\"word\":\"accept\",\"meaning\":\"kabul etmek\",\"example\":\"I accept your offer.\"}]','[{\"q\":\"What does Elif want to study?\",\"options\":[\"Medicine\",\"Engineering\",\"Law\"],\"answer\":0},{\"type\":\"truefalse\",\"q\":\"Elif\'s brother helps her practise.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0},{\"type\":\"gap\",\"q\":\"If she accepts, she will start in ___.\",\"options\":[],\"answer\":\"September\",\"accept\":[\"september\"]}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(23,'the-wishing-coin','The Wishing Coin','Dilek Parası','Bir çeşmeye atılan para, Can\'ın üç dileğini sorguya çekiyor.','B1','Eğlence','/img/stories/the-wishing-coin.webp',NULL,2,122,'[{\"en\":\"Can was sitting by an old fountain in Safranbolu when an old woman gave him a coin. \\\"This is a wishing coin,\\\" she said. \\\"You have three wishes. Choose carefully.\\\"\",\"tr\":\"Can, Safranbolu\'da eski bir \\u00e7e\\u015fmenin yan\\u0131nda otururken ya\\u015fl\\u0131 bir kad\\u0131n ona bir madeni para verdi. \\\"Bu bir dilek paras\\u0131,\\\" dedi. \\\"\\u00dc\\u00e7 dile\\u011fin var. Dikkatli se\\u00e7.\\\"\"},{\"en\":\"Can laughed, but he started thinking. \\\"If I had a lot of money, I would buy a house by the sea. If I were famous, everyone would know my name.\\\"\",\"tr\":\"Can g\\u00fcld\\u00fc ama d\\u00fc\\u015f\\u00fcnmeye ba\\u015flad\\u0131. \\\"\\u00c7ok param olsa denize yak\\u0131n bir ev al\\u0131rd\\u0131m. \\u00dcnl\\u00fc olsam herkes ad\\u0131m\\u0131 bilirdi.\\\"\"},{\"en\":\"Then he thought about his grandmother, who lived alone in another city. \\\"I wish I saw her more often,\\\" he said. As soon as he said it, the coin felt warm in his hand.\",\"tr\":\"Sonra ba\\u015fka bir \\u015fehirde yaln\\u0131z ya\\u015fayan babaannesini d\\u00fc\\u015f\\u00fcnd\\u00fc. \\\"Ke\\u015fke onu daha s\\u0131k g\\u00f6rsem,\\\" dedi. Bunu s\\u00f6yler s\\u00f6ylemez para avucunda \\u0131s\\u0131nd\\u0131.\"},{\"en\":\"That evening his mother called. \\\"Your grandmother is moving to our neighbourhood!\\\" Can looked at the coin. He still had two wishes, but suddenly he didn\'t need them.\",\"tr\":\"O ak\\u015fam annesi arad\\u0131. \\\"Babaannen bizim mahalleye ta\\u015f\\u0131n\\u0131yor!\\\" Can paraya bakt\\u0131. H\\u00e2l\\u00e2 iki dile\\u011fi vard\\u0131 ama birden onlara ihtiyac\\u0131 kalmam\\u0131\\u015ft\\u0131.\"}]','[{\"word\":\"fountain\",\"meaning\":\"\\u00e7e\\u015fme\",\"example\":\"We met by the fountain.\"},{\"word\":\"coin\",\"meaning\":\"madeni para\",\"example\":\"I found a coin on the floor.\"},{\"word\":\"carefully\",\"meaning\":\"dikkatlice\",\"example\":\"Read the question carefully.\"},{\"word\":\"alone\",\"meaning\":\"yaln\\u0131z\",\"example\":\"She lives alone.\"}]','[{\"q\":\"Where was Can sitting?\",\"options\":[\"By a fountain\",\"In a caf\\u00e9\",\"On a bus\"],\"answer\":0},{\"q\":\"What did Can wish for in the end?\",\"options\":[\"A house by the sea\",\"To be famous\",\"To see his grandmother more often\"],\"answer\":2},{\"type\":\"truefalse\",\"q\":\"Can used all three wishes.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(24,'the-dolphin-headline','The Dolphin Headline','Yunus Manşeti','Stajyer gazeteci Barış\'ın ilk büyük haberi bir yunusla ilgili.','B1','Haber','/img/stories/the-dolphin-headline.webp',NULL,2,112,'[{\"en\":\"Bar\\u0131\\u015f is a young journalist. He has been working at a local newspaper in Mu\\u011fla for three weeks, and he has only been given small stories so far.\",\"tr\":\"Bar\\u0131\\u015f gen\\u00e7 bir gazeteci. \\u00dc\\u00e7 haftad\\u0131r Mu\\u011fla\'da yerel bir gazetede \\u00e7al\\u0131\\u015f\\u0131yor ve \\u015fimdiye kadar ona sadece k\\u00fc\\u00e7\\u00fck haberler verildi.\"},{\"en\":\"One morning, a phone call was received at the office. A baby dolphin had been found on a beach near Fethiye. Nobody else was free, so Bar\\u0131\\u015f was sent.\",\"tr\":\"Bir sabah ofise bir telefon geldi. Fethiye yak\\u0131nlar\\u0131nda bir plajda yavru bir yunus bulunmu\\u015ftu. Ba\\u015fka kimse m\\u00fcsait de\\u011fildi, bu y\\u00fczden Bar\\u0131\\u015f g\\u00f6nderildi.\"},{\"en\":\"When he arrived, the dolphin was being kept wet by a group of fishermen. A vet was called and the animal was carried back into deep water.\",\"tr\":\"Vard\\u0131\\u011f\\u0131nda yunus bir grup bal\\u0131k\\u00e7\\u0131 taraf\\u0131ndan \\u0131slak tutuluyordu. Bir veteriner \\u00e7a\\u011fr\\u0131ld\\u0131 ve hayvan derin suya geri ta\\u015f\\u0131nd\\u0131.\"},{\"en\":\"Bar\\u0131\\u015f wrote the story that night. The next day it was published on the front page, and the video was watched by more than a million people.\",\"tr\":\"Bar\\u0131\\u015f haberi o gece yazd\\u0131. Ertesi g\\u00fcn haber \\u00f6n sayfada yay\\u0131mland\\u0131 ve video bir milyondan fazla ki\\u015fi taraf\\u0131ndan izlendi.\"}]','[{\"word\":\"local\",\"meaning\":\"yerel\",\"example\":\"a local newspaper\"},{\"word\":\"so far\",\"meaning\":\"\\u015fimdiye kadar\",\"example\":\"So far, so good.\"},{\"word\":\"fisherman\",\"meaning\":\"bal\\u0131k\\u00e7\\u0131\",\"example\":\"The fishermen leave at dawn.\"},{\"word\":\"front page\",\"meaning\":\"\\u00f6n sayfa\",\"example\":\"It was on the front page.\"}]','[{\"q\":\"Where was the dolphin found?\",\"options\":[\"Near Fethiye\",\"In Istanbul\",\"In a river\"],\"answer\":0},{\"q\":\"Who kept the dolphin wet?\",\"options\":[\"Bar\\u0131\\u015f\",\"Some fishermen\",\"A vet\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"The video was watched by more than a million people.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(25,'the-message-chain','The Message Chain','Mesaj Zinciri','Bir ofiste aktarılan basit bir mesaj, kulaktan kulağa nasıl değişiyor?','B1','Eğlence','/img/stories/the-message-chain.webp',NULL,2,120,'[{\"en\":\"On Monday morning, the manager, Mrs Uysal, said to Ahmet: \\\"I\'m taking the team out for lunch on Friday.\\\"\",\"tr\":\"Pazartesi sabah\\u0131 m\\u00fcd\\u00fcr Uysal Han\\u0131m Ahmet\'e dedi ki: \\\"Cuma g\\u00fcn\\u00fc ekibi \\u00f6\\u011fle yeme\\u011fine \\u00e7\\u0131kar\\u0131yorum.\\\"\"},{\"en\":\"Ahmet told Sibel that Mrs Uysal was taking the team out on Friday. Sibel told Ozan that they were going out on Friday, but she didn\'t say it was for lunch.\",\"tr\":\"Ahmet Sibel\'e Uysal Han\\u0131m\'\\u0131n cuma g\\u00fcn\\u00fc ekibi d\\u0131\\u015far\\u0131 \\u00e7\\u0131karaca\\u011f\\u0131n\\u0131 s\\u00f6yledi. Sibel de Ozan\'a cuma g\\u00fcn\\u00fc d\\u0131\\u015far\\u0131 \\u00e7\\u0131kacaklar\\u0131n\\u0131 s\\u00f6yledi ama \\u00f6\\u011fle yeme\\u011fi oldu\\u011funu s\\u00f6ylemedi.\"},{\"en\":\"Ozan asked Leyla if she was coming to the party on Friday night. Leyla told everyone that the manager had invited them to a party and that they should dress up.\",\"tr\":\"Ozan Leyla\'ya cuma ak\\u015famki partiye gelip gelmeyece\\u011fini sordu. Leyla da herkese m\\u00fcd\\u00fcr\\u00fcn onlar\\u0131 bir partiye davet etti\\u011fini ve \\u015f\\u0131k giyinmeleri gerekti\\u011fini s\\u00f6yledi.\"},{\"en\":\"On Friday at noon, Mrs Uysal found her whole team in suits and evening dresses. \\\"I said lunch,\\\" she laughed, \\\"not a wedding!\\\" They went to a kebab restaurant anyway, and it was the best-dressed lunch in the city.\",\"tr\":\"Cuma \\u00f6\\u011flen Uysal Han\\u0131m b\\u00fct\\u00fcn ekibini tak\\u0131m elbise ve gece elbiseleriyle buldu. \\\"Ben \\u00f6\\u011fle yeme\\u011fi dedim,\\\" diye g\\u00fcld\\u00fc, \\\"d\\u00fc\\u011f\\u00fcn de\\u011fil!\\\" Yine de bir kebap\\u00e7\\u0131ya gittiler ve \\u015fehrin en \\u015f\\u0131k \\u00f6\\u011fle yeme\\u011fi oldu.\"}]','[{\"word\":\"take out\",\"meaning\":\"d\\u0131\\u015far\\u0131 yeme\\u011fe g\\u00f6t\\u00fcrmek\",\"example\":\"He took me out for dinner.\"},{\"word\":\"invite\",\"meaning\":\"davet etmek\",\"example\":\"They invited us to the wedding.\"},{\"word\":\"dress up\",\"meaning\":\"\\u015f\\u0131k giyinmek\",\"example\":\"You don\'t need to dress up.\"},{\"word\":\"anyway\",\"meaning\":\"yine de\",\"example\":\"It was raining, but we went anyway.\"}]','[{\"q\":\"What did Mrs Uysal plan?\",\"options\":[\"A party\",\"A lunch\",\"A wedding\"],\"answer\":1},{\"q\":\"Who told everyone to dress up?\",\"options\":[\"Ahmet\",\"Leyla\",\"Mrs Uysal\"],\"answer\":1},{\"type\":\"order\",\"q\":\"C\\u00fcmleyi s\\u0131rala\",\"options\":[\"She\",\"said\",\"she\",\"was\",\"taking\",\"the\",\"team\",\"out\"],\"answer\":\"\"}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(26,'the-neighbour-upstairs','The Neighbour Upstairs','Üst Kattaki Komşu','Her gece piyano sesi duyan Ece, üst kattaki gizemli komşusunu merak ediyor.','B1','Gizem','/img/stories/the-neighbour-upstairs.webp',NULL,2,118,'[{\"en\":\"Ece moved into a small flat in Ankara last autumn. Every night at eleven, she heard piano music which came from the flat upstairs.\",\"tr\":\"Ece ge\\u00e7en sonbahar Ankara\'da k\\u00fc\\u00e7\\u00fck bir daireye ta\\u015f\\u0131nd\\u0131. Her gece saat on birde \\u00fcst kattaki daireden gelen piyano sesini duyuyordu.\"},{\"en\":\"She asked the doorman, who knew everyone in the building. \\\"The man who lives there is very quiet,\\\" he said. \\\"He\'s a retired teacher whose wife died two years ago.\\\"\",\"tr\":\"Binadaki herkesi tan\\u0131yan kap\\u0131c\\u0131ya sordu. \\\"Orada ya\\u015fayan adam \\u00e7ok sessizdir,\\\" dedi kap\\u0131c\\u0131. \\\"Kar\\u0131s\\u0131 iki y\\u0131l \\u00f6nce \\u00f6lm\\u00fc\\u015f emekli bir \\u00f6\\u011fretmen.\\\"\"},{\"en\":\"One evening, Ece found a letter which had been delivered to her flat by mistake. It was addressed to the man upstairs. She decided to take it to him.\",\"tr\":\"Bir ak\\u015fam Ece yanl\\u0131\\u015fl\\u0131kla kendi dairesine teslim edilmi\\u015f bir mektup buldu. \\u00dcst kattaki adama yaz\\u0131lm\\u0131\\u015ft\\u0131. Ona g\\u00f6t\\u00fcrmeye karar verdi.\"},{\"en\":\"Mr Turan opened the door and smiled. \\\"Are you the person who listens to my music? I play the songs that my wife loved.\\\" Now, every Sunday, Ece brings cake and he plays for her.\",\"tr\":\"Turan Bey kap\\u0131y\\u0131 a\\u00e7t\\u0131 ve g\\u00fcl\\u00fcmsedi. \\\"M\\u00fczi\\u011fimi dinleyen ki\\u015fi sen misin? Kar\\u0131m\\u0131n sevdi\\u011fi \\u015fark\\u0131lar\\u0131 \\u00e7al\\u0131yorum.\\\" \\u015eimdi her pazar Ece kek getiriyor, o da onun i\\u00e7in \\u00e7al\\u0131yor.\"}]','[{\"word\":\"upstairs\",\"meaning\":\"\\u00fcst kat\",\"example\":\"My room is upstairs.\"},{\"word\":\"doorman\",\"meaning\":\"kap\\u0131c\\u0131\",\"example\":\"The doorman opens the door.\"},{\"word\":\"by mistake\",\"meaning\":\"yanl\\u0131\\u015fl\\u0131kla\",\"example\":\"I took your coat by mistake.\"},{\"word\":\"address\",\"meaning\":\"(mektup) adreslemek\",\"example\":\"The letter was addressed to me.\"}]','[{\"q\":\"What did Ece hear every night?\",\"options\":[\"A dog\",\"Piano music\",\"A television\"],\"answer\":1},{\"q\":\"Who is Mr Turan?\",\"options\":[\"A doorman\",\"A retired teacher\",\"A musician from Istanbul\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Ece now visits Mr Turan every Sunday.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(27,'the-wrong-email','The Wrong Email','Yanlış E-posta','Yeni işindeki ilk haftasında Tuna, yanlış kişiye çok yanlış bir e-posta gönderiyor.','B1','Kariyer','/img/stories/the-wrong-email.webp',NULL,2,121,'[{\"en\":\"Tuna started working at a software company in Izmir on Monday. He was nervous but he enjoyed meeting his new colleagues.\",\"tr\":\"Tuna pazartesi g\\u00fcn\\u00fc \\u0130zmir\'de bir yaz\\u0131l\\u0131m \\u015firketinde \\u00e7al\\u0131\\u015fmaya ba\\u015flad\\u0131. Gergindi ama yeni i\\u015f arkada\\u015flar\\u0131yla tan\\u0131\\u015fmaktan keyif ald\\u0131.\"},{\"en\":\"On Thursday, he wanted to send a funny message to his friend Mert: \\\"The boss talks too much in meetings. I tried to stay awake!\\\" But he chose the wrong name. The email went to his boss, Mr Ayd\\u0131n.\",\"tr\":\"Per\\u015fembe g\\u00fcn\\u00fc arkada\\u015f\\u0131 Mert\'e komik bir mesaj g\\u00f6ndermek istedi: \\\"Patron toplant\\u0131larda \\u00e7ok konu\\u015fuyor. Uyan\\u0131k kalmaya \\u00e7al\\u0131\\u015ft\\u0131m!\\\" Ama yanl\\u0131\\u015f ismi se\\u00e7ti. E-posta patronu Ayd\\u0131n Bey\'e gitti.\"},{\"en\":\"Tuna couldn\'t stop thinking about it. He decided to apologise in person. He knocked on the door and said, \\\"I\'m really sorry. I didn\'t mean to be rude.\\\"\",\"tr\":\"Tuna bunu d\\u00fc\\u015f\\u00fcnmeden duramad\\u0131. Y\\u00fcz y\\u00fcze \\u00f6z\\u00fcr dilemeye karar verdi. Kap\\u0131y\\u0131 \\u00e7ald\\u0131 ve \\\"Ger\\u00e7ekten \\u00e7ok \\u00f6z\\u00fcr dilerim. Kaba olmak istemedim,\\\" dedi.\"},{\"en\":\"Mr Ayd\\u0131n laughed. \\\"Honestly, my wife says the same thing. Thank you for being honest. From now on, I\'ll try to keep meetings short.\\\" The next meeting lasted only fifteen minutes.\",\"tr\":\"Ayd\\u0131n Bey g\\u00fcld\\u00fc. \\\"A\\u00e7\\u0131k\\u00e7as\\u0131 e\\u015fim de ayn\\u0131 \\u015feyi s\\u00f6yl\\u00fcyor. D\\u00fcr\\u00fcst oldu\\u011fun i\\u00e7in te\\u015fekk\\u00fcrler. Bundan sonra toplant\\u0131lar\\u0131 k\\u0131sa tutmaya \\u00e7al\\u0131\\u015faca\\u011f\\u0131m.\\\" Bir sonraki toplant\\u0131 sadece on be\\u015f dakika s\\u00fcrd\\u00fc.\"}]','[{\"word\":\"software\",\"meaning\":\"yaz\\u0131l\\u0131m\",\"example\":\"She works for a software company.\"},{\"word\":\"stay awake\",\"meaning\":\"uyan\\u0131k kalmak\",\"example\":\"I couldn\'t stay awake.\"},{\"word\":\"apologise\",\"meaning\":\"\\u00f6z\\u00fcr dilemek\",\"example\":\"You should apologise.\"},{\"word\":\"rude\",\"meaning\":\"kaba\",\"example\":\"That was rude.\"}]','[{\"q\":\"Where does Tuna work?\",\"options\":[\"At a bank in Izmir\",\"At a software company in Izmir\",\"At a school in Ankara\"],\"answer\":1},{\"q\":\"Who received the email?\",\"options\":[\"Mert\",\"Mr Ayd\\u0131n\'s wife\",\"Mr Ayd\\u0131n\"],\"answer\":2},{\"type\":\"truefalse\",\"q\":\"Mr Ayd\\u0131n was very angry.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(28,'the-missed-flight','The Missed Flight','Kaçan Uçuş','Kaçırılan bir uçuş, Arda\'nın hayatını beklenmedik şekilde değiştiriyor.','B2','Seyahat','/img/stories/the-missed-flight.webp',NULL,2,127,'[{\"en\":\"Five years ago, Arda missed a flight from Istanbul to Amsterdam. If the taxi hadn\'t got stuck in traffic on the bridge, he would have arrived on time.\",\"tr\":\"Be\\u015f y\\u0131l \\u00f6nce Arda \\u0130stanbul\'dan Amsterdam\'a giden bir u\\u00e7a\\u011f\\u0131 ka\\u00e7\\u0131rd\\u0131. Taksi k\\u00f6pr\\u00fcde trafi\\u011fe tak\\u0131lmasayd\\u0131 zaman\\u0131nda varacakt\\u0131.\"},{\"en\":\"He was furious. He had an important meeting the next morning, and he blamed himself. \\\"I should have left an hour earlier,\\\" he kept saying at the airport.\",\"tr\":\"\\u00c7ok sinirlendi. Ertesi sabah \\u00f6nemli bir toplant\\u0131s\\u0131 vard\\u0131 ve kendini su\\u00e7lad\\u0131. Havaliman\\u0131nda \\\"Bir saat erken \\u00e7\\u0131kmal\\u0131yd\\u0131m,\\\" deyip duruyordu.\"},{\"en\":\"While he was waiting for the next flight, he started talking to a woman who had also missed the same plane. Her name was Leyla, and she was a landscape architect from Bursa.\",\"tr\":\"Bir sonraki u\\u00e7a\\u011f\\u0131 beklerken ayn\\u0131 u\\u00e7a\\u011f\\u0131 ka\\u00e7\\u0131rm\\u0131\\u015f olan bir kad\\u0131nla konu\\u015fmaya ba\\u015flad\\u0131. Ad\\u0131 Leyla\'yd\\u0131 ve Bursal\\u0131 bir peyzaj mimar\\u0131yd\\u0131.\"},{\"en\":\"They talked for six hours. Today, they are married and they have a daughter. \\\"If that taxi had been faster,\\\" Arda tells his friends, \\\"I would never have met her. I wish I could thank that traffic jam.\\\"\",\"tr\":\"Alt\\u0131 saat konu\\u015ftular. Bug\\u00fcn evliler ve bir k\\u0131zlar\\u0131 var. Arda arkada\\u015flar\\u0131na \\\"O taksi daha h\\u0131zl\\u0131 olsayd\\u0131 onunla asla tan\\u0131\\u015fmazd\\u0131m,\\\" diyor. \\\"Ke\\u015fke o trafik s\\u0131k\\u0131\\u015f\\u0131kl\\u0131\\u011f\\u0131na te\\u015fekk\\u00fcr edebilsem.\\\"\"}]','[{\"word\":\"get stuck\",\"meaning\":\"tak\\u0131l\\u0131p kalmak\",\"example\":\"We got stuck in the lift.\"},{\"word\":\"furious\",\"meaning\":\"\\u00f6fkeli\",\"example\":\"She was furious with me.\"},{\"word\":\"blame\",\"meaning\":\"su\\u00e7lamak\",\"example\":\"Don\'t blame yourself.\"},{\"word\":\"traffic jam\",\"meaning\":\"trafik s\\u0131k\\u0131\\u015f\\u0131kl\\u0131\\u011f\\u0131\",\"example\":\"There was a huge traffic jam.\"}]','[{\"q\":\"Why did Arda miss the flight?\",\"options\":[\"He overslept\",\"His taxi got stuck in traffic\",\"He lost his passport\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Leyla had also missed the plane.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0},{\"q\":\"What does Arda wish?\",\"options\":[\"That he had left earlier\",\"That he could thank the traffic jam\",\"That he had taken the bus\"],\"answer\":1}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(29,'the-last-bee','The Last Bee','Son Arı','2060\'ta, arıların yok olduğu bir dünyada genç bir bilim insanı umut arıyor.','B2','Bilim Kurgu','/img/stories/the-last-bee.webp',NULL,2,139,'[{\"en\":\"It is the year 2060. Bees have disappeared from most of the world, and farmers pollinate fruit trees by hand. Nisa is a young scientist working in a laboratory near Bolu.\",\"tr\":\"Y\\u0131l 2060. Ar\\u0131lar d\\u00fcnyan\\u0131n b\\u00fcy\\u00fck k\\u0131sm\\u0131ndan yok oldu ve \\u00e7ift\\u00e7iler meyve a\\u011fa\\u00e7lar\\u0131n\\u0131 elle tozla\\u015ft\\u0131r\\u0131yor. Nisa, Bolu yak\\u0131nlar\\u0131ndaki bir laboratuvarda \\u00e7al\\u0131\\u015fan gen\\u00e7 bir bilim insan\\u0131.\"},{\"en\":\"Her grandmother used to keep bees, and Nisa has always believed that some colonies must have survived somewhere. \\\"By the end of this year,\\\" she tells her team, \\\"we will have searched every valley in the Black Sea region.\\\"\",\"tr\":\"Babaannesi eskiden ar\\u0131 yeti\\u015ftirirdi ve Nisa baz\\u0131 kolonilerin bir yerlerde hayatta kalm\\u0131\\u015f olmas\\u0131 gerekti\\u011fine hep inand\\u0131. Ekibine \\\"Bu y\\u0131l\\u0131n sonuna kadar Karadeniz b\\u00f6lgesindeki her vadiyi aram\\u0131\\u015f olaca\\u011f\\u0131z,\\\" diyor.\"},{\"en\":\"In October, an old shepherd in a remote village hears about the project. He sends a short message: \\\"Come and see my chestnut trees.\\\"\",\"tr\":\"Ekimde uzak bir k\\u00f6ydeki ya\\u015fl\\u0131 bir \\u00e7oban projeyi duyuyor. K\\u0131sa bir mesaj g\\u00f6nderiyor: \\\"Gelin, kestane a\\u011fa\\u00e7lar\\u0131ma bak\\u0131n.\\\"\"},{\"en\":\"When Nisa arrives, she hears a sound she has only heard in old videos: a quiet, constant buzzing. A small wild colony has been living in a hollow tree for decades. \\\"This time next year,\\\" she whispers, \\\"we\'ll be bringing bees back to the whole country.\\\"\",\"tr\":\"Nisa vard\\u0131\\u011f\\u0131nda yaln\\u0131zca eski videolarda duydu\\u011fu bir ses duyuyor: sessiz, s\\u00fcrekli bir v\\u0131z\\u0131lt\\u0131. K\\u00fc\\u00e7\\u00fck, yabani bir koloni onlarca y\\u0131ld\\u0131r kovuk bir a\\u011fa\\u00e7ta ya\\u015f\\u0131yormu\\u015f. \\\"Gelecek y\\u0131l bu zamanlar,\\\" diye f\\u0131s\\u0131ld\\u0131yor, \\\"b\\u00fct\\u00fcn \\u00fclkeye ar\\u0131lar\\u0131 geri getiriyor olaca\\u011f\\u0131z.\\\"\"}]','[{\"word\":\"pollinate\",\"meaning\":\"tozla\\u015fmak, tozla\\u015ft\\u0131rmak\",\"example\":\"Bees pollinate flowers.\"},{\"word\":\"survive\",\"meaning\":\"hayatta kalmak\",\"example\":\"Only a few plants survived.\"},{\"word\":\"remote\",\"meaning\":\"uzak, \\u0131ss\\u0131z\",\"example\":\"a remote village\"},{\"word\":\"hollow\",\"meaning\":\"kovuk, i\\u00e7i bo\\u015f\",\"example\":\"a hollow tree\"}]','[{\"q\":\"How do farmers pollinate trees in 2060?\",\"options\":[\"With machines\",\"By hand\",\"With birds\"],\"answer\":1},{\"q\":\"Who helped Nisa find the colony?\",\"options\":[\"Her grandmother\",\"An old shepherd\",\"Her team leader\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"The colony had been living in a hollow tree for decades.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(30,'the-school-debate','The School Debate','Okul Münazarası','Utangaç Kerem, münazara finalinde en zor argümanı savunmak zorunda kalıyor.','B2','Okul','/img/stories/the-school-debate.webp',NULL,2,136,'[{\"en\":\"Kerem had never enjoyed speaking in public. Although he was one of the best students in his school in Trabzon, he always sat at the back and said nothing.\",\"tr\":\"Kerem topluluk \\u00f6n\\u00fcnde konu\\u015fmaktan hi\\u00e7 ho\\u015flanmam\\u0131\\u015ft\\u0131. Trabzon\'daki okulunun en iyi \\u00f6\\u011frencilerinden biri olmas\\u0131na ra\\u011fmen hep arkada oturur ve hi\\u00e7bir \\u015fey s\\u00f6ylemezdi.\"},{\"en\":\"Despite his fears, his English teacher put him in the debate team. In the final, his team had to argue that \\\"Mobile phones should be allowed in classrooms\\\", which Kerem personally disagreed with.\",\"tr\":\"Korkular\\u0131na ra\\u011fmen \\u0130ngilizce \\u00f6\\u011fretmeni onu m\\u00fcnazara tak\\u0131m\\u0131na ald\\u0131. Finalde tak\\u0131m\\u0131 \\\"Cep telefonlar\\u0131na s\\u0131n\\u0131fta izin verilmeli\\\" g\\u00f6r\\u00fc\\u015f\\u00fcn\\u00fc savunmak zorundayd\\u0131; Kerem ise ki\\u015fisel olarak buna kat\\u0131lm\\u0131yordu.\"},{\"en\":\"He prepared carefully. Whereas his teammates focused on freedom, Kerem collected evidence: studies on learning apps, examples of schools that had used phones successfully, and clear rules to prevent cheating.\",\"tr\":\"Dikkatle haz\\u0131rland\\u0131. Tak\\u0131m arkada\\u015flar\\u0131 \\u00f6zg\\u00fcrl\\u00fc\\u011fe odaklan\\u0131rken Kerem kan\\u0131t toplad\\u0131: \\u00f6\\u011frenme uygulamalar\\u0131 \\u00fczerine ara\\u015ft\\u0131rmalar, telefonlar\\u0131 ba\\u015far\\u0131yla kullanm\\u0131\\u015f okul \\u00f6rnekleri ve kopyay\\u0131 \\u00f6nleyecek a\\u00e7\\u0131k kurallar.\"},{\"en\":\"When he finally spoke, his voice was shaking. However, his arguments were so well organised that the judges gave his team the cup. \\\"I still don\'t agree with what I said,\\\" he told his teacher afterwards, \\\"but now I know I can convince people.\\\"\",\"tr\":\"Sonunda konu\\u015ftu\\u011funda sesi titriyordu. Ancak arg\\u00fcmanlar\\u0131 o kadar d\\u00fczenliydi ki j\\u00fcri kupay\\u0131 onun tak\\u0131m\\u0131na verdi. Sonra \\u00f6\\u011fretmenine \\\"S\\u00f6ylediklerime h\\u00e2l\\u00e2 kat\\u0131lm\\u0131yorum,\\\" dedi, \\\"ama art\\u0131k insanlar\\u0131 ikna edebildi\\u011fimi biliyorum.\\\"\"}]','[{\"word\":\"in public\",\"meaning\":\"topluluk \\u00f6n\\u00fcnde\",\"example\":\"I hate speaking in public.\"},{\"word\":\"disagree\",\"meaning\":\"kat\\u0131lmamak\",\"example\":\"I disagree with you.\"},{\"word\":\"focus on\",\"meaning\":\"odaklanmak\",\"example\":\"Focus on the main idea.\"},{\"word\":\"shake\",\"meaning\":\"titremek\",\"example\":\"My hands were shaking.\"}]','[{\"q\":\"Why didn\'t Kerem like the debate topic?\",\"options\":[\"He personally disagreed with it\",\"It was too easy\",\"It was about sport\"],\"answer\":0},{\"q\":\"What did Kerem focus on?\",\"options\":[\"Freedom\",\"Evidence\",\"Jokes\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"Kerem\'s team won the cup.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":0}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(31,'the-community-garden','The Community Garden','Mahalle Bahçesi','Terk edilmiş bir otopark, bir mahallenin birlikte kurduğu bahçeye dönüşüyor.','B2','Günlük Hayat','/img/stories/the-community-garden.webp',NULL,2,137,'[{\"en\":\"For years, the empty car park behind Selim\'s building in Kad\\u0131k\\u00f6y was full of rubbish. \\\"It\'s high time somebody did something about it,\\\" the residents kept saying, but nobody did.\",\"tr\":\"Y\\u0131llarca Selim\'in Kad\\u0131k\\u00f6y\'deki binas\\u0131n\\u0131n arkas\\u0131ndaki bo\\u015f otopark \\u00e7\\u00f6ple doluydu. Sakinler \\\"Birinin bu konuda bir \\u015fey yapmas\\u0131n\\u0131n vakti \\u00e7oktan geldi,\\\" deyip duruyordu ama kimse bir \\u015fey yapm\\u0131yordu.\"},{\"en\":\"One spring morning, Selim, a retired engineer, wrote a polite letter to the council: \\\"I was wondering whether the residents could use the area as a community garden.\\\" To everyone\'s surprise, they agreed.\",\"tr\":\"Bir bahar sabah\\u0131 emekli m\\u00fchendis Selim belediyeye kibar bir mektup yazd\\u0131: \\\"Sakinlerin alan\\u0131 bir mahalle bah\\u00e7esi olarak kullan\\u0131p kullanamayaca\\u011f\\u0131n\\u0131 merak ediyordum.\\\" Herkesi \\u015fa\\u015f\\u0131rtarak kabul ettiler.\"},{\"en\":\"At first, only a few volunteers came. Some neighbours said they would rather pay someone to do the work. But when the first tomatoes appeared, more people joined: students, a Syrian family from the third floor, even the grumpy man from number 12.\",\"tr\":\"Ba\\u015fta sadece birka\\u00e7 g\\u00f6n\\u00fcll\\u00fc geldi. Baz\\u0131 kom\\u015fular i\\u015fi yapmas\\u0131 i\\u00e7in birine para \\u00f6demeyi tercih edeceklerini s\\u00f6yledi. Ama ilk domatesler belirince daha \\u00e7ok insan kat\\u0131ld\\u0131: \\u00f6\\u011frenciler, \\u00fc\\u00e7\\u00fcnc\\u00fc kattaki Suriyeli bir aile, hatta 12 numaradaki huysuz adam bile.\"},{\"en\":\"Today the garden has forty members, a small library and a long table where neighbours eat together every Sunday. \\\"We didn\'t just grow vegetables,\\\" Selim says. \\\"We grew a community.\\\"\",\"tr\":\"Bug\\u00fcn bah\\u00e7enin k\\u0131rk \\u00fcyesi, k\\u00fc\\u00e7\\u00fck bir k\\u00fct\\u00fcphanesi ve kom\\u015fular\\u0131n her pazar birlikte yemek yedi\\u011fi uzun bir masas\\u0131 var. \\\"Sadece sebze yeti\\u015ftirmedik,\\\" diyor Selim. \\\"Bir topluluk yeti\\u015ftirdik.\\\"\"}]','[{\"word\":\"rubbish\",\"meaning\":\"\\u00e7\\u00f6p\",\"example\":\"Don\'t leave rubbish here.\"},{\"word\":\"polite\",\"meaning\":\"kibar\",\"example\":\"He wrote a polite email.\"},{\"word\":\"grumpy\",\"meaning\":\"huysuz\",\"example\":\"My neighbour is grumpy in the morning.\"},{\"word\":\"member\",\"meaning\":\"\\u00fcye\",\"example\":\"She is a member of the club.\"}]','[{\"q\":\"What was the car park full of?\",\"options\":[\"Cars\",\"Rubbish\",\"Trees\"],\"answer\":1},{\"q\":\"What did Selim do first?\",\"options\":[\"He wrote to the council\",\"He paid a gardener\",\"He sold the land\"],\"answer\":0},{\"type\":\"gap\",\"q\":\"Today the garden has ___ members.\",\"options\":[],\"answer\":\"forty\",\"accept\":[\"40\"]}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(32,'the-power-of-sleep','The Power of Sleep','Uykunun Gücü','Akademik dilde yazılmış kısa bir metin: uyku, öğrenme ve sınav başarısı arasındaki ilişki.','B2','Bilim','/img/stories/the-power-of-sleep.webp',NULL,2,131,'[{\"en\":\"Sleep has long been considered a passive state in which the brain simply rests. However, recent research indicates that sleep plays a crucial role in learning and memory.\",\"tr\":\"Uyku uzun zamand\\u0131r beynin sadece dinlendi\\u011fi pasif bir durum olarak g\\u00f6r\\u00fcld\\u00fc. Ancak son ara\\u015ft\\u0131rmalar uykunun \\u00f6\\u011frenme ve haf\\u0131zada \\u00e7ok \\u00f6nemli bir rol oynad\\u0131\\u011f\\u0131n\\u0131 g\\u00f6steriyor.\"},{\"en\":\"During deep sleep, information learned during the day is transferred from short-term to long-term memory. Consequently, students who sleep well after studying tend to remember more than those who stay up all night.\",\"tr\":\"Derin uyku s\\u0131ras\\u0131nda g\\u00fcn i\\u00e7inde \\u00f6\\u011frenilen bilgiler k\\u0131sa s\\u00fcreli haf\\u0131zadan uzun s\\u00fcreli haf\\u0131zaya aktar\\u0131l\\u0131r. Sonu\\u00e7 olarak, \\u00e7al\\u0131\\u015ft\\u0131ktan sonra iyi uyuyan \\u00f6\\u011frenciler b\\u00fct\\u00fcn gece uyan\\u0131k kalanlardan daha fazlas\\u0131n\\u0131 hat\\u0131rlama e\\u011filimindedir.\"},{\"en\":\"In one study, approximately two hundred university students were divided into two groups. Both groups learned the same list of words; nevertheless, the group that slept eight hours scored about thirty percent higher the next day.\",\"tr\":\"Bir \\u00e7al\\u0131\\u015fmada yakla\\u015f\\u0131k iki y\\u00fcz \\u00fcniversite \\u00f6\\u011frencisi iki gruba ayr\\u0131ld\\u0131. \\u0130ki grup da ayn\\u0131 kelime listesini \\u00f6\\u011frendi; yine de sekiz saat uyuyan grup ertesi g\\u00fcn yakla\\u015f\\u0131k y\\u00fczde otuz daha y\\u00fcksek puan ald\\u0131.\"},{\"en\":\"These findings have significant implications for exam preparation. Rather than sacrificing sleep before an exam such as the YDS, learners would benefit more from short, regular study sessions followed by a full night\'s rest.\",\"tr\":\"Bu bulgular\\u0131n s\\u0131nav haz\\u0131rl\\u0131\\u011f\\u0131 a\\u00e7\\u0131s\\u0131ndan \\u00f6nemli sonu\\u00e7lar\\u0131 var. \\u00d6\\u011frenciler, YDS gibi bir s\\u0131nav \\u00f6ncesinde uykudan feragat etmek yerine, k\\u0131sa ve d\\u00fczenli \\u00e7al\\u0131\\u015fma seanslar\\u0131n\\u0131n ard\\u0131ndan tam bir gece dinlenmekten daha \\u00e7ok fayda g\\u00f6r\\u00fcr.\"}]','[{\"word\":\"passive\",\"meaning\":\"edilgen, pasif\",\"example\":\"a passive state\"},{\"word\":\"transfer\",\"meaning\":\"aktarmak\",\"example\":\"The data was transferred.\"},{\"word\":\"implication\",\"meaning\":\"sonu\\u00e7, \\u00e7\\u0131kar\\u0131m\",\"example\":\"The study has important implications.\"},{\"word\":\"sacrifice\",\"meaning\":\"feda etmek\",\"example\":\"Don\'t sacrifice your health.\"}]','[{\"q\":\"What is the passage mainly about?\",\"options\":[\"The role of sleep in learning\",\"How to study all night\",\"Problems of university students\"],\"answer\":0},{\"q\":\"How much higher did the sleeping group score?\",\"options\":[\"About eight percent\",\"About thirty percent\",\"About two hundred percent\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"The writer recommends staying up late before an exam.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53'),
(33,'the-film-club','The Film Club','Film Kulübü','Bir üniversite film kulübü, unutulmuş bir Türk filmini yeniden keşfediyor.','B2','Eğlence','/img/stories/the-film-club.webp',NULL,2,161,'[{\"en\":\"Every Thursday, the film club at Ege University watches a classic film and discusses it in English. This term, the members were running out of ideas, and attendance was going down.\",\"tr\":\"Ege \\u00dcniversitesi\'ndeki film kul\\u00fcb\\u00fc her per\\u015fembe klasik bir film izliyor ve \\u0130ngilizce tart\\u0131\\u015f\\u0131yor. Bu d\\u00f6nem \\u00fcyelerin fikirleri t\\u00fckeniyordu ve kat\\u0131l\\u0131m d\\u00fc\\u015f\\u00fcyordu.\"},{\"en\":\"Then Deniz came up with an unusual plan. Her grandfather had looked after an old cinema in Tire for forty years, and she had found out that a lost Turkish film from 1962 was still in his basement.\",\"tr\":\"Sonra Deniz al\\u0131\\u015f\\u0131lmad\\u0131k bir plan buldu. Dedesi k\\u0131rk y\\u0131l boyunca Tire\'deki eski bir sinemaya bakm\\u0131\\u015ft\\u0131 ve Deniz 1962 yap\\u0131m\\u0131 kay\\u0131p bir T\\u00fcrk filminin h\\u00e2l\\u00e2 dedesinin bodrumunda oldu\\u011funu \\u00f6\\u011frenmi\\u015fti.\"},{\"en\":\"Restoring the film wasn\'t a piece of cake. The club had to put off their screenings for two months, and some members nearly gave up. A professor turned down their first request for equipment, but a local business finally agreed to help.\",\"tr\":\"Filmi restore etmek \\u00e7ocuk oyunca\\u011f\\u0131 de\\u011fildi. Kul\\u00fcp g\\u00f6sterimlerini iki ay ertelemek zorunda kald\\u0131 ve baz\\u0131 \\u00fcyeler neredeyse vazge\\u00e7iyordu. Bir profes\\u00f6r ekipman i\\u00e7in ilk taleplerini reddetti ama sonunda yerel bir i\\u015fletme yard\\u0131m etmeyi kabul etti.\"},{\"en\":\"On the night of the screening, the hall was full. Deniz\'s grandfather sat in the front row, and when the first black-and-white scene appeared, he broke the ice with a joke: \\\"I was much more handsome back then.\\\" Everyone laughed, and then the room fell silent for the next ninety minutes.\",\"tr\":\"G\\u00f6sterim gecesi salon doluydu. Deniz\'in dedesi \\u00f6n s\\u0131rada oturuyordu ve ilk siyah beyaz sahne belirince bir \\u015fakayla buzlar\\u0131 k\\u0131rd\\u0131: \\\"O zamanlar \\u00e7ok daha yak\\u0131\\u015f\\u0131kl\\u0131yd\\u0131m.\\\" Herkes g\\u00fcld\\u00fc, ard\\u0131ndan salon doksan dakika boyunca sessizli\\u011fe g\\u00f6m\\u00fcld\\u00fc.\"}]','[{\"word\":\"run out of\",\"meaning\":\"t\\u00fckenmek\",\"example\":\"We\'ve run out of milk.\"},{\"word\":\"attendance\",\"meaning\":\"kat\\u0131l\\u0131m\",\"example\":\"Attendance was low.\"},{\"word\":\"basement\",\"meaning\":\"bodrum\",\"example\":\"The boxes are in the basement.\"},{\"word\":\"screening\",\"meaning\":\"g\\u00f6sterim\",\"example\":\"The screening starts at eight.\"}]','[{\"q\":\"Why was the club in trouble?\",\"options\":[\"Attendance was going down\",\"The cinema closed\",\"The professor left\"],\"answer\":0},{\"q\":\"Where was the lost film?\",\"options\":[\"In a university library\",\"In her grandfather\'s basement\",\"In a cinema in Istanbul\"],\"answer\":1},{\"type\":\"truefalse\",\"q\":\"The professor immediately agreed to give them equipment.\",\"options\":[\"Do\\u011fru\",\"Yanl\\u0131\\u015f\"],\"answer\":1}]',0,1,0,'2026-08-24 04:21:53','2026-10-03 04:21:53','2026-10-03 04:21:53');
/*!40000 ALTER TABLE `stories` ENABLE KEYS */;
