  `title` varchar(255) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `guidebook` longtext DEFAULT NULL,
  `color` varchar(20) DEFAULT NULL,
  `position` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `units_course_id_foreign` (`course_id`),
  CONSTRAINT `units_course_id_foreign` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `units` WRITE;
/*!40000 ALTER TABLE `units` DISABLE KEYS */;
INSERT INTO `units` VALUES
(1,1,'Merhaba!','Selamlaşma, tanışma ve \"to be\"','## Merhaba, ben Higo!\nBu ünitede kendini tanıtmayı, birini selamlamayı ve **to be** fiilini öğreneceksin. Türkçede \"-im, -sin, -dir\" eklerinin yaptığı işi İngilizcede **am / is / are** yapar.\n\n> Higo\'nun ipucu: İngilizcede cümlenin bir fiili olmak zorunda. \"Ben öğrenci\" demek yetmez, **I am a student** demelisin.\n\n## am / is / are\n| Özne | Fiil | Örnek |\n|---|---|---|\n| I | am | I am Elif. |\n| he / she / it | is | She is my friend. |\n| you / we / they | are | We are from Turkey. |\n\nKonuşurken kısaltırız: **I\'m, he\'s, she\'s, it\'s, you\'re, we\'re, they\'re**.\n\n## Olumsuz ve soru\n- Olumsuz: fiilden sonra **not**: *I\'m not tired. She isn\'t here.*\n- Soru: fiil başa geçer: *Are you a student? Is he from Izmir?*\n- Kısa cevap: *Yes, I am. / No, she isn\'t.*\n\n## Selamlaşma kalıpları\n- **Hello / Hi**: merhaba\n- **Good morning / afternoon / evening**: günaydın / iyi günler / iyi akşamlar\n- **Nice to meet you.** Tanıştığıma memnun oldum.\n- **How are you? I\'m fine, thanks.** Nasılsın? İyiyim, teşekkürler.\n\n> Higo\'nun ipucu: \"Good night\" bir selam değil, vedalaşmadır. Akşam birine merhaba derken **Good evening** de.','#FF5A36',0,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(2,1,'Ailem','Aile, have got ve iyelik sıfatları','## Aileni tanıt\nBu ünitede aileni anlatacaksın: **mother, father, brother, sister, grandmother…** Ve sahip olduklarımızı söylemek için **have got / has got** kullanacağız.\n\n## have got / has got\n| Özne | Fiil | Örnek |\n|---|---|---|\n| I / you / we / they | have got (\'ve got) | I\'ve got two brothers. |\n| he / she / it | has got (\'s got) | She\'s got a cat. |\n\nOlumsuz: *I haven\'t got a sister. He hasn\'t got a car.*\nSoru: *Have you got a pet? Has she got a bike?*\n\n> Higo\'nun ipucu: Amerikan İngilizcesinde sadece **have / has** da çok kullanılır: *I have two brothers.* İkisi de doğru.\n\n## Kimin? İyelik sıfatları\n**my** (benim) · **your** (senin) · **his** (onun, erkek) · **her** (onun, kadın) · **its** (onun, eşya/hayvan) · **our** (bizim) · **their** (onların)\n\n*This is my sister. Her name is Ayşe.*\n\n## \'s ile sahiplik\nİsimden sonra **\'s**: *Ali\'s car* (Ali\'nin arabası), *my mother\'s phone* (annemin telefonu).','#FF8A3D',1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(3,1,'Okulda','Sınıf eşyaları, this/that ve emir cümleleri','## Sınıfta neler var?\nBu ünitede okul eşyalarını, **this / that / these / those** ile bir şeyi göstermeyi ve sınıfta duyacağın emir cümlelerini öğreneceksin.\n\n## this · that · these · those\n| | Yakın | Uzak |\n|---|---|---|\n| Tekil | **this** pen | **that** board |\n| Çoğul | **these** books | **those** chairs |\n\n> Higo\'nun ipucu: Çoğul isimlerin çoğu **-s** alır: *book → books*. Bazıları düzensizdir: *child → children, person → people*.\n\n## Emir cümleleri (Imperatives)\nFiil yalın hâliyle başta: **Open your books. Sit down. Listen!**\nOlumsuz: **Don\'t** + fiil: *Don\'t talk. Don\'t run in the corridor.*\nKibar olmak için sona **please** ekle: *Close the door, please.*\n\n## a / an\nSessiz harfle başlayan sözcükten önce **a**: *a pen, a desk*.\nSesli harf **sesiyle** başlayan sözcükten önce **an**: *an eraser, an apple, an hour*.','#FFB400',2,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(4,1,'Günüm','Geniş zaman, saatler ve sıklık zarfları','## Bir günün İngilizcesi\nBu ünitede rutinlerini anlatacaksın. Her gün, her hafta tekrar eden şeyler için **Present Simple** (geniş zaman) kullanılır.\n\n## Present Simple\n*I get up at seven. We go to school by bus.*\n\n**he / she / it** ile fiile **-s** gelir: *She works. He watches TV. It goes.*\n\n> Higo\'nun ipucu: -s, -sh, -ch, -x, -o ile biten fiiller **-es** alır: *watch → watches, go → goes*. Ünsüz + y ise **-ies**: *study → studies*.\n\n## Olumsuz ve soru\n- **don\'t / doesn\'t** + yalın fiil: *I don\'t drink coffee. She doesn\'t like fish.*\n- **Do / Does** + özne + yalın fiil: *Do you play football? Does he live here?*\n\n## Ne sıklıkla?\n**always** (her zaman) · **usually** (genellikle) · **often** (sık sık) · **sometimes** (bazen) · **never** (asla)\nFiilden önce, **be**\'den sonra gelir: *I usually walk. She is never late.*\n\n## Saat\n*It\'s seven o\'clock. It\'s half past three (3:30). It\'s quarter to nine (8:45).*','#2EC4A0',3,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(5,1,'Evim','Ev, odalar, there is/are ve yer edatları','## Evini anlat\nBu ünitede odaları ve eşyaları öğreneceksin. Bir yerde bir şeyin **var** olduğunu söylemek için **there is / there are** kullanılır.\n\n## There is / There are\n- Tekil: **There is** a sofa in the living room.\n- Çoğul: **There are** two bedrooms.\n- Olumsuz: *There isn\'t a garden. There aren\'t any chairs.*\n- Soru: *Is there a balcony? Are there any windows?*\n\n> Higo\'nun ipucu: Türkçedeki \"var / yok\" çoğu zaman **there is / there are** ile karşılanır. \"Evimde balkon var\" → *There is a balcony in my house.*\n\n## Nerede? Yer edatları\n**in** (içinde) · **on** (üstünde) · **under** (altında) · **next to** (yanında) · **between** (arasında) · **behind** (arkasında) · **in front of** (önünde) · **opposite** (karşısında)\n\n*The cat is under the bed. The lamp is between the sofa and the window.*','#3A6FF7',4,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(6,1,'Yemek ve Alışveriş','Yiyecekler, some/any ve fiyat sormak','## Mutfakta ve markette\nBu ünitede yiyecekleri, **sayılabilen / sayılamayan** isimleri ve alışverişte fiyat sormayı öğreneceksin.\n\n## Sayılabilen ve sayılamayan\n- Sayılabilen: *an apple, two eggs, three tomatoes*\n- Sayılamayan: *water, milk, bread, cheese, rice*. Bunlar **a / an** ya da **-s** almaz.\nSayılamayanı ölçmek için: *a glass of water, a bottle of milk, a piece of cake, a kilo of rice*.\n\n## some / any\n- Olumlu cümlede **some**: *There is some milk.*\n- Olumsuz ve soruda **any**: *There isn\'t any bread. Have we got any eggs?*\n- Bir şey teklif ederken **some**: *Would you like some tea?*\n\n## How much / How many\n- Sayılamayan: **How much** water? / Fiyat: **How much is it?**\n- Sayılabilen: **How many** eggs?\n\n> Higo\'nun ipucu: Siparişte \"I want\" sert durur. Kibar hâli **I\'d like …, please** ya da **Can I have …?**','#22B573',5,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(7,1,'Şehirde','Yol tarifi, yerler ve can / can\'t','## Şehirde kaybolma!\nBu ünitede şehirdeki yerleri, yol tarifini ve **can / can\'t** ile yetenek ve izin bildirmeyi öğreneceksin.\n\n## Yol tarifi\n- **Go straight on.** Düz git.\n- **Turn left / right.** Sola / sağa dön.\n- **Take the second street on the left.** Soldan ikinci sokağa gir.\n- **It\'s on your right / opposite the bank.** Sağında / bankanın karşısında.\n\nSormak için: *Excuse me, how can I get to the station? / Where is the nearest pharmacy?*\n\n> Higo\'nun ipucu: İngilizcede yol tarifi hareket sırasına göre anlatılır, hedef en sona bırakılır.\n\n## can / can\'t\n- Yetenek: *I can swim. She can\'t drive.*\n- İzin ve rica: *Can I park here? Can you help me?*\n**can**\'den sonra fiil yalın kalır: *He can speak English* (~~can speaks~~).','#3AB0E6',6,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(8,1,'Şu An','Şimdiki zaman, kıyafetler ve hava durumu','## Şu anda ne oluyor?\nBu ünitede **Present Continuous** (şimdiki zaman), kıyafetler ve hava durumunu öğreneceksin.\n\n## Present Continuous\n**am / is / are + fiil-ing**: konuşma anında olan şeyler.\n*I am reading. She is wearing a red coat. They are playing football.*\n\nOlumsuz: *I\'m not sleeping.* Soru: *Are you listening? What is he doing?*\n\n> Higo\'nun ipucu: Geniş zaman alışkanlık, şimdiki zaman şu anı anlatır. *I usually wear jeans, but today I\'m wearing a dress.*\n\n## -ing yazımı\n- *make → making* (sondaki e düşer)\n- *run → running, sit → sitting* (kısa fiillerde son harf ikilenir)\n\n## Hava durumu\n*It\'s sunny / rainy / cloudy / windy / snowing / hot / cold.*\n*What\'s the weather like? It\'s raining in Rize again!*','#8F7CF8',7,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(9,1,'Hafta Sonum','Hobiler, like + -ing ve A1 tekrarı','## Boş zamanında ne yaparsın?\nSon ünitede hobileri, sevdiklerini anlatmayı öğrenecek ve A1\'in tamamını tekrar edeceksin. Ünite sonunda **A1 seviye sınavı** var.\n\n## like / love / hate + -ing\n*I like reading. She loves dancing. They hate waking up early.*\n**enjoy** ve **don\'t mind** da -ing alır: *I enjoy cooking. I don\'t mind walking.*\n\n## Sorular için soru kelimeleri\n**What** (ne) · **Where** (nerede) · **When** (ne zaman) · **Who** (kim) · **Why** (neden) · **How** (nasıl) · **How often** (ne sıklıkla)\n\n*What do you do at the weekend? How often do you go swimming?*\n\n> Higo\'nun ipucu: Sınavdan önce Kelime defterindeki kelimelerini bir kez tekrar et. Unuttuğun kelimeler kendiliğinden öne gelir.\n\n## A1\'de neler öğrendin?\nto be · have got · this/that · present simple · there is/are · some/any · can · present continuous · like + -ing','#FF7FB0',8,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(10,2,'Dün','was / were ve düzenli geçmiş zaman','## Dün neredeydin?\nBu ünitede geçmişi anlatmaya başlıyoruz: **was / were** ve düzenli fiillerin geçmiş hâli.\n\n## was / were\n| Özne | Fiil | Örnek |\n|---|---|---|\n| I / he / she / it | was | I was at home yesterday. |\n| you / we / they | were | They were in Bodrum. |\n\nOlumsuz: *wasn\'t / weren\'t*. Soru: *Were you tired? Was it expensive?*\n\n## Düzenli fiiller: -ed\n*work → worked, play → played, watch → watched*\nYazım: *live → lived, study → studied, stop → stopped*\n\n> Higo\'nun ipucu: -ed\'in üç okunuşu var: **/t/** worked, **/d/** played, **/ɪd/** wanted. Sondaki t ya da d sesinden sonra hece eklenir.\n\n## Geçmiş zaman ifadeleri\n**yesterday** · **last night / week / summer** · **two days ago** · **in 2020**','#2EC4A0',0,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(11,2,'Hikâye Anlat','Düzensiz fiiller ve geçmişte soru','## Bir anı anlat\nBu ünitede düzensiz fiilleri ve geçmiş zamanda soru ve olumsuz cümleleri öğreneceksin.\n\n## Düzensiz fiiller\nEzberlenir, en sık kullanılanlarla başla:\n*go → went · see → saw · have → had · eat → ate · buy → bought · take → took · make → made · come → came · get → got · find → found*\n\n## did ile soru ve olumsuz\nOlumsuz ve soruda **did** geçmişi taşır, fiil **yalın** kalır.\n- *I didn\'t go. (~~didn\'t went~~)*\n- *Did you see the match? Yes, I did.*\n- *Where did you buy it?*\n\n> Higo\'nun ipucu: Bir hikâyeyi sıraya koymak için **first, then, after that, finally** kullan. Dinleyen kişi hikâyeni çok daha kolay takip eder.','#22B573',1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(12,2,'Planlar','be going to, gelecek planları ve tatil','## Gelecek planların\nBu ünitede plan ve niyetler için **be going to** kalıbını öğreneceksin.\n\n## be going to\n**am / is / are + going to + yalın fiil**\n- *I\'m going to visit my aunt in Mersin.*\n- *We aren\'t going to stay at a hotel.*\n- *Are you going to study tonight?*\n\nKanıt varken tahmin için de kullanılır: *Look at those clouds! It\'s going to rain.*\n\n## Zaman ifadeleri\n**tonight · tomorrow · next week / month / summer · this weekend · in two days**\n\n> Higo\'nun ipucu: Konuşurken \"going to\" çoğu zaman **gonna** gibi duyulur. Dinlerken tanı ama yazıda kullanma.','#3A6FF7',2,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(13,2,'Karşılaştır','Karşılaştırma ve üstünlük sıfatları','## Hangisi daha iyi?\nBu ünitede şehirleri, insanları ve eşyaları karşılaştırmayı öğreneceksin.\n\n## Karşılaştırma (Comparatives)\n- Kısa sıfat + **-er than**: *Ankara is bigger than Eskişehir.*\n- Uzun sıfat: **more … than**: *Istanbul is more crowded than Bursa.*\n- Düzensiz: *good → better, bad → worse, far → further*\n\n## Üstünlük (Superlatives)\n- **the + -est**: *the biggest, the cheapest*\n- **the most …**: *the most beautiful city*\n- Düzensiz: *the best, the worst*\n\n## as … as\nEşitlik: *My phone is as fast as yours.* Olumsuz: *It isn\'t as cold as yesterday.*\n\n> Higo\'nun ipucu: Türkçedeki \"-den daha\" İngilizcede **than** ile kurulur. \"Benden uzun\" → *taller than me*.','#FFB400',3,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(14,2,'Sağlık','Vücut, rahatsızlıklar ve should','## Kendini nasıl hissediyorsun?\nBu ünitede vücudu, rahatsızlıkları ve tavsiye vermek için **should / shouldn\'t** kalıbını öğreneceksin.\n\n## Rahatsızlıklar\n*I\'ve got a headache / a stomach ache / a sore throat / a cold / a temperature.*\n*My back hurts. I feel sick.*\n\n## should / shouldn\'t\nTavsiye vermek için: **should + yalın fiil**\n- *You should drink more water.*\n- *You shouldn\'t go to school today.*\n- *What should I do?*\n\n> Higo\'nun ipucu: Doktora gittiğinde ne zamandır sürdüğünü söylemek için **for** kullan: *I\'ve had a headache for two days.* Bunu B1\'de daha detaylı göreceğiz.','#FF5A5F',4,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(15,2,'Yolculuk','Ulaşım, will ve anlık kararlar','## Yola çıkalım\nBu ünitede ulaşımı, bilet almayı ve **will** ile tahmin ve anlık kararları öğreneceksin.\n\n## will\n**will + yalın fiil**, kısaltması **\'ll**, olumsuzu **won\'t**.\n- Anlık karar: *It\'s cold. I\'ll close the window.*\n- Söz ve teklif: *I\'ll help you with your bag.*\n- Tahmin: *I think it will be a long journey.*\n\n## going to mu, will mi?\n- Önceden yapılmış plan: **going to** → *I\'m going to fly to Berlin on Monday.*\n- Konuşma anında karar: **will** → *Oh, the bus is late. I\'ll take a taxi.*\n\n> Higo\'nun ipucu: Bilet alırken **single** tek yön, **return** gidiş-dönüş demektir. Amerikan İngilizcesinde *one-way / round-trip*.','#3AB0E6',5,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(16,2,'Deneyimler','Present perfect: ever / never','## Hiç … yaptın mı?\nBu ünitede hayat deneyimlerini anlatmak için **present perfect** ile tanışacaksın.\n\n## Present Perfect\n**have / has + fiilin 3. hâli (V3)**\n- *I have been to Rome.*\n- *She has never eaten sushi.*\n- *Have you ever ridden a horse? Yes, I have. / No, I haven\'t.*\n\n## ever / never\n- **ever**: soruda \"hiç\": *Have you ever …?*\n- **never**: olumlu fiille \"hiç … -medim\": *I\'ve never flown.*\n\n## been mi, gone mı?\n- *He has **been** to Paris.* Gitti ve döndü.\n- *He has **gone** to Paris.* Gitti, şu an orada.\n\n> Higo\'nun ipucu: Ne zaman olduğunu söylersen geçmiş zamana geç: *I\'ve been to Rome. I went there in 2022.*','#8F7CF8',6,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(17,2,'Kurallar','must / have to ve izinler','## Kurallar ve zorunluluklar\nBu ünitede kuralları anlatmayı öğreneceksin: **must, have to, mustn\'t, don\'t have to**. A2\'nin sonunda **A2 seviye sınavı** var.\n\n## must / have to\n- **must**: konuşanın kendi hissettiği zorunluluk ya da yazılı kural: *I must call my mum. You must wear a seatbelt.*\n- **have to**: dışarıdan gelen zorunluluk: *I have to wear a uniform at school.*\n\n## mustn\'t ve don\'t have to\nDikkat, anlamları çok farklı!\n- **mustn\'t**: yasak: *You mustn\'t use your phone in the exam.*\n- **don\'t have to**: gerek yok: *You don\'t have to come. It\'s optional.*\n\n> Higo\'nun ipucu: Geçmişte **must** yerine **had to** kullanılır: *I had to work late yesterday.*','#FF7FB0',7,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(18,3,'Hayat Deneyimleri','Present perfect ve past simple, for / since','## Ne zamandır?\nBu ünitede **present perfect** ile **past simple** arasındaki farkı ve **for / since** kullanımını öğreneceksin.\n\n## Present perfect mi, past simple mı?\n- Zaman belli değil ya da etkisi sürüyor: *I\'ve lost my keys.* (hâlâ yok)\n- Zaman belli, bitmiş: *I lost my keys yesterday.*\n\n## for / since\nHâlâ devam eden durumlar için:\n- **for** + süre: *I\'ve lived here for five years.*\n- **since** + başlangıç noktası: *I\'ve lived here since 2020.*\n\n> Higo\'nun ipucu: Türkçede \"İki yıldır İngilizce öğreniyorum\" şimdiki zamanla söylenir ama İngilizcede **present perfect continuous** gerekir: *I\'ve been learning English for two years.*\n\n## just / already / yet\n- *I\'ve just finished.* (az önce)\n- *She\'s already left.* (çoktan)\n- *Have you finished yet? I haven\'t finished yet.* (henüz)','#3A6FF7',0,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(19,3,'Eskiden','Past continuous ve used to','## O sırada ne yapıyordun?\nBu ünitede geçmişte süren olayları (**past continuous**) ve eski alışkanlıkları (**used to**) öğreneceksin.\n\n## Past continuous\n**was / were + fiil-ing**: geçmişte belli bir anda süren eylem.\n*At 8 pm I was watching TV. They were sleeping when I called.*\n\n## Past continuous + past simple\nUzun süren arka plan olayı + onu kesen kısa olay:\n*I **was walking** home **when** it **started** to rain.*\n*While she was cooking, the phone rang.*\n\n## used to\nEskiden olan ama artık olmayan alışkanlık ve durumlar:\n*I used to play the piano. (Artık çalmıyorum.)*\n*Did you use to live in Adana?* · *We didn\'t use to have a car.*\n\n> Higo\'nun ipucu: **used to** sadece geçmiş içindir. Şimdiki alışkanlık için geniş zaman kullan: *I usually walk to school.*','#2F7CF6',1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(20,3,'Gelecek','Gelecek zamanlar ve first conditional','## Geleceği konuşmak\nB1\'de geleceği anlatmanın üç yolunu ve **first conditional**\'ı birlikte kullanacaksın.\n\n## Üç gelecek\n- **Present continuous**: kesinleşmiş randevular: *I\'m meeting Sarah at six.*\n- **be going to**: planlar ve kanıta dayalı tahminler: *I\'m going to apply for the job.*\n- **will**: anlık kararlar, sözler, fikre dayalı tahminler: *I think you\'ll love it.*\n\n## First conditional\nGerçekleşmesi muhtemel durumlar:\n**If + present simple, will + yalın fiil**\n*If it rains, we\'ll stay at home.*\n*If you study hard, you\'ll pass the exam.*\n\n> Higo\'nun ipucu: **if** cümlesinde will kullanılmaz! ~~If it will rain~~ → **If it rains**. Aynı kural **when, as soon as, unless** için de geçerli.\n\n## unless\n\"…mezse\": *You won\'t pass unless you study.* = *If you don\'t study, you won\'t pass.*','#22B5C0',2,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(21,3,'Hayaller','Second conditional ve wish','## Ya olsaydı?\nBu ünitede hayal ettiğimiz, gerçek olmayan durumlar için **second conditional** ve **wish** kullanacağız.\n\n## Second conditional\n**If + past simple, would + yalın fiil**\n*If I had more time, I would learn the guitar.* (Şu an vaktim yok.)\n*If I were you, I\'d take the job.* (Tavsiye)\n\n> Higo\'nun ipucu: Resmî İngilizcede bütün öznelerle **were** kullanılır: *If I were rich, if she were here.* Günlük konuşmada *was* da duyarsın.\n\n## First mi, second mı?\n- *If I win the match, I\'ll be happy.* (Mümkün, gerçekçi)\n- *If I won the lottery, I\'d buy an island.* (Hayal)\n\n## wish + past simple\nŞu anki durumdan duyulan pişmanlık ya da istek:\n*I wish I lived by the sea. I wish I could speak Japanese.*','#8F7CF8',3,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(22,3,'Haberler','Edilgen yapı (passive voice)','## Ne oldu, kim yaptı?\nHaberlerde çoğu zaman **işi yapan değil, işin kendisi** önemlidir. Bu ünitede **passive voice** (edilgen yapı) öğreneceksin.\n\n## Passive voice\n**be + fiilin 3. hâli (V3)**\n| Zaman | Edilgen |\n|---|---|\n| Present simple | The museum **is visited** by millions. |\n| Past simple | The bridge **was built** in 1973. |\n| Present perfect | A new law **has been passed**. |\n| will | The results **will be announced** tomorrow. |\n\nİşi yapanı söylemek gerekirse **by** kullanılır: *The book was written by Orhan Pamuk.*\n\n> Higo\'nun ipucu: Türkçedeki \"-ıldı, -ildi\" ekleri genellikle passive ile karşılanır: *Köprü 1973\'te yapıldı → The bridge was built in 1973.*','#3AB0E6',4,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(23,3,'Dedi ki','Dolaylı anlatım (reported speech)','## Ne dedi?\nBu ünitede birinin söylediklerini aktarmak için **reported speech** (dolaylı anlatım) öğreneceksin.\n\n## Zaman bir geri gider\n| Söylenen | Aktarılan |\n|---|---|\n| \"I **am** tired.\" | She said (that) she **was** tired. |\n| \"I **will** call you.\" | He said he **would** call me. |\n| \"We **have finished**.\" | They said they **had finished**. |\n| \"I **can** help.\" | She said she **could** help. |\n\n## say ve tell\n- **say** (something): *He said he was busy.*\n- **tell** + kişi: *He told me he was busy.* (~~He said me~~)\n\n## Sorular ve istekler\n- *\"Where do you live?\"* → *She asked me where I lived.* (soru düzeni bozulur)\n- *\"Do you like it?\"* → *He asked if I liked it.*\n- *\"Please sit down.\"* → *She told me to sit down.*\n\n> Higo\'nun ipucu: Zaman ifadeleri de değişir: *tomorrow → the next day, yesterday → the day before, here → there.*','#FF8A3D',5,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(24,3,'İnsanlar ve Yerler','Relative clauses: who, which, where','## Kimden, neyden bahsediyoruz?\nBu ünitede bir insanı, eşyayı ya da yeri tanımlamak için **relative clauses** (sıfat cümlecikleri) öğreneceksin.\n\n## who · which · that · where · whose\n- **who**: insanlar: *The woman who lives next door is a pilot.*\n- **which**: eşya, hayvan: *The phone which I bought is broken.*\n- **that**: insan ve eşya (resmî olmayan): *the book that you gave me*\n- **where**: yerler: *the café where we first met*\n- **whose**: sahiplik: *the boy whose dog is lost*\n\n## Ne zaman atlanabilir?\nRelative pronoun cümlenin **nesnesiyse** atılabilir:\n*The film (that) we watched was great.* ✓\nÖznesiyse atılamaz: *The man **who** called you…* ✓\n\n> Higo\'nun ipucu: Türkçede sıfat cümlesi ismin önüne gelir (dün izlediğimiz film), İngilizcede **arkasına**: *the film we watched yesterday*.','#22B573',6,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(25,3,'İş Dünyası','Gerund / infinitive ve resmî e-posta','## İş hayatında İngilizce\nB1\'in son ünitesinde iş hayatında sık geçen kalıpları, **gerund ve infinitive** kullanımını ve resmî e-posta yazmayı öğreneceksin. Ünite sonunda **B1 seviye sınavı** var.\n\n## Gerund (-ing) alan fiiller\n**enjoy, avoid, finish, mind, suggest, consider, look forward to**\n*I look forward to hearing from you. Would you mind waiting?*\n\n## Infinitive (to + fiil) alan fiiller\n**want, decide, plan, hope, agree, offer, refuse, would like**\n*We decided to hire her. I\'d like to apply for the position.*\n\n## Resmî e-posta kalıpları\n- Başlangıç: *Dear Mr Smith, / Dear Sir or Madam,*\n- Amaç: *I am writing to apply for…*\n- Rica: *Could you please send me…?* / *I would be grateful if…*\n- Kapanış: *I look forward to hearing from you. / Kind regards,*\n\n> Higo\'nun ipucu: **look forward to** kalıbındaki **to** bir edattır, bu yüzden arkasından -ing gelir: ~~look forward to hear~~ → *look forward to hearing*.','#FFB400',7,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(26,4,'Keşke Olsaydı','Third conditional ve geçmişle ilgili pişmanlıklar','## Geçmişi değiştirebilseydik\nBu ünitede geçmişteki gerçekleşmemiş durumları **third conditional**, **wish + past perfect** ve **should have** ile konuşacağız.\n\n## Third conditional\n**If + past perfect, would have + V3**\n*If I had left earlier, I wouldn\'t have missed the train.* (Erken çıkmadım, treni kaçırdım.)\n\n## Mixed conditional\nGeçmişteki bir koşulun bugünkü sonucu:\n*If I had studied medicine, I would be a doctor now.*\n\n## wish / should have\n- *I wish I had listened to you.* (Keşke seni dinleseydim.)\n- *You should have told me.* (Bana söylemeliydin.)\n- *I shouldn\'t have eaten so much.*\n\n> Higo\'nun ipucu: Konuşmada **would have** çoğu zaman **would\'ve** gibi kısalır, kulağa \"would of\" gibi gelir. Yazıda asla \"of\" yazma.','#8F7CF8',0,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(27,4,'Tahmin ve Çıkarım','Modals of deduction: must, might, can\'t (have)','## Dedektif gibi düşün\nBu ünitede kanıta dayanarak **tahmin ve çıkarım** yapmayı öğreneceksin.\n\n## Şimdi için\n- **must**: neredeyse eminim (olumlu): *She must be tired. She\'s been working all day.*\n- **might / may / could**: belki: *He might be at the gym.*\n- **can\'t**: imkânsız: *That can\'t be Ali. He\'s in Germany.*\n\n## Geçmiş için: modal + have + V3\n- *They **must have left** already. The lights are off.*\n- *She **might have missed** the bus.*\n- *He **can\'t have seen** the message. He didn\'t reply.*\n\n> Higo\'nun ipucu: Olumsuz kesin çıkarımda **mustn\'t** değil **can\'t** kullanılır. ~~He mustn\'t be at home~~ → *He can\'t be at home.*','#5B6CF0',1,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(28,4,'Bilim ve Teknoloji','İleri passive ve have something done','## Bilimsel dil\nBilim ve teknoloji metinlerinde edilgen yapı her yerdedir. Bu ünitede **ileri passive** yapılarını ve **have something done** kalıbını göreceksin. Bunlar YDS ve YÖKDİL okuma parçalarında çok sık çıkar.\n\n## Passive + modal\n*The results **can be explained** by… · The data **must be checked**.*\n\n## It is said / believed that…\n*It is believed that the first computer was built in 1945.*\n*The city **is said to be** the oldest in the world.*\n\n## have / get something done\nBir işi başkasına yaptırmak:\n*I had my phone repaired. She\'s getting her hair cut tomorrow.*\n\n> Higo\'nun ipucu: Akademik metinde \"we, I\" yerine passive kullanılır: *The samples were analysed…* Okurken önce **ne yapıldığını** bul, kimin yaptığını sonra düşün.','#22B5C0',2,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(29,4,'Çevre','Future continuous, future perfect ve kalıp sözler','## 2050\'de dünya\nBu ünitede çevre konularını konuşurken **future continuous** ve **future perfect** kullanacaksın.\n\n## Future continuous\n**will be + fiil-ing**: gelecekte belli bir anda sürüyor olacak eylem.\n*This time next year, I\'ll be studying in Ankara.*\n\n## Future perfect\n**will have + V3**: gelecekte belli bir zamana kadar tamamlanmış olacak eylem.\n*By 2030, the city will have planted a million trees.*\n*By the time you arrive, we\'ll have finished dinner.*\n\n## Çevre kalıpları (collocations)\n**reduce waste** · **renewable energy** · **carbon footprint** · **climate change** · **endangered species** · **take action**\n\n> Higo\'nun ipucu: YDS\'de **by + zaman** ifadesi gördüğünde future perfect ya da past perfect seçeneğini kontrol et. Çoğu zaman cevap oradadır.','#22B573',3,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(30,4,'Fikir Savun','Bağlaçlar: although, despite, whereas, however','## İkna edici konuş ve yaz\nBu ünitede fikirlerini bağlamak ve karşı görüşü kabul edip yine de savunmak için **bağlaçları** kullanacaksın. Bu yapılar YDS ve YDT\'nin bağlaç sorularının tam kalbidir.\n\n## Zıtlık\n- **although / even though** + cümle: *Although it was raining, we went out.*\n- **despite / in spite of** + isim ya da -ing: *Despite the rain, we went out. Despite being tired, she finished.*\n- **however** (iki cümle arasında): *The plan is cheap. However, it will take time.*\n- **whereas / while** (karşılaştırma): *I love tea, whereas my sister prefers coffee.*\n\n## Sebep ve sonuç\n**because of / due to** + isim · **therefore / as a result** (cümle başında) · **so that** (amaç)\n\n## Fikir bildirme kalıpları\n*In my view… · It could be argued that… · On the other hand… · To sum up…*\n\n> Higo\'nun ipucu: **despite** asla \"of\" ya da cümle almaz: ~~despite of~~, ~~despite it was~~. Cümle gelecekse **despite the fact that** kullan.','#FF8A3D',4,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(31,4,'Toplum ve Şehir','Kibar ifadeler, would rather ve it\'s time','## Toplumu ve şehrini konuş\nBu ünitede toplumsal konuları tartışırken tercih ve öneri bildiren ileri yapıları kullanacaksın.\n\n## would rather / had better\n- **would rather + yalın fiil**: *I\'d rather take the metro than drive.*\n- Başkası için: **would rather + kişi + past simple**: *I\'d rather you didn\'t smoke here.*\n- **had better** (uyarı): *You\'d better leave now or you\'ll miss the bus.*\n\n## It\'s (high) time + past simple\nBir şeyin artık yapılması gerektiğini vurgular:\n*It\'s time the city built more cycle lanes.*\n\n## Kibar ve dolaylı ifadeler\n- *Could you tell me where the town hall is?* (soru düzeni bozulur)\n- *I was wondering if you could help me.*\n- *Would you mind explaining that again?*\n\n> Higo\'nun ipucu: Dolaylı sorularda yardımcı fiil öne gelmez: ~~Could you tell me where is the station?~~ → *where the station is*.','#3A6FF7',5,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(32,4,'Akademik İngilizce','Akademik okuma, YDS / YÖKDİL kalıpları','## Sınav metinlerini çöz\nBu ünite YDS, YDT ve YÖKDİL\'deki okuma ve paragraf sorularına hazırlar. Akademik metnin yapısını, sık kelimeleri ve soru tiplerini göreceksin.\n\n## Akademik metnin yapısı\n1. **Topic sentence**: paragrafın ana fikri, çoğunlukla ilk cümle.\n2. **Supporting sentences**: örnek, veri, açıklama.\n3. **Concluding sentence**: özet ya da geçiş.\n\n## Sinyal kelimeleri\n- Ekleme: **furthermore, moreover, in addition**\n- Zıtlık: **however, nevertheless, on the contrary**\n- Sonuç: **consequently, thus, hence**\n- Örnek: **for instance, such as, namely**\n\n## Soru tipleri\n- **Ana fikir**: \"The passage is mainly about…\"\n- **Paragraf tamamlama**: boşluktan önceki ve sonraki cümlenin bağlacına bak.\n- **Anlamca en yakın cümle**: zaman ve olumsuzluğu kontrol et.\n\n> Higo\'nun ipucu: Bilmediğin kelimede durma. Önce cümlenin öznesini ve fiilini bul, sonra sinyal kelimesine bak. Anlamın çoğu oradadır.','#2F7CF6',6,'2026-10-03 04:21:53','2026-10-03 04:21:53'),
(33,4,'Kültür ve Medya','Phrasal verbs, deyimler ve doğal İngilizce','## Doğal İngilizce\nB2\'nin son ünitesinde dizilerde, şarkılarda ve günlük konuşmada sık geçen **phrasal verbs** ve **deyimleri** öğreneceksin. Ünite sonunda **B2 seviye sınavı** var.\n\n## Phrasal verbs\nFiil + edat birleşip yeni bir anlam kazanır:\n- **look after**: bakmak (çocuğa, eve)\n- **give up**: vazgeçmek, bırakmak\n- **turn down**: reddetmek; sesini kısmak\n- **come up with**: (fikir) bulmak\n- **put off**: ertelemek\n- **find out**: öğrenmek, keşfetmek\n\nAyrılabilen fiillerde zamir ortaya girer: *Turn it down.* (~~Turn down it~~)\n\n## Sık deyimler\n- **break the ice**: buzları kırmak\n- **a piece of cake**: çocuk oyuncağı\n- **once in a blue moon**: kırk yılda bir\n- **hit the books**: sıkı çalışmak\n\n> Higo\'nun ipucu: Phrasal verb\'leri listeden ezberleme. Bir dizi izlerken ya da hikâye okurken gördüğünde Kelime defterine kaydet; aralıklı tekrar gerisini halleder.','#FF7FB0',7,'2026-10-03 04:21:53','2026-10-03 04:21:53');
